(143, 3, 'Tablice i Metody Funkcyjne', 'Jaka metoda odwraca kolejność elementów tablicy BEZ modyfikacji oryginału (ES2023)?', null, 'single-choice', '["toReversed()","reverse()","reversed()","flip()"]'::jsonb, 0, 'Klasyczna metoda reverse() mutuje tablicę na miejscu, natomiast nowa metoda toReversed() zwraca odwróconą kopię tablicy.', 'easy', 10),
(144, 3, 'Tablice i Metody Funkcyjne', 'Co zwraca metoda pop() wywołana na pustej tablicy []?', 'console.log([].pop());', 'output-predict', '["undefined","null","IndexOutOfBoundsException","0"]'::jsonb, 0, 'Gdy tablica jest pusta, metoda pop() (oraz shift()) nie zgłasza błędu, lecz bezpiecznie zwraca wartość undefined.', 'easy', 10),
(145, 3, 'Tablice i Metody Funkcyjne', 'Co robi metoda .copyWithin()?', 'const arr = [1, 2, 3, 4, 5];
arr.copyWithin(0, 3);
console.log(arr);', 'output-predict', '["[4, 5, 3, 4, 5] (kopiuje sekwencję elementów w inne miejsce wewnątrz tej samej tablicy bez zmiany długości)","[3, 4, 5, 1, 2]","[4, 5]","TypeError"]'::jsonb, 0, 'copyWithin(target, start, end) to wydajna metoda niskopoziomowa, która kopiuje wycinek tablicy w inne miejsce tej samej tablicy in-place.', 'hard', 20),
(146, 3, 'Tablice i Metody Funkcyjne', 'Czym są TypedArrays (np. Uint8Array, Float64Array) w JavaScript?', null, 'single-choice', '["Niskopoziomowymi tablicami o stałym rozmiarze przechowującymi surowe dane binarne w buforze ArrayBuffer o określonym typie liczbowym","Tablicami tylko dla kodu TypeScript","Tablicami z typowaniem asynchronicznym","Zwykłymi tablicami z walidacją typeof"]'::jsonb, 0, 'TypedArrays reprezentują widoki (views) na ciągły bufor pamięci bajtowej (ArrayBuffer). Są wysoce zoptymalizowane do operacji graficznych (WebGL), dźwiękowych i sieciowych.', 'medium', 15),
(147, 3, 'Tablice i Metody Funkcyjne', 'Co się stanie przy próbie zapisu liczby 300 do 8-bitowej tablicy bez znaku Uint8Array?', 'const u8 = new Uint8Array(1);
u8[0] = 300;
console.log(u8[0]);', 'output-predict', '["44 (wynik modulo 256: 300 & 0xFF)","300","RangeError","255"]'::jsonb, 0, 'Uint8Array mieści tylko liczby od 0 do 255. Następuje obcięcie bitowe (overflow): 300 % 256 = 44.', 'hard', 20),
(148, 3, 'Tablice i Metody Funkcyjne', 'Co w silnikach JS (np. V8) oznacza pojęcie "PACKED_SMI_ELEMENTS" vs "HOLEY_ELEMENTS"?', null, 'single-choice', '["Wewnętrzną optymalizację reprezentacji tablic: PACKED oznacza zwartą tablicę bez dziur i jest najszybsza, HOLEY oznacza tablicę z pustymi slotami, która zwalnia dostęp","Format zapisu w localStorage","Rodzaje błędów pamięci","Zmienne w silniku Node.js"]'::jsonb, 0, 'Silnik V8 klasyfikuje tablice na tzw. Elements Kinds. Tablica gęsta (packed) z małymi liczbami całkowitymi (SMI) działa z szybkością kodu maszynowego C++. Puste sloty powodują degradację optymalizacji.', 'hard', 20),
(149, 3, 'Tablice i Metody Funkcyjne', 'Jaka jest złożoność obliczeniowa (Big-O) metody arr.unshift() w porównaniu do arr.push() dla tablicy o n elementach?', null, 'single-choice', '["push() to O(1) amortyzowane, a unshift() to O(n), ponieważ wymaga przesunięcia wszystkich istniejących elementów o jeden indeks w prawo","Obie metody to O(1)","Obie metody to O(n)","unshift to O(log n)"]'::jsonb, 0, 'push dodaje na koniec tablicy (O(1)). unshift musi zmienić indeksy wszystkich dotychczasowych n elementów, co wymaga operacji O(n).', 'medium', 15),
(150, 3, 'Tablice i Metody Funkcyjne', 'Jaki wynik zwróci wywołanie metody .keys() i .values() na tablicy?', 'const arr = ["x", "y"];
console.log([...arr.keys()]);
console.log([...arr.values()]);', 'output-predict', '["[0, 1] oraz [\"x\", \"y\"]","[\"x\", \"y\"] oraz [0, 1]","[0, 1] oraz [0, 1]","TypeError"]'::jsonb, 0, 'keys() zwraca iterator po indeksach tablicy ([0, 1]), a values() po jej zawartych wartościach (["x", "y"]).', 'easy', 10),
(151, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak zdefiniować właściwość obiektu o dynamicznej nazwie wyliczonej w locie (Computed Property Name)?', 'const klucz = "rola";
const uzytkownik = {
  imie: "Ewa",
  ???: "admin"
};', 'fill-gap', '["[klucz]","{klucz}","(klucz)","$klucz"]'::jsonb, 0, 'W ES6 nawiasy kwadratowe wewnątrz literału obiektu [klucz] oznaczają, że nazwa właściwości ma zostać obliczona z wartości wyrażenia.', 'easy', 10),
(152, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co zwraca metoda Object.entries(obiekt)?', 'const obj = { a: 1, b: 2 };
console.log(Object.entries(obj));', 'output-predict', '["Tablicę par klucz-wartość: [[\"a\", 1], [\"b\", 2]]","[\"a\", \"b\"]","[1, 2]","{ a: 1, b: 2 }"]'::jsonb, 0, 'Metoda Object.entries() zwraca tablicę dwuelementowych tablic [klucz, wartość] dla wszystkich przeliczalnych własnych właściwości obiektu.', 'easy', 10),
(153, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka metoda odwraca działanie Object.entries() i przekształca listę par [klucz, wartość] z powrotem w obiekt?', 'const pary = [["x", 10], ["y", 20]];
const obj = Object.???(pary);', 'fill-gap', '["fromEntries","toObject","assign","create"]'::jsonb, 0, 'Wprowadzona w ES2019 metoda Object.fromEntries(iterable) przekształca listę par [klucz, wartość] w pełnoprawny obiekt JavaScript.', 'medium', 15),
(154, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak bezpiecznie usunąć właściwość z obiektu?', 'const auto = { marka: "Fiat", model: "500" };
delete auto.model;
console.log(auto);', 'output-predict', '["{ marka: \"Fiat\" }","{ marka: \"Fiat\", model: undefined }","TypeError","{ marka: \"Fiat\", model: null }"]'::jsonb, 0, 'Operator "delete" całkowicie usuwa właściwość z obiektu (zarówno klucz, jak i wartość znikają z definicji obiektu).', 'easy', 10),
(155, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Dlaczego w nowoczesnym kodzie preferuje się Object.hasOwn(obj, prop) zamiast obj.hasOwnProperty(prop)?', null, 'single-choice', '["Ponieważ działa nawet na obiektach utworzonych przez Object.create(null) oraz obiektach, w których właściwość \"hasOwnProperty\" została nadpisana","Ponieważ hasOwn działa 100x szybciej","Ponieważ hasOwnProperty jest usunięte z JS","Nie ma żadnej różnicy"]'::jsonb, 0, 'Obiekty bez prototypu (Object.create(null)) nie mają w łańcuchu metody hasOwnProperty. Rekomendowana statyczna metoda Object.hasOwn() zapobiega błędom TypeError.', 'medium', 15),
(156, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka jest różnica między Object.freeze() a Object.seal()?', null, 'single-choice', '["Object.freeze() uniemożliwia jakąkolwiek zmianę istniejących właściwości, a Object.seal() zabrania dodawania/usuwania właściwości, ale POZWALA na modyfikację istniejących","freeze działa tylko na tablicach","seal jest płytkie, a freeze głębokie","Nie ma żadnej różnicy"]'::jsonb, 0, 'Object.seal() blokuje strukturę obiektu (brak dodawania/usuwania), lecz istniejące właściwości można nadal edytować. Object.freeze() czyni wszystkie właściwości dodatkowo tylko do odczytu (writable: false).', 'medium', 15),
(157, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Czy Object.freeze() zamraża zagnieżdżone obiekty wewnętrzne (deep freeze)?', 'const user = Object.freeze({
  profil: { wiek: 30 }
});
user.profil.wiek = 31;
console.log(user.profil.wiek);', 'output-predict', '["31 (freeze jest operacją płytką - shallow freeze)","30","TypeError","undefined"]'::jsonb, 0, 'Object.freeze() działa wyłącznie płytko na pierwszym poziomie właściwości. Zagnieżdżony obiekt profil pozostaje mutowalny, dopóki nie zostanie zamrożony rekurencyjnie.', 'medium', 15),
(158, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co robi metoda Object.preventExtensions(obj)?', null, 'single-choice', '["Uniemożliwia dodawanie jakichkolwiek nowych właściwości do obiektu","Wyłącza rozszerzenia przeglądarki Chrome","Zabrania dziedziczenia w klasach","Służy do minifikacji kodu"]'::jsonb, 0, 'Object.preventExtensions() sprawia, że obiekt staje się nierozszerzalny – próba dopisania nowego klucza kończy się niepowodzeniem (lub rzuca błąd w strict mode).', 'medium', 15),
(159, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak sprawdzić, czy obiekt jest zamrożony metodą Object.freeze()?', null, 'single-choice', '["Object.isFrozen(obj)","obj.isFrozen()","obj.frozen === true","typeof obj === \"frozen\""]'::jsonb, 0, 'Statyczna metoda Object.isFrozen(obj) zwraca true, jeśli obiekt nie pozwala na dodawanie właściwości, a wszystkie istniejące są nielogiczne do modyfikacji i usunięcia.', 'easy', 10),
(160, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie przy próbie modyfikacji zamrożonego obiektu w trybie ścisłym ("use strict")?', '"use strict";
const o = Object.freeze({ x: 1 });
o.x = 2;', 'output-predict', '["TypeError: Cannot assign to read only property","Operacja zostanie zignorowana bez błędu","SyntaxError","o.x zmieni się na 2"]'::jsonb, 0, 'W trybie "use strict" próba zapisu do właściwości tylko do odczytu rzuca wyjątek TypeError.', 'easy', 10),
(161, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jakie są cztery podstawowe atrybuty deskryptora danych (Data Descriptor)?', null, 'single-choice', '["value, writable, enumerable, configurable","key, value, type, size","get, set, run, stop","name, proto, length, scope"]'::jsonb, 0, 'Deskryptor danych zawiera: value (wartość), writable (możliwość zmiany wartości), enumerable (widoczność w pętlach for...in) oraz configurable (możliwość zmiany deskryptora lub usunięcia).', 'medium', 15),
(162, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co oznacza flaga enumerable: false w deskryptorze właściwości obiektu?', 'Object.defineProperty(obj, "id", {
  value: 123,
  enumerable: false
});', 'single-choice', '["Właściwość jest ukryta przed iteracją w for...in oraz pomijana przez Object.keys() i JSON.stringify()","Właściwość nie może zostać odczytana","Wartość właściwości wynosi false","Właściwość jest prywatna w TypeScript"]'::jsonb, 0, 'Właściwości nieprzeliczalne (non-enumerable) nie pojawiają się w Object.keys(), Object.entries() ani podczas serializacji do JSON.', 'medium', 15),
(163, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie po ustawieniu configurable: false na właściwości obiektu?', null, 'single-choice', '["Właściwości nie można usunąć operatorem delete ani nie można zmienić jej deskryptora (poza flagą writable z true na false)","Obiekt nie może zostać skonfigurowany","Właściwość staje się funkcją","Obiekt traci prototyp"]'::jsonb, 0, 'configurable: false to trwała blokada usunięcia właściwości i rekonfiguracji jej deskryptora.', 'hard', 20),
(164, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak odczytać pełny deskryptor właściwości obiektu?', null, 'single-choice', '["Object.getOwnPropertyDescriptor(obj, \"nazwa\")","obj.getDescriptor(\"nazwa\")","Object.descriptor(obj)","obj.__descriptor__"]'::jsonb, 0, 'Metoda Object.getOwnPropertyDescriptor(obj, prop) zwraca obiekt ze stanem flag value, writable, enumerable i configurable.', 'easy', 10),
(165, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jakie wartości domyślne przyjmują flagi writable, enumerable i configurable w Object.defineProperty, jeśli ich nie podamy?', 'Object.defineProperty(obj, "test", { value: 42 });', 'output-predict', '["false, false, false (wszystkie domyślnie przyjmują fałsz!)","true, true, true","true, false, true","undefined"]'::jsonb, 0, 'W przeciwieństwie do tworzenia właściwości kropką (obj.test = 42 daje domyślnie true), defineProperty domyślnie ustawia wszystkie niepodane flagi logiczne na false.', 'hard', 20),
(166, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co wskazuje "this" przy niejawnym wywołaniu metody na obiekcie (Implicit Binding)?', 'const user = {
  imie: "Marta",
  przedstawSie() { return this.imie; }
};
console.log(user.przedstawSie());', 'output-predict', '["\"Marta\" (this wskazuje na obiekt po lewej stronie kropki: user)","undefined","window/global","TypeError"]'::jsonb, 0, 'W wywołaniu obiekt.metoda() obiekt przed kropką stanowi kontekst this w momencie wywołania.', 'easy', 10),
(167, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Słynna utrata kontekstu (Losing this): Co wypisze poniższy kod po przypisaniu metody do osobnej zmiennej?', 'const user = {
  imie: "Jan",
  say() { return this ? this.imie : "brak"; }
};
const fn = user.say;
console.log(fn());', 'output-predict', '["undefined (lub błąd w strict mode, ponieważ wywołanie fn() to wywołanie domyślne bez kontekstu)","\"Jan\"","\"user\"","SyntaxError"]'::jsonb, 0, 'Przypisanie metody do zmiennej odrywa referencję od obiektu user. Samodzielne wywołanie fn() korzysta z Default Binding (wskazuje na obiekt globalny lub undefined w strict mode).', 'medium', 15),
(168, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co wskazuje "this" w zwykłej funkcji wywołanej w trybie ścisłym ("use strict") bez żadnego obiektu kontekstu?', '"use strict";
function test() { return this; }
console.log(test());', 'output-predict', '["undefined","obiekt globalny window / global","null","{}"]'::jsonb, 0, 'W trybie ścisłym silnik JS nie podstawia obiektu globalnego pod niepowiązany "this", lecz pozostawia go jako undefined.', 'easy', 10),
(169, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Które wiązanie kontekstu "this" ma najwyższy priorytet?', null, 'single-choice', '["Wiązanie konstruktora ze słowem kluczowym \"new\" (new binding)","Wiązanie jawne (.bind/.call/.apply)","Wiązanie niejawne (obj.method())","Wiązanie domyślne (globalne)"]'::jsonb, 0, 'Hierarchia priorytetów: new > bind/call/apply > kontekst obiektu (obj.method) > domyślne (global/undefined). Funkcje strzałkowe stoją poza tą hierarchią (wiązanie leksykalne).', 'hard', 20),
(170, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co wypisze poniższy kod łączący funkcję strzałkową wewnątrz tradycyjnej metody obiektu?', 'const kalkulator = {
  mnoznik: 3,
  licz(arr) {
    return arr.map(x => x * this.mnoznik);
  }
};
console.log(kalkulator.licz([2, 4]));', 'output-predict', '["[6, 12]","[NaN, NaN]","TypeError","undefined"]'::jsonb, 0, 'Funkcja strzałkowa dziedziczy "this" z otaczającej metody licz(), w której this wskazuje na kalkulator. Dzięki temu this.mnoznik jest równe 3.', 'easy', 10),
(171, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Czym kończy się każdy standardowy łańcuch prototypów w JavaScript?', null, 'single-choice', '["Object.prototype, którego prototypem jest null","Obiektem window","Pustą tablicą []","Klasą Function"]'::jsonb, 0, 'Szczytem łańcucha prototypów w JavaScript jest Object.prototype, a Object.prototype.__proto__ wynosi null, co stanowi definitywny koniec przeszukiwania właściwości.', 'medium', 15),
(172, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak utworzyć obiekt, który jest całkowicie pozbawiony jakiegokolwiek prototypu (tzw. czysty słownik)?', 'const slownik = Object.create(null);
console.log(slownik.toString);', 'output-predict', '["undefined (nie dziedziczy nawet metod z Object.prototype, takich jak toString czy hasOwnProperty)","function toString()","TypeError","{}"]'::jsonb, 0, 'Object.create(null) tworzy obiekt z prototypem null. Jest bezpieczny przed kolizjami kluczy prototypu i atakami prototype pollution.', 'medium', 15),
(173, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka jest nowoczesna i rekomendowana metoda odczytania prototypu danego obiektu?', null, 'single-choice', '["Object.getPrototypeOf(obj)","obj.__proto__","obj.prototype","Object.prototypeOf(obj)"]'::jsonb, 0, 'Object.getPrototypeOf(obj) to standardowa, zoptymalizowana metoda ECMAScript. Właściwość __proto__ jest przestarzała (deprecated legacy accessor).', 'easy', 10),
(174, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka jest różnica między właściwością .prototype a wewnętrznym wskaźnikiem [[Prototype]] (__proto__)?', null, 'single-choice', '["Właściwość .prototype występuje na funkcjach-konstruktorach i staje się prototypem dla obiektów tworzonych przez \"new\", a [[Prototype]] to faktyczny link w obiekcie wskazujący na jego rodzica","To dokładnie to samo","prototype występuje tylko w klasach","[[Prototype]] to zmienna w CSS"]'::jsonb, 0, 'Tylko funkcje konstruujące posiadają jawną właściwość .prototype. Każdy obiekt posiada z kolei wewnętrzne połączenie [[Prototype]] do swojego prototypu.', 'hard', 20),
(175, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Czym jest podatność "Prototype Pollution"?', null, 'single-choice', '["Atakiem polegającym na wstrzyknięciu złośliwych właściwości bezpośrednio do Object.prototype, co zanieczyszcza wszystkie obiekty w całej aplikacji","Zapełnieniem pamięci RAM","Zniszczeniem drzewa DOM","Wyciekiem kluczy SSH"]'::jsonb, 0, 'Prototype Pollution to poważna luka bezpieczeństwa, w której atakujący modyfikuje Object.prototype (np. przez nieostrożne scalanie jsona z kluczem __proto__), wpływając na logikę całego programu.', 'hard', 20),
(176, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jakie słowo kluczowe w klasie pochodnej (extends) MUSI zostać wywołane przed jakimkolwiek odwołaniem do "this"?', 'class Pies extends Zwierze {
  constructor(imie, rasa) {
    ???(imie);
    this.rasa = rasa;
  }
}', 'fill-gap', '["super","parent","base","root"]'::jsonb, 0, 'W klasach potomnych wywołanie super(...args) wykonuje konstruktor klasy bazowej i inicjalizuje instancję "this". Próba odczytania this przed super rzuca ReferenceError.', 'easy', 10),
(177, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Czym są klasy wprowadzone w standardzie ES6 pod maską silnika JavaScript?', null, 'single-choice', '["Lukrem składniowym (syntactic sugar) nad istniejącym prototypowym modelem dziedziczenia JavaScript","Całkowicie nową maszyną wirtualną w C++","Osobnym wątkiem Web Worker","Mechanizmem kompilowanym do kodu binarnego"]'::jsonb, 0, 'Klasy w JS są w rzeczywistości funkcjami (typeof Klasa === "function") i opierają się na tradycyjnych łańcuchach prototypów.', 'easy', 10),
(178, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie przy próbie wywołania klasy jak zwykłej funkcji bez słowa kluczowego "new"?', 'class Samochod {}
Samochod();', 'output-predict', '["TypeError: Class constructor Samochod cannot be invoked without \"new\"","undefined","Tworzy pusty obiekt","ReferenceError"]'::jsonb, 0, 'W przeciwieństwie do tradycyjnych funkcji konstruujących, klasy ES6 posiadają wewnętrzne zabezpieczenie i rzucają TypeError, gdy zostaną wywołane bez operatora new.', 'medium', 15),
(179, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Czy klasy podlegają hoistingowi w taki sam sposób jak tradycyjne deklaracje funkcji?', 'const a = new Test();
class Test {}', 'output-predict', '["ReferenceError: Cannot access \"Test\" before initialization (podlegają TDZ podobnie jak let i const)","Działa poprawnie","TypeError","undefined"]'::jsonb, 0, 'Deklaracje klas są w Temporal Dead Zone przed ich linią deklaracji i rzucają ReferenceError przy próbie użycia przed zadeklarowaniem.', 'medium', 15),
(180, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co sprawdza operator instanceof w JavaScript?', 'p instanceof Pies;', 'single-choice', '["Czy właściwość prototype danego konstruktora znajduje się gdziekolwiek w łańcuchu prototypów sprawdzanego obiektu","Tylko dokładną nazwę klasy","Wielkość obiektu w bajtach","Czy obiekt ma te same klucze"]'::jsonb, 0, 'Operator a instanceof B sprawdza, czy B.prototype występuje w łańcuchu prototypów obiektu a.', 'medium', 15),
(181, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak zadeklarować prawdziwie prywatne pole w klasie w nowoczesnym standardzie JavaScript?', 'class Konto {
  ???saldo = 0;
}', 'fill-gap', '["# (np. #saldo)","private","_ (np. _saldo)","protected"]'::jsonb, 0, 'Znak krzyżyka (#) definiuje prywatne pole instancji egzekwowane na poziomie silnika JS. Próba dostępu do obiektu z zewnątrz (#saldo) wyrzuca SyntaxError.', 'easy', 10),
(182, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Do czego służy słowo kluczowe "static" przed metodą lub polem w klasie?', 'class Narzedzia {
  static wersja = "1.0.0";
  static loguj() { return "OK"; }
}', 'single-choice', '["Wiąże metodę/właściwość bezpośrednio z samą klasą (funkcją konstruktora), a nie z jej poszczególnymi instancjami","Zamraża obiekt na stałe","Tworzy metodę asynchroniczną","Ukrywa metodę"]'::jsonb, 0, 'Metody i pola statyczne wywołuje się bezpośrednio na klasie (Narzedzia.loguj()), a nie na obiektach utworzonych przez new.', 'easy', 10),
(183, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Do czego służą akcesory "get" i "set" (gettery i settery) w obiektach i klasach?', 'const koło = {
  promien: 5,
  get pole() { return Math.PI * this.promien ** 2; }
};
console.log(koło.pole);', 'single-choice', '["Pozwalają na powiązanie właściwości z funkcją wywoływaną automatycznie podczas odczytu lub zapisu, z zachowaniem składni zwykłej właściwości (bez nawiasów ())","Służą do wysyłania żądań HTTP GET i POST","Są używane tylko w TypeScript","Zwiększają zużycie pamięci"]'::jsonb, 0, 'Getter pozwala odczytywać właściwość jak zwykłą zmienną (koło.pole), wykonując pod spodem zdefiniowaną logikę kalkulacji.', 'easy', 10),
(184, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie przy próbie odczytania prywatnego pola #tajne z zewnątrz instancji klasy?', 'class Skarbiec {
  #tajne = "haslo123";
}
const s = new Skarbiec();
console.log(s.#tajne);', 'output-predict', '["SyntaxError: Private field \"#tajne\" must be declared in an enclosing class","undefined","\"haslo123\"","null"]'::jsonb, 0, 'Prywatne pola (#) mają twarde zabezpieczenie w silniku i ich niepoprawne użycie jest wyłapywane już na etapie parsowania kodu jako błąd składni (SyntaxError).', 'medium', 15),
(185, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co oznacza statyczny blok inicjalizacyjny (Static Initialization Block) w klasie (ES2022)?', 'class Baza {
  static dane;
  static {
    Baza.dane = "Zainicjalizowano";
  }
}', 'single-choice', '["Blok kodu wykonujący się dokładnie jeden raz w momencie definiowania/parsowania klasy, pozwalający na skomplikowaną logikę inicjalizacji pól statycznych","Blok uruchamiany przy każdym new","Zabezpieczenie przed atakami","Funkcję asynchroniczną"]'::jsonb, 0, 'Bloki static { ... } wykonują się natychmiast podczas inicjalizacji samej klasy i mają dostęp nawet do prywatnych pól statycznych.', 'hard', 20),
(186, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jakie 4 kroki wykonuje silnik JavaScript, gdy używamy operatora "new Konstruktor()"?', null, 'single-choice', '["1. Tworzy pusty obiekt, 2. Łączy prototyp z Konstruktor.prototype, 3. Wiąże this z nowym obiektem i wykonuje konstruktor, 4. Zwraca ten obiekt (chyba że konstruktor zwróci inny obiekt)","Tylko klonuje funkcję","Rejestruje obiekt w DOM","Pobiera pamięć z pliku"]'::jsonb, 0, 'To fundamentalny mechanizm działania "new" w specyfikacji ECMAScript.', 'hard', 20),
(187, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co zwraca meta-właściwość "new.target" wewnątrz funkcji wywołanej bez słowa kluczowego "new"?', 'function Test() {
  console.log(new.target);
}
Test();', 'output-predict', '["undefined","funkcję Test","null","false"]'::jsonb, 0, 'new.target pozwala wykryć, czy funkcja lub konstruktor został uruchomiony za pomocą operatora new. Jeśli wywołano go tradycyjnie, new.target ma wartość undefined.', 'medium', 15),
(188, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie, jeśli konstruktor wywołany przez "new" jawnie zwróci prymityw (np. return 42)?', 'function Moja() {
  this.x = 10;
  return 42;
}
const m = new Moja();
console.log(m.x);', 'output-predict', '["10 (zwrócenie prymitywu z konstruktora jest ignorowane przez operator new)","42","undefined","TypeError"]'::jsonb, 0, 'Jeśli konstruktor wywołany przez new zwraca wartość prymitywną (liczbę, string, boolean), zostaje ona zignorowana i silnik zwraca nowo utworzony obiekt (this).', 'hard', 20),
(189, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'A co się stanie, jeśli konstruktor wywołany przez "new" zwróci INNY obiekt (np. return { inny: true })?', 'function Fabryka() {
  this.a = 1;
  return { b: 2 };
}
const f = new Fabryka();
console.log(f.a, f.b);', 'output-predict', '["undefined 2 (zwrócenie obiektu zastępuje utworzoną instancję)","1 2","1 undefined","TypeError"]'::jsonb, 0, 'Jeśli konstruktor jawnie zwróci obiekt (Object, Array itp.), ten obiekt staje się ostatecznym wynikiem wyrażenia new, a utworzony wcześniej obiekt this jest odrzucany.', 'hard', 20),
(190, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak napisać funkcję konstruktora, która automatycznie działa poprawnie nawet bez użycia słowa "new"?', 'function User(imie) {
  if (!new.target) return new User(imie);
  this.imie = imie;
}', 'single-choice', '["Sprawdzając warunek !new.target i wywołując rekurencyjnie new User(...)","Używając try...catch","Deklarując funkcję strzałkową","Nie jest to możliwe"]'::jsonb, 0, 'Sprawdzenie !new.target pozwala na bezpieczną autokonstrukcję (np. tak jak działa funkcja RegExp() lub Error()).', 'medium', 15),
(191, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka wbudowana metoda w nowoczesnych przeglądarkach i Node.js służy do bezpiecznego głębokiego klonowania (Deep Clone)?', 'const glebokaKopia = ???(oryginalnyObiekt);', 'fill-gap', '["structuredClone","deepClone","Object.clone","JSON.clone"]'::jsonb, 0, 'Natywna funkcja structuredClone() obsługuje głębokie klonowanie obiektów zagnieżdżonych, struktur cyklicznych oraz typów takich jak Date, Set, Map, RegExp czy TypedArray.', 'medium', 15),
(192, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaki jest główny minus klonowania obiektów za pomocą triku JSON.parse(JSON.stringify(obj))?', null, 'single-choice', '["Gubi funkcje, wartości undefined, symbole oraz konwertuje obiekty Date na zwykłe stringi, a przy referencjach cyklicznych rzuca TypeError","Działa za szybko","Zmienia kolory w konsoli","Działa tylko w plikach tekstowych"]'::jsonb, 0, 'Serializacja JSON nie obsługuje wielu typów JS (funkcje, undefined, Map, Set, BigInt, Date jako obiekt) i załamuje się przy referencjach cyklicznych.', 'medium', 15),
(193, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co robi metoda Object.assign(cel, ...zrodla)?', 'const cel = { a: 1 };
Object.assign(cel, { b: 2 }, { c: 3 });
console.log(cel);', 'output-predict', '["{ a: 1, b: 2, c: 3 } (kopiuje przeliczalne właściwości do obiektu docelowego i mutuje go)","{ a: 1 }","{ b: 2, c: 3 }","TypeError"]'::jsonb, 0, 'Object.assign() kopiuje właściwości ze wszystkich źródeł do obiektu docelowego "cel" (który jest mutowany) i zwraca go.', 'easy', 10),
(194, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co się stanie, jeśli dwa obiekty scalane operatorem spread ({ ...a, ...b }) mają klucz o tej samej nazwie?', 'const a = { x: 1, y: 2 };
const b = { y: 99, z: 3 };
console.log({ ...a, ...b });', 'output-predict', '["{ x: 1, y: 99, z: 3 } (właściwość z późniejszego obiektu b nadpisuje wcześniejszą)","{ x: 1, y: 2, z: 3 }","SyntaxError","{ x: 1, y: [2, 99], z: 3 }"]'::jsonb, 0, 'Właściwości są przypisywane w kolejności występowania – klucze z prawej strony nadpisują te z lewej strony.', 'easy', 10),
(195, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak porównać dwa obiekty pod kątem ich zawartości (płytkie porównanie / shallow equal)?', null, 'single-choice', '["Sprawdzając, czy mają tę samą liczbę kluczy i czy wartości wszystkich właściwości są ściśle równe (a[k] === b[k])","Używając operatora a === b","Używając a == b","Za pomocą typeof a === typeof b"]'::jsonb, 0, 'Operator === na obiektach bada wyłącznie tożsamość referencji w pamięci ({ a: 1 } === { a: 1 } to false). Płytkie porównanie wymaga weryfikacji kluczy i ich wartości.', 'medium', 15),
(196, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Do czego służy wbudowany obiekt Proxy w JavaScript?', 'const p = new Proxy(cel, handler);', 'single-choice', '["Pozwala na przechwytywanie i modyfikowanie fundamentalnych operacji na obiekcie (np. odczytu get, zapisu set, usuwania właściwości)","Do konfiguracji serwerów proxy sieciowych","Do szyfrowania ciasteczek HTTP","Do renderowania animacji w CSS"]'::jsonb, 0, 'Proxy pozwala na tworzenie nakładek na obiekty, w których tzw. pułapki (traps) przechwytują operacje odczytu, zapisu, iteracji i wywołań.', 'hard', 20),
(197, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jaka pułapka (trap) w Proxy odpowiada za przechwycenie odczytu właściwości (obj.prop)?', null, 'single-choice', '["get(target, prop, receiver)","read(target, prop)","fetch(prop)","lookup(prop)"]'::jsonb, 0, 'Pułapka get(target, prop, receiver) przechwytuje każdy dostęp do właściwości obiektu i może zwrócić dowolną przetworzoną wartość.', 'medium', 15),
(198, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Do czego służy wbudowany obiekt Reflect w parze z Proxy?', null, 'single-choice', '["Udostępnia metody do wykonywania domyślnych zachowań silnika odpowiadające dokładnie pułapkom Proxy (np. Reflect.get, Reflect.set)","Służy do tworzenia lustrzanych odbić grafiki","Do refleksji kodu w języku C#","Do usuwania obiektów z pamięci"]'::jsonb, 0, 'Reflect zawiera metody ułatwiające przekazywanie domyślnej implementacji operacji wewnątrz pułapek Proxy z poprawnym przekazaniem kontekstu receiver.', 'hard', 20),
(199, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Co wypisze poniższe Proxy z pułapką wartości domyślnej dla nieistniejących właściwości?', 'const user = { imie: "Kasia" };
const proxy = new Proxy(user, {
  get(target, prop) {
    return prop in target ? target[prop] : "Nie podano";
  }
});
console.log(proxy.wiek);', 'output-predict', '["\"Nie podano\"","undefined","ReferenceError","null"]'::jsonb, 0, 'Ponieważ klucz "wiek" nie istnieje w obiekcie user, pułapka get zwraca zdefiniowaną wartość zastępczą "Nie podano".', 'medium', 15),
(200, 4, 'Obiekty, Słowo "this" i Klasy ES6', 'Jak utworzyć odwoływalne (revocable) Proxy, które można w dowolnym momencie wyłączyć?', null, 'single-choice', '["Proxy.revocable(target, handler)","proxy.revoke()","new RevocableProxy(target)","Object.revoke(proxy)"]'::jsonb, 0, 'Proxy.revocable() zwraca obiekt { proxy, revoke }. Wywołanie metody revoke() natychmiast wyłącza Proxy, a każda kolejna próba dostępu rzuca TypeError.', 'hard', 20),
(201, 5, 'Asynchroniczność i Event Loop', 'Czy silnik wykonawczy JavaScript (wątek główny) jest jednowątkowy czy wielowątkowy?', null, 'single-choice', '["Jest jednowątkowy (posiada jeden stos wywołań Call Stack i jedno środowisko pamięci)","Jest w pełni wielowątkowy z automatycznym zrównoleglaniem na 8 rdzeni","Posiada osobny wątek dla każdej funkcji","Nie posiada wątków"]'::jsonb, 0, 'Środowisko wykonawcze JavaScript jest jednowątkowe (Single-Threaded), co oznacza, że może wykonywać tylko jedną instrukcję naraz na głównym stosie wywołań.', 'easy', 10),
(202, 5, 'Asynchroniczność i Event Loop', 'Czym jest Call Stack (stos wywołań) w JavaScript?', null, 'single-choice', '["Strukturą danych LIFO (Last In, First Out), która śledzi, w którym miejscu kodu aktualnie znajduje się program i jakie funkcje zostały wywołane","Kolejką zapytań do bazy danych","Plikiem tymczasowym na dysku","Pamięcią podręczną przeglądarki"]'::jsonb, 0, 'Call Stack kładzie ramki wywoływanych funkcji na szczyt stosu, a po ich zakończeniu (return) zdejmuje je z góry.', 'easy', 10),
(203, 5, 'Asynchroniczność i Event Loop', 'Co się stanie z interfejsem strony, gdy na głównym wątku uruchomimy ciężką pętlę synchroniczną trwającą 10 sekund?', 'const start = Date.now();
while (Date.now() - start < 10000) {}
// Ciężka pętla blokująca', 'single-choice', '["Interfejs ulegnie całkowitemu zamrożeniu (brak reakcji na kliknięcia, brak scrolla i brak renderowania animacji), dopóki pętla się nie zakończy","Przeglądarka przeniesie pętlę automatycznie do wątku w tle","Wyświetli się błąd SyntaxError","Pętla wykona się asynchronicznie"]'::jsonb, 0, 'Blokowanie Call Stacka uniemożliwia Event Loopowi obsłużenie renderowania ekranu i zdarzeń użytkownika (tzw. zawieszenie wątku UI).', 'easy', 10),
(204, 5, 'Asynchroniczność i Event Loop', 'Gdzie w architekturze przeglądarki wykonywane są operacje takie jak timery (setTimeout) czy zapytania sieciowe fetch?', null, 'single-choice', '["W środowisku Web APIs przeglądarki (zewnętrznych wątkach udostępnianych przez silnik przeglądarki)","Wewnątrz czystego silnika V8 na Call Stacku","W pliku index.html","W pamięci karty graficznej GPU"]'::jsonb, 0, 'Timery, operacje I/O i obsługa DOM to interfejsy Web APIs. Przeglądarka zarządza nimi w tle, a po zakończeniu przekazuje callbacki do kolejki zadań.', 'medium', 15),
(205, 5, 'Asynchroniczność i Event Loop', 'Jaka jest rola pętli zdarzeń (Event Loop)?', null, 'single-choice', '["Nieustanne sprawdzanie, czy Call Stack jest pusty, a jeśli tak – pobieranie zadań z kolejki (Microtasks / Macrotasks) i umieszczanie ich na Call Stacku","Pętla zliczająca błędy w kodzie","Mechanizm renderujący pliki SVG","Odpowiednik pętli while w HTML"]'::jsonb, 0, 'Event Loop koordynuje wykonywanie kodu, zbieranie zdarzeń i uruchamianie callbacków z kolejek, dbając o płynność aplikacji.', 'medium', 15),
(206, 5, 'Asynchroniczność i Event Loop', 'Kiedy wykona się callback przekazany do setTimeout(fn, 0)?', 'console.log("A");
setTimeout(() => console.log("B"), 0);
console.log("C");', 'output-predict', '["A, C, a na końcu B (dopiero po całkowitym opróżnieniu synchronicznego Call Stacka)","A, B, C","B, A, C","B, C, A"]'::jsonb, 0, 'Nawet przy opóźnieniu 0 ms callback trafia do kolejki Macrotasków i może zostać uruchomiony dopiero wtedy, gdy stos wywołań zostanie w całości wyczyszczony.', 'easy', 10),
(207, 5, 'Asynchroniczność i Event Loop', 'Jak anulować zaplanowany timer w JavaScript?', 'const timerId = setTimeout(akcja, 5000);
// Jak go zatrzymać?', 'single-choice', '["clearTimeout(timerId)","timerId.stop()","delete timerId","abortTimer(timerId)"]'::jsonb, 0, 'Funkcja clearTimeout(id) (oraz clearInterval dla interwałów) anuluje zaplanowane wykonanie na podstawie zwróconego identyfikatora.', 'easy', 10),
(208, 5, 'Asynchroniczność i Event Loop', 'Dlaczego czas podany w setTimeout(fn, 1000) nie jest gwarancją wykonania dokładnie po 1000 ms?', null, 'single-choice', '["Parametr określa minimalny czas oczekiwania, ale jeśli Call Stack jest zajęty innymi zadaniami, wykonanie callbacka ulegnie opóźnieniu","Bo zegary procesorów mają błędy","Bo silnik losuje opóźnienie","Działa z dokładnością do 1 milisekundy zawsze"]'::jsonb, 0, 'Czas w setTimeout to gwarantowany czas MINIMALNY. Jeśli w momencie upłynięcia 1000 ms na Call Stacku wykonuje się inny kod, callback musi poczekać w kolejce.', 'medium', 15),
(209, 5, 'Asynchroniczność i Event Loop', 'Dlaczego w wielu przypadkach zaleca się stosowanie rekurencyjnego setTimeout zamiast setInterval?', null, 'single-choice', '["Ponieważ gwarantuje stały odstęp czasu MIĘDZY zakończeniem poprzedniego wywołania a startem kolejnego, zapobiegając nakładaniu się zadań asynchronicznych","Bo setInterval jest usunięte ze standardu","Bo setTimeout zużywa mniej pamięci o 90%","Działa tylko w Node.js"]'::jsonb, 0, 'Jeśli zadanie w setInterval trwa dłużej niż interwał, wywołania zaczną się nawarstwiać w kolejce. Rekurencyjny setTimeout czeka na ukończenie poprzedniej operacji.', 'medium', 15),
(210, 5, 'Asynchroniczność i Event Loop', 'Jaki jest minimalny clamping interwału w przeglądarkach dla zagnieżdżonych timerów powyżej 5 poziomów wg specyfikacji HTML5?', null, 'single-choice', '["4 milisekundy","1 milisekunda","10 milisekund","0 milisekund"]'::jsonb, 0, 'Zgodnie ze specyfikacją HTML, po 5 kolejnych zagnieżdżonych wywołaniach timera przeglądarka wymusza minimalny próg (clamping) wynoszący 4 ms w celu oszczędzania baterii.', 'hard', 20),
(211, 5, 'Asynchroniczność i Event Loop', 'Która kolejka ma bezwzględny priorytet przed renderowaniem i kolejnymi Macrotaskami?', null, 'single-choice', '["Microtask Queue (promisy, queueMicrotask, MutationObserver)","Macrotask Queue (setTimeout, setInterval, I/O)","Kolejka CSS","Kolejka dźwiękowa"]'::jsonb, 0, 'Kolejka mikrozadań (Microtask Queue) jest opróżniana w całości po każdym zadaniu synchronicznym, zanim Event Loop przejdzie do kolejnego Macrotaska lub renderowania.', 'medium', 15),
(212, 5, 'Asynchroniczność i Event Loop', 'Klasyczna łamigłówka rekrutacyjna: Jaka będzie kolejność logów w konsoli?', 'console.log(1);
setTimeout(() => console.log(2), 0);
Promise.resolve().then(() => console.log(3));
console.log(4);', 'output-predict', '["1, 4, 3, 2 (synchroniczny kod 1, 4 -> microtask 3 -> macrotask 2)","1, 2, 3, 4","1, 3, 4, 2","1, 4, 2, 3"]'::jsonb, 0, 'Najpierw synchronicznie wykonują się logi 1 i 4. Następnie opróżniana jest kolejka mikrozadań (Promise .then() daje 3). Na samym końcu rusza macrotask z setTimeout (2).', 'medium', 15),
(213, 5, 'Asynchroniczność i Event Loop', 'W jaki sposób jawnie dodać własne zadanie bezpośrednio do kolejki mikrozadań (Microtask Queue)?', 'queueMicrotask(() => {
  console.log("Mikrozadanie wykonane!");
});', 'single-choice', '["Za pomocą wbudowanej funkcji queueMicrotask(fn)","setTimeout(fn, 0)","setImmediate(fn)","process.nextTick() w przeglądarce"]'::jsonb, 0, 'queueMicrotask() to oficjalna, standaryzowana metoda dodawania mikrozadania bez konieczności tworzenia pustego Promise.resolve().then(fn).', 'easy', 10),
(214, 5, 'Asynchroniczność i Event Loop', 'Co się stanie, jeśli funkcja w kolejce mikrozadań w nieskończoność dodaje kolejne mikrozadania?', 'function petla() {
  queueMicrotask(petla);
}
petla();', 'single-choice', '["Wątek całkowicie się zablokuje (tzw. Microtask Starvation) – przeglądarka nigdy nie przejdzie do renderowania ani obsługi kliknięć myszy","Przeglądarka wyrzuci błąd SyntaxError","Po 100 wywołaniach mikrozadanie zamieni się w setTimeout","Nic, zadziała w tle"]'::jsonb, 0, 'Ponieważ Event Loop musi całkowicie opróżnić kolejkę mikrozadań przed przejściem dalej, nieskończona pętla mikrozadań głodzi (starves) wątek główny i zamraża UI.', 'hard', 20),
(215, 5, 'Asynchroniczność i Event Loop', 'Czym jest process.nextTick() w środowisku Node.js w relacji do mikrozadań Promise?', null, 'single-choice', '["Specjalną kolejką Node.js o priorytecie jeszcze wyższym niż standardowa kolejka mikrozadań Promise","Odpowiednikiem setTimeout(1000)","Kolejką renderowania DOM","Błędem silnika V8"]'::jsonb, 0, 'W Node.js kolejka process.nextTickQueue jest przetwarzana przed wszystkimi innymi mikrozadaniami (nawet przed spełnionymi obietnicami Promise).', 'hard', 20),
(216, 5, 'Asynchroniczność i Event Loop', 'Jakie są trzy możliwe stany obiektu Promise w JavaScript?', null, 'single-choice', '["pending (oczekująca), fulfilled (spełniona), rejected (odrzucona)","waiting, running, done","open, processing, closed","loading, success, error"]'::jsonb, 0, 'Promise startuje w stanie "pending". Może przejść tylko raz w stan ostateczny (settled): "fulfilled" (sukces z wartością) lub "rejected" (błąd z powodem).', 'easy', 10),
(217, 5, 'Asynchroniczność i Event Loop', 'Co zwraca metoda .then() wywołana na obiekcie Promise?', 'const p2 = p1.then(x => x * 2);', 'single-choice', '["Zawsze ZUPEŁNIE NOWY obiekt Promise, co umożliwia tworzenie łańcuchów (Promise Chaining)","Oryginalny obiekt p1","Liczbę","undefined"]'::jsonb, 0, 'Każde wywołanie .then(), .catch() lub .finally() tworzy nową obietnicę, rozwiązującą się z wartością zwróconą z callbacka.', 'medium', 15),
(218, 5, 'Asynchroniczność i Event Loop', 'Jaki wynik wypisze poniższy łańcuch obietnic z obsługą błędu w .catch()?', 'Promise.reject("Błąd!")
  .catch(err => "Naprawiono")
  .then(val => console.log(val));', 'output-predict', '["\"Naprawiono\" (blok .catch obsłużył błąd i zwrócił zwykłą wartość, przywracając łańcuch do stanu fulfilled)","\"Błąd!\"","UnhandledPromiseRejection","undefined"]'::jsonb, 0, 'Zwrócenie zwykłej wartości z metody .catch() sprawia, że kolejna obietnica w łańcuchu zostaje pomyślnie rozwiązana (fulfilled) z tą wartością.', 'medium', 15),
(219, 5, 'Asynchroniczność i Event Loop', 'Kiedy wykonuje się metoda .finally() w obietnicy?', 'pobierzDane()
  .then(pokaz)
  .catch(blad)
  .finally(ukryjSpinner);', 'single-choice', '["Zawsze, niezależnie od tego, czy obietnica została spełniona (fulfilled) czy odrzucona (rejected)","Tylko gdy wystąpi błąd","Tylko przy sukcesie","Nigdy, jeśli użyto catch"]'::jsonb, 0, '.finally() uruchamia się po zakończeniu obietnicy w każdym scenariuszu. Idealnie nadaje się do sprzątania zasobów i wyłączania wskaźników ładowania.', 'easy', 10),
(220, 5, 'Asynchroniczność i Event Loop', 'Czy po przejściu obietnicy w stan spełniony (fulfilled) można zmienić jej stan na odrzucony (rejected)?', 'new Promise((resolve, reject) => {
  resolve("OK");
  reject("ERR");
});', 'single-choice', '["Nie, stan obietnicy jest niezmienny (immutable) po pierwszym rozwiązaniu; kolejne wywołania reject() są po prostu ignorowane","Tak, reject ma wyższy priorytet","Wyrzuci błąd PromiseStateException","Zależy od wersji Node.js"]'::jsonb, 0, 'Promise może zmienić stan tylko raz w swoim cyklu życia. Po pierwszym wywołaniu resolve lub reject staje się "settled" i kolejne wywołania nie odnoszą skutku.', 'easy', 10),
(221, 5, 'Asynchroniczność i Event Loop', 'Jak zachowuje się Promise.all([p1, p2, p3]), gdy JEDNA z przekazanych obietnic zostanie odrzucona (rejected)?', null, 'single-choice', '["Natychmiast odrzuca całą obietnicę (fail-fast) z powodem błędu pierwszej odrzuconej obietnicy","Czeka na pozostałe i zwraca sukces","Ignoruje błąd i zwraca null","Zwraca tablicę błędów"]'::jsonb, 0, 'Promise.all wymaga sukcesu wszystkich obietnic. Jeśli chociaż jedna zostanie odrzucona, cała konstrukcja natychmiast ulega odrzuceniu (fail-fast).', 'easy', 10),
(222, 5, 'Asynchroniczność i Event Loop', 'Do czego służy Promise.allSettled() wprowadzony w ES2020?', 'const wyniki = await Promise.allSettled([p1, p2]);', 'single-choice', '["Czeka na ukończenie WSZYSTKICH obietnic (zarówno spełnionych, jak i odrzuconych) i zwraca tablicę obiektów z ich stanami ({ status, value/reason })","Zwraca tylko pierwszą najszybszą","Zatrzymuje program przy błędzie","Sortuje obietnice alfabetycznie"]'::jsonb, 0, 'Promise.allSettled nigdy nie zostaje odrzucone w całości. Zawsze czeka na ukończenie wszystkich zadań i raportuje ich indywidualne rezultaty.', 'medium', 15),
(223, 5, 'Asynchroniczność i Event Loop', 'Jaka jest różnica między Promise.race() a Promise.any()?', null, 'single-choice', '["Promise.race rozstrzyga się natychmiast przy pierwszej ukończonej obietnicy (niezależnie czy to sukces czy błąd), a Promise.any czeka na pierwszy SUKCES (ignorując błędy, chyba że wszystkie zawiodą)","To synonimy","any działa tylko na liczbach","race działa tylko w przeglądarce"]'::jsonb, 0, 'Promise.race rozstrzyga się przy pierwszym zakończonym zdarzeniu. Promise.any poszukuje pierwszego sukcesu (fulfilled); jeśli wszystkie zawiodą, rzuca AggregateError.', 'medium', 15),
(224, 5, 'Asynchroniczność i Event Loop', 'Jaki błąd zostanie wyrzucony przez Promise.any(), jeśli wszystkie przekazane obietnice zakończą się odrzuceniem?', null, 'single-choice', '["AggregateError (obiekt błędu grupujący wszystkie indywidualne powody odrzuceń w tablicy .errors)","TypeError","AllRejectedException","Brak błędu, zwraca pustą tablicę"]'::jsonb, 0, 'Gdy żadna obietnica w Promise.any nie odniesie sukcesu, zgłaszany jest błąd AggregateError z właściwością .errors zawierającą wszystkie przyczyny odrzucenia.', 'hard', 20),
(225, 5, 'Asynchroniczność i Event Loop', 'Co zwróci Promise.all([]), jeśli przekażemy do niego pustą tablicę?', null, 'output-predict', '["Natychmiast spełnioną obietnicę (synchronicznie fulfilled) z pustą tablicą []","Promise w stanie pending na zawsze","Błąd TypeError","undefined"]'::jsonb, 0, 'Dla pustej kolekcji Promise.all([]) natychmiast zwraca obietnicę spełnioną z pustą tablicą [].', 'hard', 20),
(226, 5, 'Asynchroniczność i Event Loop', 'Co ZAWSZE zwraca funkcja oznaczona słowem kluczowym "async"?', 'async function pobierz() {
  return 42;
}
console.log(pobierz());', 'output-predict', '["Obiekt Promise rozwiązujący się do podanej wartości (Promise { 42 })","Liczbę 42 bezpośrednio","undefined","null"]'::jsonb, 0, 'Funkcja ze słowem kluczowym async zawsze niejawnie opakowuje zwracaną wartość w obiekt Promise.resolve(wartość).', 'easy', 10),
(227, 5, 'Asynchroniczność i Event Loop', 'Jak przechwycić błędy z odrzuconej obietnicy przy użyciu składni "await"?', 'async function run() {
  ??? {
    const dane = await pobierzZleDane();
  } ??? (err) {
    console.error(err);
  }
}', 'fill-gap', '["try ... catch","then ... catch","if ... else","guard ... defer"]'::jsonb, 0, 'Składnia async/await pozwala na obsługę błędów asynchronicznych za pomocą standardowej, synchronicznie wyglądającej konstrukcji try...catch.', 'easy', 10),
(228, 5, 'Asynchroniczność i Event Loop', 'Co robi słowo kluczowe "await" z perspektywy wątku głównego?', null, 'single-choice', '["Wstrzymuje wykonywanie tylko DANEJ funkcji asynchronicznej (zwracając sterowanie do Event Loopa), pozwalając innym zadaniom na normalne działanie w tym czasie","Zatrzymuje cały proces przeglądarki","Blokuje system operacyjny","Wyłącza silnik JavaScript"]'::jsonb, 0, 'await jest nieblokujące dla całego wątku (non-blocking). Wstrzymuje tylko ciało bieżącej funkcji async, a reszta aplikacji działa płynnie.', 'medium', 15),
(229, 5, 'Asynchroniczność i Event Loop', 'Jaki jest powszechny błąd wydajnościowy przy pobieraniu niezależnych danych przez "await"?', 'const uzytkownik = await getUzytkownik();
const produkty = await getProdukty();
// Jak to przyspieszyć?', 'single-choice', '["Zamiast czekać po kolei sekwencyjnie, należy uruchomić oba żądania równolegle za pomocą Promise.all([getUzytkownik(), getProdukty()])","Dodać setTimeout","Zmienić nazwę zmiennych","Usunąć słowo await"]'::jsonb, 0, 'Sekwencyjny await wydłuża czas ładowania do sumy czasów obu zapytań (tzw. waterfall). Równoległe Promise.all skraca czas do czasu najdłuższego zapytania.', 'medium', 15),
(230, 5, 'Asynchroniczność i Event Loop', 'Czym jest "Top-level await" wprowadzony w ES2022 w modułach ES?', '// Na najwyższym poziomie pliku modułu .mjs:
const konfiguracja = await fetch("/api/config").then(r => r.json());
export { konfiguracja };', 'single-choice', '["Możliwością używania słowa kluczowego await bezpośrednio na najwyższym poziomie modułu bez konieczności opakowywania go w funkcję async","Automatycznym await dla każdej funkcji","Wsparciem dla asynchronicznego HTML","Szybszym ładowaniem plików graficznych"]'::jsonb, 0, 'Top-level await pozwala modułom działać jak wielkie funkcje asynchroniczne, wstrzymując ładowanie modułów zależnych do czasu pobrania zasobów.', 'medium', 15),
(231, 5, 'Asynchroniczność i Event Loop', 'Dlaczego wywołanie fetch() z adresem zwracającym błąd HTTP 404 lub 500 NIE odrzuca obietnicy (nie wchodzi do .catch)?', null, 'single-choice', '["Ponieważ fetch odrzuca Promise TYLKO przy awarii sieci (np. brak internetu, błąd DNS, błąd CORS), a status 404/500 to poprawna odpowiedź HTTP (res.ok wynosi false)","To błąd w przeglądarce","Bo 404 to kod sukcesu","Trzeba zaktualizować bibliotekę axios"]'::jsonb, 0, 'Fetch uznaje za sukces każde pomyślne połączenie z serwerem. Aby obsłużyć błędy HTTP, należy ręcznie sprawdzić if (!response.ok) throw new Error(response.status).', 'medium', 15),
(232, 5, 'Asynchroniczność i Event Loop', 'Jak anulować trwające żądanie HTTP fetch() (np. po zmianie zakładki przez użytkownika)?', 'const controller = new AbortController();
fetch("/api/dane", { signal: controller.signal });
// Jak przerwać?', 'single-choice', '["controller.abort()","fetch.cancel()","delete controller","window.stopFetch()"]'::jsonb, 0, 'Interfejs AbortController pozwala przerwać jedno lub wiele trwających żądań fetch za pomocą powiązanego sygnału (signal) i metody controller.abort().', 'medium', 15),
(233, 5, 'Asynchroniczność i Event Loop', 'Czy ciało odpowiedzi (response.body) w Fetch API można odczytać wielokrotnie metodami takimi jak res.json()?', 'const res = await fetch("/api");
const d1 = await res.json();
const d2 = await res.json(); // Co się stanie?', 'output-predict', '["TypeError: Failed to execute \"json\" on \"Response\": body stream already read","Zwróci te same dane d1","null","undefined"]'::jsonb, 0, 'Ciało odpowiedzi w fetch jest strumieniem jednorazowym (ReadableStream). Po jego skonsumowaniu strumień jest zablokowany. Aby odczytać dwukrotnie, należy użyć res.clone().', 'hard', 20),
(234, 5, 'Asynchroniczność i Event Loop', 'Jak ustawić automatyczny limit czasu (timeout na 5 sekund) dla zapytania fetch w nowoczesnym JS?', null, 'single-choice', '["fetch(url, { signal: AbortSignal.timeout(5000) })","fetch(url, { timeout: 5000 })","fetch.timeout(5000)","window.setTimeoutFetch(5000)"]'::jsonb, 0, 'Statyczna metoda AbortSignal.timeout(ms) tworzy gotowy sygnał anulujący, który automatycznie przerywa żądanie po upływie wskazanego czasu.', 'medium', 15),
(235, 5, 'Asynchroniczność i Event Loop', 'Jaki nagłówek Content-Type należy wysłać, przesyłając obiekt JSON metodą POST w fetch?', 'headers: { "Content-Type": ??? }', 'fill-gap', '["\"application/json\"","\"text/json\"","\"multipart/form-data\"","\"application/javascript\""]'::jsonb, 0, 'Oficjalnym i wymaganym typem MIME dla dokumentów w formacie JSON jest "application/json".', 'easy', 10),
(236, 5, 'Asynchroniczność i Event Loop', 'Jaka pętla służy do iterowania po asynchronicznych źródłach danych (Async Iterables)?', 'async function czytaj(strumien) {
  ??? (const fragment of strumien) {
    console.log(fragment);
  }
}', 'fill-gap', '["for await","for each","while await","async for"]'::jsonb, 0, 'Pętla "for await (const x of asyncIterable)" oczekuje na rozwiązanie każdej kolejnej obietnicy zwracanej przez asynchroniczny iterator.', 'medium', 15),
(237, 5, 'Asynchroniczność i Event Loop', 'Jak deklaruje się funkcję asynchronicznego generatora?', null, 'single-choice', '["async function* generator() {}","function async* generator() {}","generator async() {}","async generator*() {}"]'::jsonb, 0, 'Składnia async function* łączy możliwości asynchroniczności (await) oraz generatora (yield), produkując asynchroniczny iterator.', 'medium', 15),
(238, 5, 'Asynchroniczność i Event Loop', 'Co zwraca metoda .next() wywołana na asynchronicznym iteratorze?', null, 'single-choice', '["Obiekt Promise rozwiązujący się do { value, done }","{ value, done } synchronicznie","Samą wartość value","undefined"]'::jsonb, 0, 'Zgodnie z protokołem asynchronicznej iteracji, wywołanie iterator.next() zwraca obietnicę Promise<{ value: any, done: boolean }>.', 'hard', 20),
(239, 5, 'Asynchroniczność i Event Loop', 'Jaki symbol identyfikuje obiekt jako asynchronicznie iterowalny?', null, 'single-choice', '["Symbol.asyncIterator","Symbol.iterator","Symbol.async","Symbol.stream"]'::jsonb, 0, 'Właściwość pod kluczem [Symbol.asyncIterator] musi być funkcją zwracającą asynchroniczny iterator, aby obiekt mógł być użyty w for await...of.', 'hard', 20),
(240, 5, 'Asynchroniczność i Event Loop', 'Do czego najczęściej stosuje się asynchroniczne iteratory w przeglądarce i Node.js?', null, 'single-choice', '["Do czytania strumieni danych (ReadableStream) partiami (chunks), np. pobierania wielkich plików lub generowanych w czasie rzeczywistym odpowiedzi AI","Do sortowania małych tablic","Do zmiany tła strony","Do kompilacji CSS"]'::jsonb, 0, 'Asynchroniczne iteratory pozwalają przetwarzać strumienie kawałek po kawałku w miarę ich napływania z sieci bez wczytywania całego pliku do pamięci RAM.', 'medium', 15),
(241, 5, 'Asynchroniczność i Event Loop', 'Czym jest Web Worker w przeglądarce?', null, 'single-choice', '["Mechanizmem pozwalającym na uruchomienie kodu JavaScript w prawdziwym, osobnym wątku procesora w tle, bez blokowania wątku interfejsu (UI)","Wtyczką do przeglądarki","Kolejką mikrozadań","Serwerem proxy"]'::jsonb, 0, 'Web Worker działa w całkowicie niezależnym wątku systemowym, idealnym do obliczeń kryptograficznych, kompresji obrazów czy symulacji fizyki.', 'medium', 15),
(242, 5, 'Asynchroniczność i Event Loop', 'Czy kod działający wewnątrz Web Workera ma bezpośredni dostęp do drzewa DOM (document, window)?', null, 'single-choice', '["Nie, z przyczyn bezpieczeństwa i braku synchronizacji wątków Web Worker nie ma dostępu do DOM ani obiektu window","Tak, może swobodnie modyfikować HTML","Tylko jeśli posiada uprawnienia roota","Tak, w trybie strict mode"]'::jsonb, 0, 'Web Worker nie ma dostępu do DOM, window czy document. Zamiast tego komunikuje się z głównym wątkiem poprzez system komunikatów postMessage.', 'medium', 15),
(243, 5, 'Asynchroniczność i Event Loop', 'Jak przesyła się dane między głównym wątkiem a Web Workerem?', null, 'single-choice', '["Za pomocą metody postMessage() oraz nasłuchiwania zdarzenia \"message\"","Poprzez współdzielone zmienne globalne window.data","Zapisując pliki na dysku","Przez nagłówki HTTP"]'::jsonb, 0, 'Komunikacja opiera się na architekturze przesyłania wiadomości (Message Passing) z wykorzystaniem algorytmu klonowania strukturalnego lub obiektów transferowalnych.', 'easy', 10),
(244, 5, 'Asynchroniczność i Event Loop', 'Czym są obiekty transferowalne (Transferable Objects, np. ArrayBuffer)?', null, 'single-choice', '["Obiektami, których prawo własności do pamięci jest błyskawicznie przekazywane (zerowy koszt kopiowania) z jednego wątku do drugiego z natychmiastowym wyczyszczeniem w wątku źródłowym","Plikami przesyłanymi przez FTP","Ciasteczkami sesyjnymi","Zmiennymi typu let"]'::jsonb, 0, 'Przekazanie przez transfer (ownership transfer) pozwala na bezkosztowe przeniesienie nawet gigabajtowego bufora w ułamku milisekundy.', 'hard', 20),
(245, 5, 'Asynchroniczność i Event Loop', 'Do czego służy SharedArrayBuffer oraz Atomics w JavaScript?', null, 'single-choice', '["Do współdzielenia wspólnego obszaru pamięci RAM pomiędzy wieloma wątkami/Workerami z operacjami atomowymi zabezpieczającymi przed wyścigami (race conditions)","Do formatowania tablic w konsoli","Do tworzenia animacji CSS","Do kompresji plików ZIP"]'::jsonb, 0, 'SharedArrayBuffer umożliwia bezpośrednie współdzielenie pamięci, a obiekt Atomics zapewnia operacje niepodzielne (load, store, wait, notify).', 'hard', 20),
(246, 5, 'Asynchroniczność i Event Loop', 'Kiedy dokładnie przeglądarka wykonuje zadania z kolejki requestAnimationFrame(callback)?', null, 'single-choice', '["Tuż przed kolejnym odświeżeniem ekranu (repaintingiem klatki, zazwyczaj z częstotliwością 60 Hz / 120 Hz)","Po każdym kliknięciu myszą","Zawsze co 1 milisekundę","Na samym początku działania skryptu"]'::jsonb, 0, 'requestAnimationFrame synchronizuje wywołania callbacku bezpośrednio z cyklem odświeżania monitora, gwarantując maksymalną płynność animacji.', 'medium', 15),
(247, 5, 'Asynchroniczność i Event Loop', 'Do czego służy globalne zdarzenie "unhandledrejection"?', 'window.addEventListener("unhandledrejection", event => {
  console.error(event.reason);
});', 'single-choice', '["Przechwytuje wszystkie odrzucone obietnice Promise, dla których nie zdefiniowano bloku .catch() ani try...catch","Obsługuje odrzucenia plików cookie","Blokuje reklamy","Wykrywa błędy 404 w CSS"]'::jsonb, 0, 'Zdarzenie unhandledrejection pozwala na centralne logowanie i monitorowanie nieobsłużonych asynchronicznych wyjątków w całej aplikacji.', 'easy', 10),
(248, 5, 'Asynchroniczność i Event Loop', 'Jaki będzie wynik wywołania await na wartości, która NIE jest obiektem Promise (np. await 10)?', 'async function test() {
  const x = await 10;
  console.log(x);
}
test();', 'output-predict', '["10 (silnik automatycznie opakowuje wartość w Promise.resolve(10) i czeka na kolejny tick mikrozadań)","TypeError: 10 is not a Promise","undefined","NaN"]'::jsonb, 0, 'await może być bezpiecznie stosowany do dowolnej wartości; prymitywy są automatycznie konwertowane na spełnioną obietnicę.', 'medium', 15),
(249, 5, 'Asynchroniczność i Event Loop', 'Czym jest obiekt typu "Thenable"?', 'const custom = {
  then(resolve, reject) {
    resolve("Działa!");
  }
};
console.log(await custom);', 'output-predict', '["\"Działa!\" (każdy obiekt posiadający metodę .then() jest traktowany przez Promise i await jak natywna obietnica)","TypeError","undefined","{ then: function }"]'::jsonb, 0, 'JavaScript stosuje Duck Typing dla obietnic: każdy obiekt z metodą .then() to "Thenable" i może być poprawnie obsłużony przez await.', 'hard', 20),
(250, 5, 'Asynchroniczność i Event Loop', 'Jaka metoda służy do odłożenia zadania na czas bezczynności przeglądarki, aby nie przeszkadzać w interakcji użytkownika?', null, 'single-choice', '["requestIdleCallback(callback)","requestAnimationFrame()","setTimeout(0)","queueMicrotask()"]'::jsonb, 0, 'requestIdleCallback uruchamia zadania o niskim priorytecie (np. wysyłanie telemetrii lub analityki) w wolnych szczelinach czasowych między klatkami renderowania.', 'medium', 15),
(251, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między document.querySelector() a document.querySelectorAll()?', null, 'single-choice', '["querySelector zwraca pierwszy pasujący element (lub null), a querySelectorAll zwraca statyczną kolekcję NodeList wszystkich pasujących elementów","querySelector działa tylko po ID (#)","querySelectorAll modyfikuje elementy w DOM","Nie ma żadnej różnicy"]'::jsonb, 0, 'querySelector() przerywa szukanie po znalezieniu pierwszego dopasowania. querySelectorAll() zbiera wszystkie elementy pasujące do selektora CSS do kolekcji NodeList.', 'easy', 10),
(252, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest kluczowa różnica między żywą kolekcją (Live Collection) a kolekcją statyczną (Static)?', 'const zywa = document.getElementsByClassName("karta");
const statyczna = document.querySelectorAll(".karta");', 'single-choice', '["Żywa kolekcja automatycznie aktualizuje swoją zawartość i długość, gdy elementy są dodawane lub usuwane z DOM; kolekcja statyczna to jednorazowa migawka (snapshot)","Żywa kolekcja zużywa baterię","Statyczna kolekcja nie ma metody forEach","To pojęcia tożsame"]'::jsonb, 0, 'Metody getElementsBy... zwracają HTMLCollection (żywą). Metoda querySelectorAll zwraca statyczny NodeList, który nie reaguje na późniejsze zmiany w drzewie DOM.', 'medium', 15),
(253, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między węzłem (Node) a elementem (Element) w drzewie DOM?', null, 'single-choice', '["Każdy Element jest Node, ale Node obejmuje również węzły tekstowe, komentarze oraz sam dokument","Element to plik na dysku, a Node to kod w pamięci","Node to element tylko w Node.js","Elementy nie mają atrybutów"]'::jsonb, 0, 'Węzeł (Node) to ogólna klasa bazowa hierarchii DOM (komentarze, tekst, węzły CDATA). Element dziedziczy z Node i reprezentuje konkretny tag HTML (<p>, <div>).', 'medium', 15),
(254, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak za pomocą nowoczesnego API wyszukać najbliższego przodka elementu pasującego do selektora CSS?', 'const przycisk = document.querySelector("button");
const formularz = przycisk.???("form");', 'fill-gap', '["closest","parent","ancestor","findParent"]'::jsonb, 0, 'Metoda Element.prototype.closest(selector) przemieszcza się w górę drzewa DOM, zwracając najbliższy element pasujący do podanego selektora.', 'easy', 10),
(255, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak sprawdzić, czy dany element pasuje do określonego selektora CSS?', 'if (element.???(".aktywny")) {
  console.log("Jest aktywny!");
}', 'fill-gap', '["matches","contains","is","hasSelector"]'::jsonb, 0, 'Metoda element.matches(selector) zwraca wartość logiczną true/false, informując, czy dany element odpowiada regule CSS.', 'easy', 10),
(256, 6, 'DOM, Zdarzenia i Przeglądarka', 'Dlaczego wstawianie niezaufanych danych użytkownika przez element.innerHTML stwarza krytyczne zagrożenie bezpieczeństwa?', null, 'single-choice', '["Otwiera aplikację na ataki typu Cross-Site Scripting (XSS), umożliwiając wykonanie wstrzykniętego złośliwego kodu JavaScript","Niszczy połączenie HTTPS","Spowalnia działanie karty graficznej","Powoduje usunięcie bazy danych"]'::jsonb, 0, 'Przypisanie do innerHTML parsuje surowy HTML, co pozwala atakującym wstrzyknąć niebezpieczne skrypty lub tagi (np. <img src=x onerror=...>) kradnące ciasteczka sesyjne.', 'easy', 10),
(257, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka właściwość służy do bezpiecznego wstawiania czystego tekstu bez ryzyka interpretacji znaczników HTML?', 'komunikat.??? = userInput;', 'fill-gap', '["textContent","innerHTML","outerHTML","writeText"]'::jsonb, 0, 'Właściwość textContent traktuje przypisany ciąg znaków wyłącznie jako zwykły tekst, automatycznie neutralizując wszelkie znaki specjalne (<, >, &).', 'easy', 10),
(258, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy DocumentFragment podczas dodawania wielu elementów do drzewa DOM?', null, 'single-choice', '["Do grupowania wielu nowych węzłów w pamięci i wstawienia ich do właściwego DOM w JEDNEJ operacji, co drastycznie redukuje kosztowne przeliczenia układu (reflow)","Do podziału strony na podstrony","Do tworzenia animacji CSS","Do kompresji plików DOM"]'::jsonb, 0, 'DocumentFragment to lekki kontener DOM w pamięci. Po wstawieniu go do dokumentu wstawiane są tylko jego dzieci, wywołując pojedynczy reflow.', 'medium', 15),
(259, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak w nowoczesnym JavaScript usunąć element z drzewa DOM wprost bez odwoływania się do jego rodzica?', 'const baner = document.querySelector("#baner");
// Wcześniej: baner.parentNode.removeChild(baner);
// Nowocześnie:', 'single-choice', '["baner.remove()","baner.delete()","delete baner","document.destroy(baner)"]'::jsonb, 0, 'Metoda element.remove() wprowadzona w standardzie DOM pozwala na bezpośrednie usunięcie elementu bez konieczności przechodzenia przez parentNode.', 'easy', 10),
(260, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka metoda pozwala precyzyjnie wstawić fragment HTML w określone miejsce (beforebegin, afterbegin, beforeend, afterend)?', null, 'single-choice', '["insertAdjacentHTML(pozycja, html)","insertHTML(pozycja, html)","appendHTML(html)","setHTML(html)"]'::jsonb, 0, 'element.insertAdjacentHTML(position, text) to niezwykle szybka metoda parsująca i wstawiająca HTML dokładnie w żądane miejsce względem elementu.', 'medium', 15),
(261, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak za pomocą classList w prosty sposób włączyć klasę, jeśli jej nie ma, lub usunąć, jeśli jest (przełącznik)?', 'element.classList.???("widoczny");', 'fill-gap', '["toggle","switch","flip","addOrRemove"]'::jsonb, 0, 'Metoda classList.toggle("klasa") dodaje klasę, jeśli element jej nie posiada, lub usuwa ją, jeśli już występuje.', 'easy', 10),
(262, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak odczytać w JavaScript niestandardowy atrybut danych HTML data-user-role="moderator"?', '<div id="box" data-user-role="moderator"></div>', 'single-choice', '["element.dataset.userRole (notacja camelCase)","element.dataset[\"data-user-role\"]","element.userRole","element.data.role"]'::jsonb, 0, 'Właściwość .dataset automatycznie przekształca atrybuty data-* z zapisu kebab-case na camelCase (data-user-role staje się dataset.userRole).', 'easy', 10),
(263, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między atrybutem HTML a właściwością (property) obiektu DOM?', '<input id="i" value="Początek">', 'single-choice', '["Atrybut w HTML określa stan początkowy w znaczniku, natomiast właściwość DOM reprezentuje bieżący stan dynamiczny w pamięci przeglądarki","Atrybuty są zawsze liczbami","Właściwości DOM nie można edytować","To dokładnie to samo"]'::jsonb, 0, 'Gdy użytkownik wpisze tekst w input, input.value (właściwość) ulega zmianie, ale input.getAttribute("value") wciąż zwraca wartość początkową.', 'medium', 15),
(264, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak sprawdzić, czy element posiada zdefiniowaną określoną klasę CSS?', null, 'single-choice', '["element.classList.contains(\"moja-klasa\")","element.hasClassName(\"moja-klasa\")","element.classList.has(\"moja-klasa\")","element.isClass(\"moja-klasa\")"]'::jsonb, 0, 'Metoda element.classList.contains(string) zwraca boolean informujący o obecności danej klasy.', 'easy', 10),
(265, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak najwygodniej ustawić styl inline za pomocą właściwości .style?', 'element.style.backgroundColor = "blue";', 'single-choice', '["Właściwości wieloczłonowe CSS (np. background-color) zapisujemy w JS w notacji camelCase (backgroundColor)","Zawsze z myślnikami w cudzysłowie","Tylko za pomocą metody setCSS()","Używając wielkich liter"]'::jsonb, 0, 'Właściwości stylów w obiekcie style przyjmują nazwy w notacji camelCase (np. fontSize, zIndex, borderRadius).', 'easy', 10),
(266, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jakie są trzy kolejne fazy propagacji zdarzenia w standardzie DOM?', null, 'single-choice', '["1. Faza przechwytywania (Capturing), 2. Faza celu (Target), 3. Faza bąbelkowania (Bubbling)","1. Ładowanie, 2. Parsowanie, 3. Renderowanie","1. Kliknięcie, 2. Reakcja, 3. Koniec","1. Sync, 2. Async, 3. Microtask"]'::jsonb, 0, 'Zdarzenie najpierw schodzi z samej góry drzewa (Window) do elementu docelowego (Capturing), osiąga cel (Target), a następnie wznosi się w górę (Bubbling).', 'medium', 15),
(267, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest fundamentalna różnica między właściwościami event.target a event.currentTarget?', null, 'single-choice', '["event.target wskazuje element, na którym faktycznie doszło do zdarzenia (np. kliknięty guzik), a event.currentTarget wskazuje element, do którego aktualnie przypięty jest nasłuchiwacz (listener)","event.target to zawsze obiekt window","event.currentTarget działa tylko w fazie capturing","Nie ma żadnej różnicy"]'::jsonb, 0, 'event.target to element źródłowy akcji. event.currentTarget to element, na którym aktualnie wykonuje się funkcja addEventListener.', 'medium', 15),
(268, 6, 'DOM, Zdarzenia i Przeglądarka', 'Co robi metoda event.stopPropagation()?', null, 'single-choice', '["Zatrzymuje dalsze rozprzestrzenianie się zdarzenia w górę (lub w dół) drzewa DOM do kolejnych elementów","Blokuje domyślną akcję przeglądarki (np. przeładowanie formularza)","Usuwa nasłuchiwacz zdarzeń","Wyłącza kursor myszy"]'::jsonb, 0, 'stopPropagation() uniemożliwia bąbelkowanie zdarzenia do nadrzędnych węzłów DOM, izolując obsługę zdarzenia.', 'easy', 10),
(269, 6, 'DOM, Zdarzenia i Przeglądarka', 'Czym różni się event.stopImmediatePropagation() od zwykłego event.stopPropagation()?', null, 'single-choice', '["Dodatkowo natychmiast zapobiega uruchomieniu pozostałych nasłuchiwaczy tego samego typu zarejestrowanych na TYM SAMYM elemencie","Zamyka kartę w przeglądarce","Działa asynchronicznie","Nie ma różnicy"]'::jsonb, 0, 'Jeśli na jednym elemencie jest 3 listenerów zdarzenia "click", stopImmediatePropagation() zatrzymuje także wykonanie 2 i 3 listenera na tym samym elemencie.', 'hard', 20),
(270, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak zarejestrować nasłuchiwacz zdarzenia w fazie przechwytywania (Capture Phase)?', 'element.addEventListener("click", handler, ???);', 'fill-gap', '["true (lub { capture: true })","false","\"capture\"","{ bubble: false }"]'::jsonb, 0, 'Trzeci parametr addEventListener ustawiony na true (lub obiekt opcji { capture: true }) włącza obsługę w fazie Capturing zamiast domyślnej fazy Bubbling.', 'medium', 15),
(271, 6, 'DOM, Zdarzenia i Przeglądarka', 'Na czym polega wzorzec delegacji zdarzeń (Event Delegation)?', 'document.querySelector("ul").addEventListener("click", e => {
  if (e.target.matches("li.element")) {
    console.log("Kliknięto:", e.target.textContent);
  }
});', 'single-choice', '["Na przypisaniu jednego wspólnego nasłuchiwacza zdarzeń do rodzica kontenera i obsłudze zdarzeń bąbelkujących od obecnych i dynamicznie dodawanych dzieci","Na tworzeniu osobnego listenera w pętli dla każdego <li>","Na delegowaniu obliczeń do Web Workera","Na przekazywaniu kliknięć przez iframe"]'::jsonb, 0, 'Delegacja zdarzeń oszczędza pamięć RAM i automatycznie obsługuje elementy dodane do DOM w przyszłości dzięki mechanizmowi bąbelkowania (bubbling).', 'medium', 15),
(272, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak obsłużyć sytuację w delegacji zdarzeń, gdy kliknięto na element potomny wewnątrz przycisku (np. <i> w <button>)?', '<button class="btn"><i class="ikona"></i> Zapisz</button>', 'single-choice', '["Użyć e.target.closest(\".btn\"), aby odszukać właściwy element nadrzędny przycisku","Zablokować klikanie ikon w CSS","Przypisać listener do ikony","Użyć window.currentButton"]'::jsonb, 0, 'e.target.closest(".btn") bezpiecznie odnajduje kontener przycisku, nawet jeśli właściwym klikniętym węzłem była ikona <i> lub span wewnątrz.', 'medium', 15),
(273, 6, 'DOM, Zdarzenia i Przeglądarka', 'Które z poniższych popularnych zdarzeń DOM domyślnie NIE bąbelkują (bubbles: false)?', null, 'single-choice', '["focus i blur (oraz mouseenter i mouseleave)","click i dblclick","keydown i keyup","submit i reset"]'::jsonb, 0, 'Zdarzenia focus, blur, mouseenter i mouseleave nie bąbelkują. Ich bąbelkującymi odpowiednikami są focusin, focusout, mouseover i mouseout.', 'hard', 20),
(274, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy opcja { once: true } w metodzie addEventListener?', 'btn.addEventListener("click", fn, { once: true });', 'single-choice', '["Automatycznie usuwa nasłuchiwacz zdarzeń zaraz po jego pierwszym uruchomieniu","Pozwala na kliknięcie tylko raz na sekundę","Zezwala na rejestrację tylko jednej funkcji","Uniemożliwia bąbelkowanie"]'::jsonb, 0, 'Opcja once: true gwarantuje, że funkcja callback wykona się dokładnie jeden raz, a po zakończeniu silnik samoczynnie wyrejestruje listener.', 'easy', 10),
(275, 6, 'DOM, Zdarzenia i Przeglądarka', 'Dlaczego podanie opcji { passive: true } przy zdarzeniach touchstart lub wheel drastycznie poprawia płynność przewijania strony?', null, 'single-choice', '["Informuje przeglądarkę, że funkcja nigdy nie wywoła event.preventDefault(), dzięki czemu wątek kompozytora (scroll) może natychmiast płynnie przewijać ekran bez czekania na kod JS","Wyłącza animacje CSS","Kompresuje obrazy","Zmniejsza zużycie pamięci"]'::jsonb, 0, 'Dzięki passive: true przeglądarka wie, że nie dojdzie do zablokowania scrolla przez JS, więc nie wstrzymuje renderowania klatek.', 'hard', 20),
(276, 6, 'DOM, Zdarzenia i Przeglądarka', 'Co robi wywołanie event.preventDefault() w obsłudze zdarzenia "submit" formularza?', 'form.addEventListener("submit", e => {
  e.preventDefault();
  // Dalsza logika w JS
});', 'single-choice', '["Zapobiega domyślnej akcji przeglądarki, czyli przeładowaniu całej strony i wysłaniu żądania GET/POST","Usuwa wszystkie pola formularza","Zamyka przeglądarkę","Zatrzymuje propagację zdarzenia w górę DOM"]'::jsonb, 0, 'preventDefault() blokuje domyślne zachowanie elementu w przeglądarce, pozwalając na wysłanie danych formularza w tle np. przez fetch() bez przeładowania strony.', 'easy', 10),
(277, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak sprawdzić, czy dane zdarzenie pozwala na zablokowanie domyślnej akcji za pomocą preventDefault()?', null, 'single-choice', '["Sprawdzając właściwość logiczną event.cancelable","Sprawdzając event.isPreventable","Wszystkie zdarzenia zawsze można zablokować","Właściwością event.blocked"]'::jsonb, 0, 'Właściwość event.cancelable określa, czy zdarzenie może zostać powstrzymane. Jeśli cancelable wynosi false, preventDefault() nic nie zmieni.', 'medium', 15),
(278, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak za pomocą obiektu FormData łatwo wyciągnąć wszystkie wartości z formularza HTML?', 'const dane = new FormData(formElement);
const email = dane.get("email");', 'single-choice', '["Przekazując element <form> do konstruktora new FormData() i korzystając z metody .get(name) lub Object.fromEntries(dane)","Odczytując ręcznie każde pole w tablicy","Pobierając dane z ciasteczek","Tylko za pomocą jQuery"]'::jsonb, 0, 'Obiekt FormData zbiera pary nazwa-wartość ze wszystkich kontrolek formularza posiadających atrybut "name", ułatwiając serializację.', 'easy', 10),
(279, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między zdarzeniami "input" a "change" na polach tekstowych <input>?', null, 'single-choice', '["\"input\" odpala się natychmiast przy każdym wpisaniu/usunięciu znaku, natomiast \"change\" dopiero po utracie fokusu (blur) i zmianie wartości","\"change\" działa tylko przy kopiowaniu","\"input\" działa tylko na urządzeniach mobilnych","To synonimy"]'::jsonb, 0, '"input" reaguje na żywo na każdą modyfikację (idealny do live-search). "change" wyzwala się dopiero po sfinalizowaniu edycji i zatwierdzeniu (np. Enter lub opuszczenie pola).', 'easy', 10),
(280, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy API walidacji ograniczeń (Constraint Validation API) w polach formularzy HTML5?', 'if (!input.checkValidity()) {
  console.log(input.validationMessage);
}', 'single-choice', '["Do weryfikacji poprawności pól (np. required, minlength, type=\"email\") przy użyciu metod checkValidity() i reportValidity()","Do szyfrowania haseł","Do generowania kodów CAPTCHA","Do sprawdzania bazy danych SQL"]'::jsonb, 0, 'Wbudowane Constraint Validation API pozwala programmaticznie sprawdzać poprawność reguł formularza bez pisania własnych regexów.', 'medium', 15),
(281, 6, 'DOM, Zdarzenia i Przeglądarka', 'Czym jest Reflow (Layout) w procesie renderowania strony przez silnik przeglądarki?', null, 'single-choice', '["Kosztownym procesem przeliczania fizycznej geometrii, pozycji i wymiarów wszystkich elementów na ekranie","Tylko zmianą koloru tła","Pobieraniem czcionek z sieci","Usuwaniem plików cache"]'::jsonb, 0, 'Reflow (układ) wyznacza rozmiary i położenie każdego węzła na stronie. Zmiana geometrii jednego elementu może wywołać kaskadowe przeliczenie całego dokumentu.', 'medium', 15),
(282, 6, 'DOM, Zdarzenia i Przeglądarka', 'Czym jest Layout Thrashing (wymuszony synchroniczny layout)?', 'for (let i = 0; i < elementy.length; i++) {
  elementy[i].style.width = box.offsetWidth + "px"; // Zapis i odczyt naprzemiennie!
}', 'single-choice', '["Poważnym błędem wydajnościowym, gdzie kod naprzemiennie modyfikuje DOM (zapis) i natychmiast odpytuje o geometrię (odczyt), zmuszając przeglądarkę do wielokrotnego powtarzania Reflow w jednej pętli","Wyczerpaniem limitu pamięci dyskowej","Błędem w sterowniku karty graficznej","Przegrzaniem procesora"]'::jsonb, 0, 'Odpytanie o właściwości geometryczne (offsetWidth, clientHeight itp.) natychmiast wymusza przeliczenie layoutu. Naprzemienny zapis i odczyt rujnuje wydajność klatki (spadek FPS).', 'hard', 20),
(283, 6, 'DOM, Zdarzenia i Przeglądarka', 'Które właściwości CSS są najbezpieczniejsze i najbardziej wydajne do animacji, ponieważ omijają etapy Reflow i Repaint (działają w warstwie Composite)?', null, 'single-choice', '["transform oraz opacity","top, left, width i height","margin i padding","display i float"]'::jsonb, 0, 'Animacje oparte o transform i opacity są delegowane bezpośrednio do procesora graficznego GPU (Compositing), osiągając stabilne 60 lub 120 FPS bez ruszania wątku głównego.', 'medium', 15),
(284, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak odczytać dokładne wymiary i pozycję elementu względem bieżącego okna podglądu (viewport)?', null, 'single-choice', '["element.getBoundingClientRect()","element.getDimensions()","element.clientCoordinates()","element.screenSize()"]'::jsonb, 0, 'Metoda getBoundingClientRect() zwraca obiekt DOMRect z właściwościami top, right, bottom, left, width, height oraz x, y względem viewportu.', 'easy', 10),
(285, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy właściwość CSS "will-change: transform"?', null, 'single-choice', '["Daje podpowiedź przeglądarce, że element będzie wkrótce animowany, co pozwala jej wcześniej wydzielić osobną warstwę sprzętową (GPU compositor layer)","Wymusza zmianę stylów w trybie awaryjnym","Usuwa element z DOM","Blokuje zdarzenia myszy"]'::jsonb, 0, 'will-change przygotowuje przeglądarkę do optymalizacji renderowania, choć nadużywane może pochłonąć zbyt dużo pamięci GPU.', 'medium', 15),
(286, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy IntersectionObserver API w JavaScript?', 'const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) zaladujObraz(entry.target);
  });
});', 'single-choice', '["Do asynchronicznego wykrywania, kiedy obserwowany element pojawia się w widocznym oknie (viewport), idealne do Lazy Loading obrazów i nieskończonego scrolla","Do obserwacji zmian w bazie danych","Do sprawdzania rozdzielczości ekranu","Do przecinania ciągów znaków"]'::jsonb, 0, 'IntersectionObserver zastępuje kosztowne nasłuchiwanie zdarzenia "scroll", powiadamiając asynchronicznie o wejściu elementu w kadr.', 'medium', 15),
(287, 6, 'DOM, Zdarzenia i Przeglądarka', 'Czym zajmuje się ResizeObserver API?', null, 'single-choice', '["Powiadamia o zmianie fizycznych wymiarów (prostokąta granicznego) konkretnego elementu HTML, niezależnie od rozmiaru całego okna","Zmienia rozmiar czcionek w systemie","Monitoruje powiększenie w przeglądarce","Kompresuje pliki graficzne"]'::jsonb, 0, 'ResizeObserver pozwala reagować na zmiany rozmiaru pojedynczego kontenera, co jest podstawą tzw. Container Queries w nowoczesnych komponentach.', 'medium', 15),
(288, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy MutationObserver API?', null, 'single-choice', '["Do obserwowania zmian w strukturze drzewa DOM (dodanie/usunięcie węzłów, zmiana atrybutów lub modyfikacja tekstu)","Do testów mutacyjnych kodu","Do modyfikacji prototypów obiektów","Do wykrywania wirusów w przeglądarce"]'::jsonb, 0, 'MutationObserver to wydajny mechanizm oparty o kolejkę mikrozadań do monitorowania wszelkich zmian strukturalnych w drzewie DOM.', 'medium', 15),
(289, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak przestać obserwować element w IntersectionObserver lub MutationObserver?', null, 'single-choice', '["observer.disconnect() (aby odpiąć wszystko) lub observer.unobserve(element)","observer.stop()","delete observer","observer.close()"]'::jsonb, 0, 'Metoda .unobserve(target) usuwa pojedynczy element, a .disconnect() natychmiast wyłącza obserwator dla wszystkich śledzonych węzłów.', 'easy', 10),
(290, 6, 'DOM, Zdarzenia i Przeglądarka', 'Co oznacza próg threshold: [0, 0.5, 1.0] w konfiguracji IntersectionObserver?', null, 'single-choice', '["Callback uruchomi się przy 0% (pierwszy piksel w kadrze), 50% oraz 100% pełnej widoczności elementu na ekranie","Opóźnienie w sekundach","Liczbę powtórzeń pętli","Współczynnik kompresji"]'::jsonb, 0, 'Tablica threshold określa procentowe progi widoczności elementu w obszarze przecięcia (od 0.0 do 1.0), przy których generowany jest raport zdarzenia.', 'hard', 20),
(291, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest podstawowa różnica między localStorage a sessionStorage?', null, 'single-choice', '["localStorage przechowuje dane trwale bez daty wygaśnięcia (nawet po ponownym uruchomieniu przeglądarki), a sessionStorage czyści się automatycznie po zamknięciu danej karty/okna","sessionStorage ma pojemność 1 GB, a localStorage 1 KB","localStorage działa tylko po HTTPS","Nie ma żadnej różnicy"]'::jsonb, 0, 'sessionStorage żyje tak długo, jak otwarta jest konkretna karta przeglądarki. localStorage zachowuje dane na stałe do momentu ich jawnego wyczyszczenia.', 'easy', 10),
(292, 6, 'DOM, Zdarzenia i Przeglądarka', 'Dlaczego ciasteczka (cookies) z flagą "HttpOnly" są bezpieczniejsze dla tokenów uwierzytelniających niż localStorage?', null, 'single-choice', '["Ciasteczka HttpOnly są całkowicie niedostępne dla skryptów JavaScript (document.cookie), co uniemożliwia ich kradzież w przypadku ataku XSS","Bo są szyfrowane kluczem AES-256","Bo nie zajmują pamięci RAM","Bo działają offline"]'::jsonb, 0, 'Brak dostępu do ciasteczka z poziomu document.cookie chroni wrażliwe tokeny sesyjne przed kradzieżą przez wstrzyknięty skrypt XSS.', 'medium', 15),
(293, 6, 'DOM, Zdarzenia i Przeglądarka', 'Czym jest IndexedDB w przeglądarce?', null, 'single-choice', '["Wbudowaną w przeglądarkę, w pełni asynchroniczną, transakcyjną bazą danych NoSQL o dużej pojemności do przechowywania ustrukturyzowanych obiektów i plików","Relacyjną bazą MySQL w chmurze","Plikiem tekstowym CSV","Kolejką mikrozadań"]'::jsonb, 0, 'IndexedDB pozwala przechowywać setki megabajtów danych offline z indeksami, kursorami i transakcjami bez blokowania wątku głównego.', 'medium', 15),
(294, 6, 'DOM, Zdarzenia i Przeglądarka', 'Co się stanie przy próbie zapisu obiektu do localStorage za pomocą metody setItem("user", obj)?', 'const user = { imie: "Kamil" };
localStorage.setItem("user", user);
console.log(localStorage.getItem("user"));', 'output-predict', '["\"[object Object]\" (localStorage przyjmuje wyłącznie stringi i rzutuje obiekty przez .toString())","{\"imie\":\"Kamil\"}","TypeError","null"]'::jsonb, 0, 'localStorage obsługuje tylko ciągi znaków. Aby zapisać obiekt, należy go najpierw zserializować przez JSON.stringify(user), a przy odczycie zdeserializować JSON.parse().', 'easy', 10),
(295, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy globalne zdarzenie "storage" na obiekcie window?', 'window.addEventListener("storage", e => {
  console.log("Zmieniono klucz:", e.key);
});', 'single-choice', '["Uruchamia się w INNYCH otwartych kartach/oknach tej samej domeny, gdy w jednej z kart nastąpi modyfikacja danych w localStorage, umożliwiając synchronizację między kartami","Powiadamia o zapełnieniu dysku","Czyści pamięć podręczną","Działa tylko na urządzeniach mobilnych"]'::jsonb, 0, 'Zdarzenie window.onstorage to świetne narzędzie do synchronizacji stanu aplikacji w czasie rzeczywistym między wieloma otwartymi kartami przeglądarki.', 'hard', 20),
(296, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między zdarzeniami "DOMContentLoaded" a "load" na obiekcie window?', null, 'single-choice', '["DOMContentLoaded odpala się, gdy drzewo DOM jest w pełni zbudowane (bez czekania na obrazki i arkusze stylów), a window \"load\" czeka na pobranie absolutnie wszystkich zasobów (obrazów, stylów, ramek)","DOMContentLoaded działa tylko w HTML5","load odpala się przed parsowaniem HTML","Nie ma żadnej różnicy"]'::jsonb, 0, 'DOMContentLoaded pozwala uruchomić interaktywny kod znacznie szybciej, ponieważ nie czeka na ładowanie ciężkich plików graficznych.', 'easy', 10),
(297, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jaka jest różnica między atrybutami skryptu "async" i "defer" w znaczniku <script>?', '<script src="a.js" async></script>
<script src="b.js" defer></script>', 'single-choice', '["Oba pobierają plik w tle, ale \"defer\" wykonuje się dopiero po zakończeniu parsowania HTML i zachowuje kolejność skryptów, a \"async\" wykonuje się natychmiast po pobraniu, przerywając parsowanie HTML","async jest synchroniczny","defer działa tylko w CSS","Nie ma różnicy"]'::jsonb, 0, 'defer gwarantuje wykonanie skryptów w kolejności ich zapisu w dokumencie tuż przed DOMContentLoaded. async uruchamia skrypt w dowolnej kolejności, zależnie od tego, który plik pobierze się pierwszy.', 'medium', 15),
(298, 6, 'DOM, Zdarzenia i Przeglądarka', 'Jak niezawodnie wysłać telemetrię lub analitykę w momencie, gdy użytkownik zamyka stronę lub opuszcza kartę?', null, 'single-choice', '["navigator.sendBeacon(url, data) lub fetch z opcją { keepalive: true }","alert(\"Do widzenia\")","setTimeout(send, 1000)","window.close()"]'::jsonb, 0, 'Metoda navigator.sendBeacon() oraz fetch z flagą keepalive gwarantują, że dane zostaną przesłane asynchronicznie przez przeglądarkę nawet po zamknięciu dokumentu.', 'medium', 15),
(299, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy API Custom Events (własne zdarzenia)?', 'const ev = new CustomEvent("uzytkownikZalogowany", {
  detail: { id: 42 },
  bubbles: true
});
element.dispatchEvent(ev);', 'single-choice', '["Pozwala na tworzenie i emitowanie własnych, semantycznych zdarzeń z niestandardowymi danymi w obiekcie .detail","Służy do zmiany nazwy zdarzenia click","Do obsługi klawiatury","Do szyfrowania zdarzeń DOM"]'::jsonb, 0, 'Konstruktor CustomEvent umożliwia architekturę sterowaną zdarzeniami (Event-Driven) wewnątrz komponentów DOM z przekazywaniem danych w polu detail.', 'medium', 15),
(300, 6, 'DOM, Zdarzenia i Przeglądarka', 'Do czego służy Web Component i Shadow DOM w przeglądarce?', null, 'single-choice', '["Do hermetyzacji stylów CSS i drzewa elementów komponentu, zapobiegając wyciekaniu stylów na zewnątrz i ingerencji stylów globalnych do wnętrza komponentu","Do renderowania cieni w grafice Canvas","Do tworzenia ciemnego motywu (Dark Mode)","Do ukrywania kodu źródłowego przed podglądem"]'::jsonb, 0, 'Shadow DOM tworzy odizolowane poddrzewo DOM, którego style i struktura są w pełni odseparowane od głównego dokumentu, umożliwiając budowę modularnych Web Components.', 'hard', 20),
(301, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka jest różnica między eksportem domyślnym (default) a nazwanym (named)?', null, 'single-choice', '["Moduł może mieć tylko jeden eksport domyślny importowany bez klamer z dowolną nazwą, oraz wiele eksportów nazwanych importowanych w klamrach { nazwa }","Eksport nazwany działa tylko w plikach JSON","Eksport domyślny jest kompilowany wolniej","Nie ma żadnej różnicy"]'::jsonb, 0, 'W ESM moduł może posiadać maksymalnie jeden "export default" (importowany jako: import Cos from "./plik.js") oraz dowolną liczbę "export const nazwa" (importowanych jako: import { nazwa } from "./plik.js").', 'easy', 10),
(302, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak zaimportować wszystkie eksporty z modułu do jednego obiektu przestrzeni nazw (namespace)?', 'import ??? as Narzedzia from "./narzedzia.js";', 'fill-gap', '["*","all","{ all }","default"]'::jsonb, 0, 'Składnia import * as Nazwa from "./modul.js" pakuje wszystkie eksporty nazwane oraz domyślne w jeden obiekt modułu.', 'easy', 10),
(303, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co zwraca wywołanie funkcji dynamicznego importu import("sciezka.js")?', 'const przycisk = document.querySelector("#zaladuj");
przycisk.onclick = async () => {
  const modul = await import("./ciezkiModul.js");
};', 'single-choice', '["Obiekt Promise rozwiązujący się do obiektu modułu (umożliwia Code Splitting i leniwe ładowanie)","Czysty tekst pliku","Funkcję synchroniczną","Tablicę bajtów"]'::jsonb, 0, 'Dynamiczny import import() zwraca Promise, co pozwala wczytywać moduły na żądanie (Lazy Loading) tylko wtedy, gdy są faktycznie potrzebne.', 'medium', 15),
(304, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym są wiązania na żywo (Live Bindings) w modułach ES?', null, 'single-choice', '["Wartości zaimportowane z modułu aktualizują się automatycznie w czasie rzeczywistym, gdy moduł eksportujący zmieni wartość swojej zmiennej","Połączeniem WebSocket","Animacją CSS w module","Wiązaniem danych w formularzu"]'::jsonb, 0, 'W przeciwieństwie do CommonJS, gdzie moduł kopiuje wartości prymitywne, moduły ES tworzą tzw. żywe referencje (Live Bindings) do eksportowanych zmiennych.', 'hard', 20),
(305, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co udostępnia meta-właściwość "import.meta" wewnątrz modułu ES?', null, 'single-choice', '["Obiekt zawierający metadane o bieżącym module (np. import.meta.url z adresem URL pliku)","Listę wszystkich zainstalowanych pakietów npm","Liczbę linii kodu w pliku","Klucze API środowiska"]'::jsonb, 0, 'import.meta udostępnia specyficzne dla środowiska informacje kontekstowe, np. pełny URL bieżącego modułu w import.meta.url.', 'medium', 15),
(306, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka jest kluczowa różnica między operatorem Nullish Coalescing (??) a logicznym OR (||)?', 'const liczba = 0;
const r1 = liczba || 10;
const r2 = liczba ?? 10;
console.log(r1, r2);', 'output-predict', '["10 i 0 (operator || traktuje 0 jako wartość fałszywą/falsy, a ?? reaguje wyłącznie na null oraz undefined)","0 i 10","10 i 10","0 i 0"]'::jsonb, 0, 'Operator ?? (Nullish Coalescing) sprawdza wyłącznie nullish values (null lub undefined). Wartości 0, false oraz pusty string "" są traktowane jako w pełni poprawne wartości.', 'medium', 15),
(307, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co zwróci Optional Chaining (?.) przy próbie wywołania metody, która nie istnieje?', 'const obj = {};
const wynik = obj.nieznanaMetoda?.();
console.log(wynik);', 'output-predict', '["undefined (zamiast rzucać błąd TypeError: obj.nieznanaMetoda is not a function)","TypeError","null","false"]'::jsonb, 0, 'Dzięki składni obj.metoda?.() silnik najpierw sprawdza, czy metoda istnieje i nie jest null/undefined; jeśli nie istnieje, zwraca undefined bez rzucania błędu.', 'easy', 10),
(308, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co robi operator przypisania z łączeniem logicznym ||= (Logical OR assignment)?', 'let tytul = "";
tytul ||= "Domyślny";
console.log(tytul);', 'output-predict', '["\"Domyślny\" (przypisuje wartość z prawej strony tylko wtedy, gdy lewa strona jest wartością fałszywą/falsy)","\"\"","SyntaxError","undefined"]'::jsonb, 0, 'x ||= y oznacza: jeśli x jest falsy, przypisz x = y. Pusty string "" jest falsy, więc zmienna tytul otrzymuje "Domyślny".', 'medium', 15),
(309, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co robi operator ??= (Logical Nullish assignment)?', 'let punkty = 0;
punkty ??= 100;
console.log(punkty);', 'output-predict', '["0 (ponieważ 0 nie jest ani null, ani undefined, więc przypisanie NIE następuje)","100","undefined","TypeError"]'::jsonb, 0, 'Operator a ??= b przypisuje nową wartość TYLKO wtedy, gdy bieżąca wartość a to null lub undefined. Dla 0 wartość pozostaje niezmieniona.', 'medium', 15),
(310, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak za pomocą Optional Chaining bezpiecznie odczytać element z tablicy, która może być nullem?', 'const tablica = null;
const el = tablica?.[0];', 'output-predict', '["undefined","TypeError","null","0"]'::jsonb, 0, 'Składnia arr?.[index] to bezpieczny dostęp do indeksów lub właściwości dynamicznych z zabezpieczeniem przed błędem w przypadku null/undefined.', 'easy', 10),
(311, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka jest główna zaleta kolekcji Map w porównaniu do tradycyjnego obiektu Object jako słownika?', null, 'single-choice', '["Kluczem w Map może być dowolny typ danych (w tym obiekty, funkcje, inne kolekcje), a kolejność wstawiania kluczy jest zawsze gwarantowana","Map jest darmowy w pamięci","Map nie ma metod get i set","W Map nie można usuwać kluczy"]'::jsonb, 0, 'Tradycyjne obiekty konwertują wszystkie klucze na stringi lub symbole. Map pozwala używać referencji do obiektów jako kluczy i posiada bezpośrednią właściwość .size.', 'easy', 10),
(312, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak sprawdzić liczbę unikalnych elementów w kolekcji Set?', 'const unikalne = new Set([1, 2, 2, 3]);
console.log(unikalne.???);', 'fill-gap', '["size","length","count","total"]'::jsonb, 0, 'Zarówno Map, jak i Set posiadają właściwość .size (a nie .length), która zwraca aktualną liczbę zgromadzonych elementów.', 'easy', 10),
(313, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka metoda pozwala błyskawicznie sprawdzić obecność elementu w kolekcji Set ze złożonością O(1)?', null, 'single-choice', '["set.has(wartość)","set.includes(wartość)","set.contains(wartość)","set.find(wartość)"]'::jsonb, 0, 'Metoda Set.prototype.has() sprawdza obecność elementu w stałym czasie O(1), podczas gdy przeszukiwanie tablicy array.includes() to O(n).', 'easy', 10),
(314, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jakie nowe metody algebry zbiorów dodano do Set w specyfikacji ECMAScript 2024?', null, 'single-choice', '["union(), intersection(), difference(), symmetricDifference()","merge(), cut(), sub()","concat(), filter(), map()","plus(), minus()"]'::jsonb, 0, 'Nowe metody zbiorów (ES2024) pozwalają bezpośrednio wyznaczać sumę (union), część wspólną (intersection) oraz różnice zbiorów bez ręcznych pętli.', 'medium', 15),
(315, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co wypisze poniższy kod wykorzystujący referencje do obiektów w Map?', 'const mapa = new Map();
mapa.set({}, 1);
mapa.set({}, 2);
console.log(mapa.size);', 'output-predict', '["2 (ponieważ dwa literały {} to dwie różne referencje do różnych obiektów w pamięci)","1","TypeError","undefined"]'::jsonb, 0, 'Map porównuje klucze według tożsamości referencji (algorytm SameValueZero). Każdy literał {} tworzy odrębny obiekt w pamięci, więc są to dwa niezależne klucze.', 'medium', 15),
(316, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym jest słaba referencja w WeakMap i jak wpływa na Garbage Collector (odśmiecacz pamięci)?', null, 'single-choice', '["Klucze w WeakMap są trzymane w sposób \"słaby\": jeśli nie ma żadnych innych referencji do obiektu-klucza w programie, obiekt może zostać automatycznie usunięty z pamięci przez Garbage Collector wraz z wartością","Klucze ulegają skasowaniu po 5 minutach","WeakMap zużywa mniej prądu","WeakMap zapisuje dane na dysku"]'::jsonb, 0, 'WeakMap zapobiega wyciekom pamięci. Gdy obiekt używany jako klucz przestaje być potrzebny, silnik automatycznie zwalnia zasoby bez ręcznego czyszczenia mapy.', 'medium', 15),
(317, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co może być kluczem w kolekcji WeakMap?', null, 'single-choice', '["Wyłącznie obiekty (oraz niezarejestrowane symbole w nowszych wersjach); prymitywy takie jak stringi czy liczby są niedozwolone","Tylko stringi","Dowolny typ","Tylko liczby całkowite"]'::jsonb, 0, 'Wartości prymitywne nie posiadają tożsamości pamięciowej i cyklu życia zarządzanego przez Garbage Collector, dlatego kluczami w WeakMap mogą być wyłącznie obiekty.', 'medium', 15),
(318, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Dlaczego po kolekcji WeakMap lub WeakSet NIE MOŻNA iterować pętlą (brak for...of, keys, size)?', null, 'single-choice', '["Ponieważ działanie Garbage Collectora jest niedeterministyczne w czasie, co mogłoby dawać różne wyniki iteracji z ułamka sekundy na ułamek sekundy","To przeoczenie twórców standardu","Bo dane są zaszyfrowane","Bo WeakMap nie ma pamięci RAM"]'::jsonb, 0, 'Gdyby dało się sprawdzić .size lub iterować po WeakMap, zachowanie programu zależałoby od tego, w którym dokładnie momencie uruchomił się proces Garbage Collection silnika.', 'hard', 20),
(319, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do jakiego celu w praktyce najczęściej używa się WeakMap?', null, 'single-choice', '["Do przechowywania prywatnych danych/stanów powiązanych z węzłami DOM lub instancjami klas bez ryzyka wycieku pamięci po ich usunięciu z drzewa","Do sortowania bazy danych","Do pobierania plików przez sieć","Do szyfrowania haseł"]'::jsonb, 0, 'Powiązanie danych z węzłem DOM za pomocą WeakMap gwarantuje, że gdy węzeł zostanie usunięty z dokumentu i odpięty, jego metadane w WeakMap również zostaną automatycznie sprzątnięte.', 'medium', 15),
(320, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy API FinalizationRegistry w JavaScript (ES2021)?', null, 'single-choice', '["Pozwala zarejestrować funkcję callback uruchamianą w momencie, gdy dany obserwowany obiekt zostanie faktycznie zniszczony i zwolniony przez Garbage Collector","Do finalizowania transakcji płatniczych","Do kończenia działania skryptu","Do zamykania bazy danych"]'::jsonb, 0, 'FinalizationRegistry pozwala na czyszczenie zewnętrznych zasobów (np. uchwytów WebAssembly lub deskryptorów plików) po zebraniu obiektu JS przez GC.', 'hard', 20),
(321, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak zdefiniować funkcję generatora w JavaScript?', 'function??? liczby() {
  yield 1;
  yield 2;
}', 'fill-gap', '["*"," generator","#","&"]'::jsonb, 0, 'Gwiazdka po słowie function (function* nazwa()) deklaruje generator zwracający obiekt Generator (będący jednocześnie iteratorem i obiektem iterowalnym).', 'easy', 10),
(322, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co robi słowo kluczowe "yield" wewnątrz generatora?', null, 'single-choice', '["Wstrzymuje (pauzuje) wykonywanie generatora, zwraca bieżącą wartość na zewnątrz w obiekcie { value, done: false } i zachowuje stan wykonania funkcji na później","Kończy działanie programu","Resetuje zmienne do zera","Działa identycznie jak throw"]'::jsonb, 0, 'yield zamraża stan generatora. Kolejne wywołanie metody .next() wznawia wykonanie dokładnie od linii z yield.', 'easy', 10),
(323, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co robi delegacja generatora za pomocą instrukcji "yield*"?', 'function* g1() { yield 1; yield 2; }
function* g2() {
  yield* g1();
  yield 3;
}
console.log([...g2()]);', 'output-predict', '["[1, 2, 3] (deleguje iterację do innego generatora lub obiektu iterowalnego)","[g1, 3]","[undefined, 3]","TypeError"]'::jsonb, 0, 'Instrukcja yield* przekazuje kontrolę innemu generatorowi lub strukturze iterowalnej (np. tablicy), wyemitowując po kolei wszystkie jej elementy.', 'medium', 15),
(324, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak przekazać wartość DO WNĘTRZA generatora w trakcie jego działania (komunikacja dwukierunkowa)?', 'function* dialog() {
  const odp = yield "Jak masz na imię?";
  yield `Cześć ${odp}`;
}
const it = dialog();
it.next();
console.log(it.next("Kuba").value);', 'output-predict', '["\"Cześć Kuba\" (argument przekazany w kolejnym .next(\"Kuba\") staje się wartością zwracaną przez wyrażenie yield)","\"Cześć undefined\"","TypeError","\"Jak masz na imię?\""]'::jsonb, 0, 'Metoda generator.next(wartosc) wstrzykuje podaną wartość do wnętrza generatora w miejsce wstrzymanego wcześniej wyrażenia yield.', 'hard', 20),
(325, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaki symbol jest wymagany, aby własny obiekt stał się iterowalny (np. w pętli for...of lub ze spreadem [...obj])?', 'const obj = {
  *[???]() {
    yield 10;
    yield 20;
  }
};', 'fill-gap', '["Symbol.iterator","Symbol.iterable","Symbol.toIterator","Symbol.loop"]'::jsonb, 0, 'Protokół iteracji w JavaScript wymaga zdefiniowania metody pod kluczem [Symbol.iterator], która zwraca iterator.', 'medium', 15),
(326, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym charakteryzuje się typ prymitywny Symbol w JavaScript?', 'const s1 = Symbol("opis");
const s2 = Symbol("opis");
console.log(s1 === s2);', 'output-predict', '["false (każdy wygenerowany Symbol jest całkowicie unikalny i niepowtarzalny w całym programie)","true","undefined","TypeError"]'::jsonb, 0, 'Każdy utworzony Symbol() jest gwarantowanie unikalną wartością prymitywną, nawet jeśli podano do niego dokładnie taki sam opis.', 'easy', 10),
(327, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak utworzyć lub pobrać współdzielony Symbol ze specjalnego globalnego rejestru symboli?', null, 'single-choice', '["Symbol.for(\"nazwaKlucza\")","Symbol.get(\"nazwaKlucza\")","new Symbol(\"nazwaKlucza\")","Symbol.global(\"nazwaKlucza\")"]'::jsonb, 0, 'Metoda Symbol.for(klucz) przeszukuje globalny rejestr symboli: zwraca istniejący symbol o podanym kluczu lub tworzy nowy, jeśli taki jeszcze nie istniał.', 'medium', 15),
(328, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy dobrze znany symbol Symbol.toStringTag?', 'class MojaKlasa {
  get [Symbol.toStringTag]() { return "MojaKlasa"; }
}
console.log(Object.prototype.toString.call(new MojaKlasa()));', 'output-predict', '["\"[object MojaKlasa]\"","\"[object Object]\"","TypeError","undefined"]'::jsonb, 0, 'Symbol.toStringTag pozwala na dostosowanie ciągu znaków zwracanego przy domyślnej konwersji do stringa przez Object.prototype.toString().', 'medium', 15),
(329, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czy właściwości obiektu o kluczach Symbol pojawiają się w Object.keys() lub for...in?', 'const id = Symbol("id");
const obj = { [id]: 123, nazwa: "Test" };
console.log(Object.keys(obj));', 'output-predict', '["[\"nazwa\"] (klucze Symbol są pomijane przez Object.keys, for...in oraz JSON.stringify)","[\"id\", \"nazwa\"]","[]","TypeError"]'::jsonb, 0, 'Klucze Symbol są nieprzeliczalne w standardowych pętlach. Aby je pobrać, należy użyć Object.getOwnPropertySymbols(obj) lub Reflect.ownKeys(obj).', 'medium', 15),
(330, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy Symbol.toPrimitive?', null, 'single-choice', '["Umożliwia pełną kontrolę nad sposobem konwersji własnego obiektu na wartość prymitywną w zależności od wymaganego typu (hint: \"number\", \"string\" lub \"default\")","Służy do tworzenia prostych zmiennych","Konwertuje obiekty na format XML","Kasuje metody z obiektu"]'::jsonb, 0, 'Metoda pod symbolem Symbol.toPrimitive(hint) zastępuje tradycyjne metody valueOf i toString, decydując o konwersji np. przy dodawaniu lub rzutowaniu na string.', 'hard', 20),
(331, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym jest typ BigInt i jak tworzy się literał typu BigInt?', 'const wielkaLiczba = 9007199254740991???;
const b2 = BigInt(123);', 'fill-gap', '["n (np. 9007199254740991n)","bi","L","b"]'::jsonb, 0, 'BigInt służy do reprezentacji liczb całkowitych o dowolnej precyzji (ponad limit Number.MAX_SAFE_INTEGER) i oznacza się go literą n na końcu liczby.', 'easy', 10),
(332, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co się stanie przy próbie dodania BigInt do zwykłego typu Number (np. 10n + 5)?', 'const wynik = 10n + 5;', 'output-predict', '["TypeError: Cannot mix BigInt and other types, use explicit conversions","15n","15","NaN"]'::jsonb, 0, 'JavaScript celowo zabrania niejawnego mieszania typów BigInt i Number ze względu na ryzyko utraty precyzji. Wymagana jest jawna konwersja (np. 10n + BigInt(5)).', 'medium', 15),
(333, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaki jest wynik dzielenia całkowitego dla typu BigInt?', 'const wynik = 5n / 2n;
console.log(wynik);', 'output-predict', '["2n (następuje obcięcie części ułamkowej w stronę zera - brak liczb zmiennoprzecinkowych w BigInt)","2.5n","2.5","TypeError"]'::jsonb, 0, 'BigInt operuje wyłącznie na liczbach całkowitych, dlatego dzielenie zaokrągla wynik zawsze w dół do liczby całkowitej (obcina resztę).', 'medium', 15),
(334, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czy BigInt można bezpośrednio zserializować za pomocą JSON.stringify()?', 'JSON.stringify({ wiek: 25n });', 'output-predict', '["TypeError: Do not know how to serialize a BigInt","{\"wiek\":\"25n\"}","{\"wiek\":25}","null"]'::jsonb, 0, 'Format JSON nie posiada typu BigInt. Serializacja obiektu z BigInt rzuca TypeError, chyba że zaimplementujemy BigInt.prototype.toJSON.', 'hard', 20),
(335, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka jest wartość Number.MAX_SAFE_INTEGER w standardowym formacie IEEE-754?', null, 'single-choice', '["2^53 - 1 (dokładnie 9007199254740991)","2^32 - 1","2^64 - 1","Nieskończoność"]'::jsonb, 0, 'Format 64-bitowy zmiennoprzecinkowy (Double Precision) przeznacza 53 bity na mantysę, co pozwala na bezpieczne operacje bez utraty precyzji do liczby 9 007 199 254 740 991.', 'medium', 15),
(336, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak w nowoczesnych wyrażeniach regularnych zdefiniować nazwaną grupę przechwytującą (Named Capture Group)?', 'const reg = /(???\d{4})-(?<miesiac>\d{2})-(?<dzien>\d{2})/;
const m = reg.exec("2026-09-17");
console.log(m.groups.rok);', 'fill-gap', '["?<rok>","rok:","$rok=","&rok;"]'::jsonb, 0, 'Składnia (?<nazwa>wzorzec) tworzy nazwaną grupę, której wynik trafia bezpośrednio do obiektu matches.groups.nazwa.', 'medium', 15),
(337, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy flaga "s" (dotAll) w wyrażeniach regularnych?', null, 'single-choice', '["Sprawia, że kropka (.) dopasowuje ABSOLUTNIE KAŻDY znak, włączając w to znaki nowej linii (\\n i \\r)","Włącza wyszukiwanie tylko małych liter","Przyspiesza przeszukiwanie","Ignoruje spacje"]'::jsonb, 0, 'Domyślnie kropka w RegExp nie dopasowuje znaków końca linii. Flaga s (dotAll) usuwa to ograniczenie.', 'easy', 10),
(338, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co umożliwia metoda String.prototype.matchAll(regex)?', null, 'single-choice', '["Zwraca iterator zawierający pełne obiekty dopasowań (wraz z grupami przechwytującymi i indeksami) dla wszystkich wystąpień globalnego wzorca","Podmienia wszystkie znaki","Zwraca tablicę samych stringów","Sprawdza tylko czy pasuje (true/false)"]'::jsonb, 0, 'matchAll() eliminuje potrzebę żmudnego wykonywania pętli while z regex.exec(), zwracając wygodny iterator po wszystkich dopasowaniach.', 'medium', 15),
(339, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym jest pozytywne spojrzenie wstecz (Positive Lookbehind) w RegExp?', 'const reg = /(?<=\$)\d+/;
console.log(reg.exec("$100")[0]);', 'output-predict', '["\"100\" (dopasowuje cyfry tylko wtedy, gdy są poprzedzone znakiem $, ale sam znak $ nie wchodzi do wyniku)","\"$100\"","\"$\"","null"]'::jsonb, 0, 'Składnia (?<=wzorzec) sprawdza warunek poprzedzający bez włączania go do ostatecznego tekstu dopasowania.', 'hard', 20),
(340, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy flaga "d" (hasIndices) w RegExp wprowadzona w ES2022?', null, 'single-choice', '["Generuje tablicę .indices zawierającą dokładne indeksy startowe i końcowe [start, end] dla każdej dopasowanej grupy w oryginalnym tekście","Włącza tryb debugowania wyrażeń","Dopasowuje tylko cyfry","Ignoruje wielkość liter"]'::jsonb, 0, 'Flaga d dostarcza precyzyjnych współrzędnych znakowych dla każdej grupy, co jest nieocenione w edytorach kodu i parserach składni.', 'hard', 20),
(341, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak za pomocą Intl.NumberFormat sformatować liczbę jako walutę (np. PLN w języku polskim)?', 'const fmt = new Intl.NumberFormat("pl-PL", {
  style: "currency",
  currency: "PLN"
});
console.log(fmt.format(1250.5));', 'output-predict', '["\"1 250,50 zł\" (z poprawną spacją nierozdzielającą i przecinkiem)","\"1250.5 PLN\"","\"$1,250.50\"","\"PLN 1250,5\""]'::jsonb, 0, 'Intl.NumberFormat automatycznie formatuje liczby według rygorystycznych norm typograficznych i walutowych danego kraju.', 'easy', 10),
(342, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy obiekt Intl.RelativeTimeFormat?', 'const rtf = new Intl.RelativeTimeFormat("pl", { numeric: "auto" });
console.log(rtf.format(-1, "day"));', 'output-predict', '["\"wczoraj\"","\"1 dzień temu\"","\"jutro\"","\"-1 dzień\""]'::jsonb, 0, 'Intl.RelativeTimeFormat automatycznie generuje relatywne określenia upływu czasu (np. "wczoraj", "za 3 godziny", "w zeszłym miesiącu") w dowolnym języku.', 'medium', 15),
(343, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy obiekt Intl.ListFormat?', 'const lf = new Intl.ListFormat("pl", { style: "long", type: "conjunction" });
console.log(lf.format(["jabłko", "banan", "gruszka"]));', 'output-predict', '["\"jabłko, banan i gruszka\"","\"jabłko, banan, gruszka\"","\"jabłko lub banan lub gruszka\"","\"[jabłko, banan, gruszka]\""]'::jsonb, 0, 'Intl.ListFormat zamienia tablicę stringów w naturalnie brzmiącą listę z poprawnym spójnikiem (np. "i", "oraz", "lub") dopasowanym do języka.', 'medium', 15),
(344, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak za pomocą Intl.Segmenter podzielić tekst na słowa lub emoji z uwzględnieniem zasad lingwistycznych?', null, 'single-choice', '["Używając new Intl.Segmenter(locale, { granularity: \"word\" })","Używając text.split(\" \")","Za pomocą funkcji text.toWords()","Metodą JSON.segment()"]'::jsonb, 0, 'text.split(" ") zawodzi przy językach azjatyckich (np. japoński, chiński) oraz przy złożonych emoji (ZWJ). Intl.Segmenter poprawnie dzieli tekst na jednostki leksykalne.', 'hard', 20),
(345, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co rozwiązuje Intl.Collator w porównaniu do zwykłego a > b przy sortowaniu łańcuchów znaków?', null, 'single-choice', '["Poprawne sortowanie słów z uwzględnieniem znaków diakrytycznych, wielkości liter i lokalnych reguł alfabetycznych danego państwa","Szyfrowanie ciągów znaków","Sprawdzanie pisowni","Kompresję tekstu"]'::jsonb, 0, 'Intl.Collator zapewnia wysokowydajne porównywanie ciągów tekstowych zgodnie z regułami ortograficznymi wskazanego języka.', 'easy', 10),
(346, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jaka nowa metoda tablicowa (ES2023) wyszukuje ostatni pasujący element od końca tablicy?', 'const liczby = [1, 10, 5, 20, 3];
const ostatniaDuza = liczby.???(x => x > 8);', 'fill-gap', '["findLast","findBack","lastFind","findEnd"]'::jsonb, 0, 'Metody findLast() oraz findLastIndex() przeszukują tablicę od końca (od ostatniego indeksu do zerowego), zwracając pierwsze pasujące dopasowanie.', 'easy', 10),
(347, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Jak za pomocą nowości z ES2024 pogrupować elementy tablicy w obiekt kategorii?', 'const produkty = [
  { kategoria: "owoce", nazwa: "jabłko" },
  { kategoria: "warzywa", nazwa: "marchew" },
  { kategoria: "owoce", nazwa: "banan" }
];
const grupy = Object.???(produkty, p => p.kategoria);', 'fill-gap', '["groupBy","group","partition","categorize"]'::jsonb, 0, 'Metody Object.groupBy() oraz Map.groupBy() (ES2024) to długo wyczekiwane standardowe mechanizmy grupowania kolekcji według podanego kryterium.', 'medium', 15),
(348, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Do czego służy metoda Promise.withResolvers() wprowadzona w ES2024?', 'const { promise, resolve, reject } = Promise.withResolvers();', 'single-choice', '["Udostępnia w jednym obiekcie gotową obietnicę wraz z jej zewnętrznymi funkcjami resolve i reject, bez konieczności zagnieżdżania kodu w new Promise((res, rej) => ...)","Automatycznie retry’uje żądanie 3 razy","Rozwiązuje problemy z CORS","Służy do anulowania żądań"]'::jsonb, 0, 'Promise.withResolvers() upraszcza wzorzec Deferred Promise, zwracając obiekt z { promise, resolve, reject } dostępnymi na zewnątrz.', 'medium', 15),
(349, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Czym są atrybuty importu (Import Attributes / Import Assertions)?', 'import dane from "./dane.json" with { type: "json" };', 'single-choice', '["Składnią pozwalającą na jawne wskazanie oczekiwanego typu modułu (np. json lub css), zapobiegając atakom polegającym na wykonaniu złośliwego kodu JS zamaskowanego jako JSON","Wersjonowaniem pakietów npm","Formatowaniem kodu w pliku","Zabezpieczeniem przed utratą pamięci"]'::jsonb, 0, 'Import Attributes zapewniają bezpieczeństwo i standaryzację importowania plików nierozszerzalnych (JSON, CSS Modules) w środowiskach przeglądarek i Node.js.', 'hard', 20),
(350, 7, 'Nowoczesny JS (ES6+) i Moduły', 'Co umożliwia flaga "v" w RegExp wprowadzona w ES2024?', null, 'single-choice', '["Zaawansowane operacje na zbiorach znaków (odejmowanie i część wspólną klas znaków: [[a-z]--[aeiou]]) oraz pełne wsparcie dla właściwości ciągów Unicode","Sprawdzanie poprawności składni regex","Weryfikację wersji silnika JS","Podwójną szybkość działania"]'::jsonb, 0, 'Flaga v (unicodeSets) to potężne uaktualnienie flagi u, umożliwiające m.in. operacje na zbiorach znaków (różnica, iloczyn) w klasach znaków [].', 'hard', 20),
(351, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest TypeScript w relacji do języka JavaScript?', null, 'single-choice', '["Ścisłym nadzbiorem (superset) języka JavaScript ze statycznym systemem typowania, który w procesie kompilacji jest transpilowany do czystego kodu JavaScript","Całkowicie osobnym językiem działającym tylko w specjalnej maszynie wirtualnej","Zamiennikiem dla silnika Node.js","Bazą danych dla kodu JS"]'::jsonb, 0, 'Każdy poprawny kod JavaScript jest poprawnym kodem TypeScript. TS dodaje analizę typów w czasie kompilacji, po czym usuwa wszystkie adnotacje typów (type erasure).', 'easy', 10),
(352, 8, 'TypeScript i Statyczne Typowanie', 'Co dzieje się z typami, interfejsami i generykami TypeScript podczas uruchamiania kodu w przeglądarce?', null, 'single-choice', '["Zostają całkowicie usunięte w czasie kompilacji (Type Erasure) i nie istnieją w środowisku wykonawczym (runtime)","Zostają zamienione na obiekty JSON w pamięci RAM","Są sprawdzane dynamicznie podczas każdego kliknięcia","Są szyfrowane kluczem publicznym"]'::jsonb, 0, 'TypeScript to narzędzie wyłącznie czasu kompilacji (Compile-time). W wygenerowanym pliku .js nie ma ani jednego typu, więc typy nie wpływają na wielkość ani szybkość programu w runtime.', 'easy', 10),
(353, 8, 'TypeScript i Statyczne Typowanie', 'Która flaga w tsconfig.json włącza rygorystyczne sprawdzanie typów (w tym noImplicitAny, strictNullChecks)?', '{
  "compilerOptions": {
    "???": true
  }
}', 'fill-gap', '["strict","safeMode","strongTypes","strictChecks"]'::jsonb, 0, 'Flaga "strict": true włącza całą rodzinę restrykcyjnych reguł sprawdzania typów, zapobiegając wielu potencjalnym błędom.', 'easy', 10),
(354, 8, 'TypeScript i Statyczne Typowanie', 'Co oznacza flaga "noImplicitAny" w kompilatorze TypeScript?', null, 'single-choice', '["Zgłasza błąd, jeśli kompilator nie jest w stanie wywnioskować typu zmiennej lub parametru i musiałby niejawnie przypisać typ \"any\"","Zabrania używania słowa let","Wyłącza moduły ES","Wymusza użycie interfejsów zamiast klas"]'::jsonb, 0, 'noImplicitAny zmusza programistę do jawnego podania typu wszędzie tam, gdzie mechanizm wnioskowania typów (Type Inference) nie może jednoznacznie ustalić typu.', 'medium', 15),
(355, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służą pliki z rozszerzeniem ".d.ts" (pliki deklaracji)?', null, 'single-choice', '["Zawierają wyłącznie definicje typów dla istniejących bibliotek napisanych w czystym JavaScript (bez kodu wykonywalnego)","Są plikami baz danych dla TypeScript","Służą do testowania jednostkowego","Zawierają style komponentów"]'::jsonb, 0, 'Pliki *.d.ts opisują kształt i sygnatury zewnętrznego kodu JavaScript, umożliwiając autouzupełnianie i sprawdzanie typów (np. paczki @types/*).', 'easy', 10),
(356, 8, 'TypeScript i Statyczne Typowanie', 'Jaka jest kluczowa różnica między typem "any" a typem "unknown"?', null, 'single-choice', '["\"any\" całkowicie wyłącza sprawdzanie typów, a \"unknown\" jest typem bezpiecznym (type-safe) – nie można wywołać metody ani przypisać wartości bez wcześniejszego zawężenia typu (type narrowing)","\"unknown\" działa tylko dla liczb","\"any\" jest nowszym typem wprowadzonym w TS 5","Nie ma żadnej różnicy"]'::jsonb, 0, 'unknown zmusza programistę do sprawdzenia typu (np. za pomocą typeof lub instanceof) przed wykonaniem jakiejkolwiek operacji na zmiennej, zapobiegając błędom runtime.', 'medium', 15),
(357, 8, 'TypeScript i Statyczne Typowanie', 'Co reprezentuje typ "never" w TypeScript?', null, 'single-choice', '["Wartość, która nigdy nie wystąpi – np. typ zwracany przez funkcję, która zawsze rzuca wyjątek (throw) lub zawiera nieskończoną pętlę","Pusty ciąg znaków \"\"","Typ dla wartości null","Wartość logiczną false"]'::jsonb, 0, 'never to dolny typ (bottom type) w hierarchii TypeScript. Oznacza stan niemożliwy do osiągnięcia w kodzie.', 'medium', 15),
(358, 8, 'TypeScript i Statyczne Typowanie', 'Jaka jest różnica między typem "void" a "undefined" jako typem zwracanym przez funkcję?', 'function f1(): void {}
function f2(): undefined { return undefined; }', 'single-choice', '["Funkcja z typem \"void\" ignoruje zwracaną wartość (może nie mieć return lub mieć return;), a funkcja z \"undefined\" wymaga jawnej instrukcji zwracającej undefined","void jest typem dla liczb","undefined nie istnieje w TS","To pojęcia tożsame"]'::jsonb, 0, 'void oznacza, że wywołujący nie powinien polegać na żadnej zwracanej wartości (choć w JS funkcja bez return zwraca undefined). undefined jako typ wymusza jawny return undefined.', 'medium', 15),
(359, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest krotka (Tuple) w TypeScript?', 'const rekord: [string, number, boolean] = ["Jan", 30, true];', 'single-choice', '["Tablicą o ściśle określonej liczbie elementów, w której każdy element na określonej pozycji ma z góry zdefiniowany konkretny typ","Obiektem JSON","Funkcją zwracającą 3 wartości","Listą jednokierunkową"]'::jsonb, 0, 'Krotka (Tuple) definiuje tablicę o ustalonym rozmiarze i typach dla każdego kolejnego indeksu.', 'easy', 10),
(360, 8, 'TypeScript i Statyczne Typowanie', 'Co się stanie przy próbie przypisania wartości typu "unknown" do zmiennej typu "string" bez rzutowania?', 'let u: unknown = "tekst";
let s: string = u;', 'output-predict', '["Błąd kompilatora: Type \"unknown\" is not assignable to type \"string\"","Skompiluje się bez błędu","Wartość s zamieni się w null","Zmienna u zostanie usunięta"]'::jsonb, 0, 'Typ unknown można przypisać tylko do innego unknown lub any. Aby przypisać go do string, należy najpierw sprawdzić typ (np. if (typeof u === "string")) lub użyć rzutowania.', 'medium', 15),
(361, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest scalanie deklaracji (Declaration Merging), które jest możliwe dla interfejsów, ale niemożliwe dla aliasów "type"?', 'interface User { imie: string; }
interface User { wiek: number; }
// Obiekt typu User ma teraz oba pola: imie i wiek!', 'single-choice', '["Zdolnością do automatycznego łączenia wielu definicji tego samego interfejsu w jedną całość o tej samej nazwie","Kompresją kodu","Usuwaniem pól z pamięci","Zabezpieczeniem przed kolizją nazw"]'::jsonb, 0, 'Dwa interfejsy o tej samej nazwie w tym samym zasięgu automatycznie scalają swoje właściwości. Alias type User = ... spowodowałby błąd Duplicate identifier.', 'medium', 15),
(362, 8, 'TypeScript i Statyczne Typowanie', 'Co potrafi zdefiniować alias typu (type), czego NIE MOŻNA zdefiniować za pomocą interfejsu (interface)?', null, 'single-choice', '["Unie typów prymitywnych (Union Types, np. type Status = \"sukces\" | \"blad\") oraz typy generyczne z conditional types","Metody w klasach","Obiekty z polami opcjonalnymi","Tablice obiektów"]'::jsonb, 0, 'Interfejs może definiować wyłącznie kształt obiektów lub funkcji. Nie potrafi bezpośrednio reprezentować unii prymitywów (np. type ID = string | number).', 'medium', 15),
(363, 8, 'TypeScript i Statyczne Typowanie', 'Jak w interfejsie oznaczyć pole, którego nie można modyfikować po zainicjalizowaniu obiektu?', 'interface Konfiguracja {
  ??? id: string;
}', 'fill-gap', '["readonly","const","immutable","final"]'::jsonb, 0, 'Modyfikator readonly uniemożliwia zmianę wartości właściwości po utworzeniu instancji obiektu.', 'easy', 10),
(364, 8, 'TypeScript i Statyczne Typowanie', 'Jak w interfejsie lub typie zdefiniować pole opcjonalne (które może zostać pominięte)?', 'interface Produkt {
  nazwa: string;
  opis???: string;
}', 'fill-gap', '["?","!","*","optional"]'::jsonb, 0, 'Znak zapytania po nazwie właściwości (opis?: string) oznacza, że dane pole jest opcjonalne (jego typ to string | undefined).', 'easy', 10),
(365, 8, 'TypeScript i Statyczne Typowanie', 'Jak w TypeScript zapisać sygnaturę indeksu (Index Signature) dla obiektu o nieznanych z góry kluczach tekstowych?', 'interface Slownik {
  [klucz: string]: number;
}', 'single-choice', '["[klucz: string]: number (dowolny string jako klucz i liczba jako wartość)","keyof string = number","{ *string: number }","Dictionary<string, number>"]'::jsonb, 0, 'Index signature [key: string]: number pozwala na definiowanie obiektów o dynamicznych kluczach z określonym typem wartości.', 'medium', 15),
(366, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest unia dyskryminacyjna (Discriminated Union / Tagged Union)?', 'type Odpowiedz =
  | { status: "sukces"; dane: string }
  | { status: "blad"; kod: number };', 'single-choice', '["Wzorcem unii obiektów posiadających wspólne pole literałowe (tzw. tag / dyskryminator), które pozwala kompilatorowi na bezpieczne zawężenie typu w instrukcji switch/if","Zabronioną składnią w TypeScript","Typem z losową wartością","Funkcją asynchroniczną"]'::jsonb, 0, 'Wspólna właściwość literałowa (tutaj: status: "sukces" | "blad") umożliwia TypeScriptowi precyzyjne odgadnięcie pozostałych pól obiektu wewnątrz bloku if/switch.', 'medium', 15),
(367, 8, 'TypeScript i Statyczne Typowanie', 'Jak zdefiniować własnego strażnika typu (Custom Type Guard)?', 'function czyRyba(zwierze: Ryba | Ptak): zwierze ??? Ryba {
  return (zwierze as Ryba).plywaj !== undefined;
}', 'fill-gap', '["is","instanceof","typeof","as"]'::jsonb, 0, 'Predykat typu zwierze is Ryba informuje kompilator TypeScript, że jeśli funkcja zwróci true, zmienna w danym bloku ma bezwzględnie typ Ryba.', 'medium', 15),
(368, 8, 'TypeScript i Statyczne Typowanie', 'Co robi operator przecięcia (Intersection Type: &)?', 'type Pracownik = Osoba & Uprawnienia;', 'single-choice', '["Łączy wiele typów w jeden, wymagając, aby obiekt posiadał WSZYSTKIE właściwości ze wszystkich połączonych typów","Wybiera tylko jedną z opcji (lub)","Usuwa wspólne pola","Tworzy typ never"]'::jsonb, 0, 'Typ przecięcia (A & B) to iloczyn typów: obiekt musi spełniać równocześnie wymagania typu A oraz typu B.', 'easy', 10),
(369, 8, 'TypeScript i Statyczne Typowanie', 'Jak w instrukcji switch sprawdzić, czy obsłużono absolutnie wszystkie możliwe warianty unii (Exhaustive Checking)?', 'function sprawdz(akcja: Akcja) {
  switch (akcja.typ) {
    case "A": return 1;
    case "B": return 2;
    default:
      const _niedozwolone: ??? = akcja;
      throw new Error("Nieobsłużony typ");
  }
}', 'fill-gap', '["never","unknown","any","void"]'::jsonb, 0, 'Przypisanie do zmiennej typu never w gałęzi default zgłosi błąd kompilacji, jeśli w przyszłości dodamy nowy wariant do unii Akcja i zapomnimy go obsłużyć.', 'hard', 20),
(370, 8, 'TypeScript i Statyczne Typowanie', 'Jak zawęzić typ obiektu za pomocą operatora "in"?', 'if ("plywaj" in zwierze) {
  zwierze.plywaj();
}', 'single-choice', '["Kompilator TS automatycznie zawęża typ zwierzęcia do wariantów, które posiadają właściwość o nazwie \"plywaj\"","Operator \"in\" rzuca błąd w TS","Zawęża do typu boolean","Działa tylko dla tablic"]'::jsonb, 0, 'TypeScript rozumie operator in języka JavaScript i automatycznie filtruje unie obiektów pod kątem obecności sprawdzanego klucza.', 'medium', 15),
(371, 8, 'TypeScript i Statyczne Typowanie', 'Czym są typy generyczne (Generics) w TypeScript?', 'function tozsamosc<T>(arg: T): T {
  return arg;
}', 'single-choice', '["Zmiennymi typów, które pozwalają na tworzenie reużywalnych komponentów i funkcji działających z różnymi typami przy zachowaniu pełnego bezpieczeństwa typowania","Typami przechowującymi dane w formacie XML","Plikami konfiguracyjnymi","Typami dla silnika bazy danych"]'::jsonb, 0, 'Generyki pozwalają przekazywać typ jako parametr (<T>), gwarantując, że np. typ zwracany z funkcji będzie identyczny z typem przekazanego argumentu.', 'easy', 10),
(372, 8, 'TypeScript i Statyczne Typowanie', 'Jak nałożyć ograniczenie (Generic Constraint) na typ generyczny T, aby musiał posiadać właściwość .length?', 'function logujDlugosc<T ??? { length: number }>(arg: T) {
  console.log(arg.length);
}', 'fill-gap', '["extends","implements",":","satisfies"]'::jsonb, 0, 'Słowo kluczowe extends w deklaracji typu generycznego (<T extends K>) ogranicza dozwolone typy do tych, które spełniają strukturę K.', 'medium', 15),
(373, 8, 'TypeScript i Statyczne Typowanie', 'Jak zdefiniować domyślną wartość dla typu generycznego?', 'interface Odpowiedz<T = string> {
  dane: T;
}', 'single-choice', '["Podając znak równości po nazwie generyka: <T = string>","Podając <T : string>","Używając default T","Nie można ustawiać wartości domyślnych"]'::jsonb, 0, 'Składnia <T = DomyślnyTyp> sprawia, że jeśli programista nie poda jawnego typu generycznego (Odpowiedz zamiast Odpowiedz<number>), zostanie podstawiony typ domyślny.', 'easy', 10),
(374, 8, 'TypeScript i Statyczne Typowanie', 'Jak za pomocą generyków i operatora keyof bezpiecznie pobrać właściwość obiektu?', 'function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}', 'single-choice', '["K extends keyof T gwarantuje, że przekazany klucz na pewno istnieje w obiekcie, a typem wyniku jest precyzyjnie T[K]","Klucz musi być zawsze liczbą","Funkcja zwróci any","Spowoduje błąd kompilacji"]'::jsonb, 0, 'To wzorzec Indexed Access Type z generykami: kompilator uniemożliwi przekazanie nieistniejącej nazwy właściwości i idealnie wywnioskuje typ zwracanej wartości.', 'hard', 20),
(375, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służy typ generyczny Promise<T>?', null, 'single-choice', '["Określa typ wartości, do której rozwiąże się asynchroniczna obietnica po zakończeniu (np. Promise<User>)","Wstrzymuje wykonanie kodu w wątku","Zamienia kod na synchroniczny","Jest błędem składni"]'::jsonb, 0, 'Promise<T> precyzyjnie definiuje, jakiego typu danych należy spodziewać się po użyciu await lub w argumencie callbacka .then(val => ...).', 'easy', 10),
(376, 8, 'TypeScript i Statyczne Typowanie', 'Co robi wbudowany typ narzędziowy Partial<T>?', 'type UserUpdate = Partial<User>;', 'single-choice', '["Tworzy nowy typ, w którym absolutnie WSZYSTKIE właściwości typu T stają się opcjonalne (?)","Usuwa połowę pól","Czyni pola tylko do odczytu","Zwraca pierwszy element"]'::jsonb, 0, 'Partial<T> zamienia każdą właściwość w obiekcie na opcjonalną, co jest idealne np. dla funkcji aktualizacji częściowej (PATCH).', 'easy', 10),
(377, 8, 'TypeScript i Statyczne Typowanie', 'Jaka jest różnica między Pick<T, K> a Omit<T, K>?', null, 'single-choice', '["Pick wybiera tylko wskazane klucze K z typu T, a Omit usuwa wskazane klucze K z typu T, pozostawiając całą resztę","Pick działa tylko na tablicach","Omit dodaje nowe pola","To synonimy"]'::jsonb, 0, 'Pick<User, "id" | "email"> tworzy typ z samymi polami id i email. Omit<User, "haslo"> tworzy typ ze wszystkimi polami User z wyjątkiem hasła.', 'easy', 10),
(378, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służy typ Record<K, T>?', 'type Konfiguracja = Record<"prod" | "dev", { url: string }>;', 'single-choice', '["Tworzy typ obiektu, którego klucze należą do zbioru K, a wartości mają typ T","Służy do nagrywania dźwięku","Jest odpowiednikiem tablicy w C#","Tworzy klasę bazową"]'::jsonb, 0, 'Record<K, T> pozwala na wygodne definiowanie słowników i map obiektowych o zadanym zbiorze kluczy i jednolitym typie wartości.', 'medium', 15),
(379, 8, 'TypeScript i Statyczne Typowanie', 'Jak wyciągnąć typ zwracany z istniejącej funkcji za pomocą typów narzędziowych?', 'function stworzRaport() {
  return { id: 1, wygenerowano: new Date() };
}
type Raport = ???<typeof stworzRaport>;', 'fill-gap', '["ReturnType","ExtractReturn","ResultOf","TypeOf"]'::jsonb, 0, 'Typ ReturnType<T> wydobywa typ wartości zwracanej z sygnatury funkcji bez konieczności jej ręcznego dublowania.', 'medium', 15),
(380, 8, 'TypeScript i Statyczne Typowanie', 'Co robi typ Exclude<T, U>?', 'type T1 = Exclude<"a" | "b" | "c", "a">;', 'output-predict', '["\"b\" | \"c\" (usuwa z unii T warianty przypisywalne do U)","\"a\"","never","undefined"]'::jsonb, 0, 'Exclude<T, U> filtruje unię typów, odrzucając te składowe, które pasują do typu U.', 'medium', 15),
(381, 8, 'TypeScript i Statyczne Typowanie', 'Czym są typy warunkowe (Conditional Types)?', 'type CzyString<T> = T extends string ? "tak" : "nie";', 'single-choice', '["Typami, które wybierają jeden z dwóch wariantów typu na podstawie relacji podtypu (T extends U ? X : Y) na wzór operatora trójargumentowego w JS","Instrukcją if w kodzie runtime","Testami jednostkowymi typów","Warunkami pętli for"]'::jsonb, 0, 'Conditional Types wprowadzają logikę warunkową do samego systemu typów TypeScript na etapie kompilacji.', 'medium', 15),
(382, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służy słowo kluczowe "infer" wewnątrz typu warunkowego?', 'type ElementTablicy<T> = T extends (infer U)[] ? U : never;', 'single-choice', '["Pozwala na zadeklarowanie zmiennej typu wewnątrz warunku, którą kompilator ma automatycznie wywnioskować (odgadnąć) z dopasowania","Zmusza kompilator do błędu","Oznacza dziedziczenie interfejsu","Usuwa typ z pamięci"]'::jsonb, 0, 'infer U działa jak wzorzec ekstrakcji: jeśli T jest tablicą elementów, kompilator wyciąga typ tych elementów do nowej zmiennej U.', 'hard', 20),
(383, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest dystrybucyjność typów warunkowych (Distributive Conditional Types)?', null, 'single-choice', '["Gdy sprawdzany parametr generyczny w T extends U jest nagą unią (naked type parameter), warunek jest automatycznie aplikowany do każdego elementu unii osobno, a wyniki są łączone w nową unię","Dystrybucją paczek npm","Zapisem do wielu plików","Działaniem asynchronicznym"]'::jsonb, 0, 'Dla unii A | B warunek CzyString<A | B> rozwija się do CzyString<A> | CzyString<B>.', 'hard', 20),
(384, 8, 'TypeScript i Statyczne Typowanie', 'Jak wydobyć typ wewnątrz obietnicy za pomocą wbudowanego typu Awaited<T> (ES2022)?', 'type Wynik = Awaited<Promise<Promise<number>>>;', 'output-predict', '["number (rekurencyjnie rozpakowuje wszystkie zagnieżdżone obietnice)","Promise<number>","unknown","never"]'::jsonb, 0, 'Wbudowany typ Awaited<T> modeluje zachowanie słowa kluczowego await, odwijając obietnice i Thenables aż do uzyskania właściwego typu bazowego.', 'medium', 15),
(385, 8, 'TypeScript i Statyczne Typowanie', 'Jak zapobiec dystrybucyjności w typie warunkowym?', null, 'single-choice', '["Opakowując oba typy w klamry tablicowe: [T] extends [U]","Dodając słowo static","Używając nawiasów okrągłych (T)","Wyłączając flagę strict"]'::jsonb, 0, 'Zapis [T] extends [U] wyłącza automatyczne rozbijanie unii na pojedyncze elementy i porównuje całą unię jako jeden typ.', 'hard', 20),
(386, 8, 'TypeScript i Statyczne Typowanie', 'Czym są typy literałów szablonowych (Template Literal Types)?', 'type Kolor = "red" | "blue";
type Rozmiar = "small" | "large";
type Wariant = `${Rozmiar}-${Kolor}`;', 'output-predict', '["\"small-red\" | \"small-blue\" | \"large-red\" | \"large-blue\" (tworzy iloczyn kartezjański wszystkich możliwych kombinacji ciągów znaków)","\"small-large-red-blue\"","string","TypeError"]'::jsonb, 0, 'Template Literal Types pozwalają łączyć typy unijne stringów w nowe szablony, generując wszystkie dopuszczalne kombinacje.', 'medium', 15),
(387, 8, 'TypeScript i Statyczne Typowanie', 'Jak w typie mapowanym usunąć modyfikator opcjonalności (-) ze wszystkich pól?', 'type WymaganeWszystko<T> = {
  [K in keyof T]???: T[K];
};', 'fill-gap', '["-?","!","required","+?"]'::jsonb, 0, 'Znak minusa przed pytajnikiem (-?) w typie mapowanym jawnie usuwa opcjonalność ze wszystkich właściwości (dokładnie tak działa Required<T>).', 'hard', 20),
(388, 8, 'TypeScript i Statyczne Typowanie', 'Jak w typie mapowanym zmienić nazwy kluczy (Key Remapping via as)?', 'type Gettery<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};', 'single-choice', '["Używając klauzuli \"as\" w nagłówku mapowania, łącząc ją z przekształceniami ciągu znaków","Zmieniając nazwy w obiekcie runtime","Poprzez dziedziczenie klas","Nie można zmieniać nazw kluczy w TS"]'::jsonb, 0, 'Klauzula as w typach mapowanych pozwala na dowolne przekształcanie, filtrowanie lub prefiksowanie nazw właściwości.', 'hard', 20),
(389, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służą wbudowane transformacje ciągów w TS: Uppercase, Lowercase, Capitalize, Uncapitalize?', null, 'single-choice', '["Do modyfikacji wielkości liter w typach literałowych ciągów znaków na poziomie kompilacji","Do formatowania tekstu w konsoli","Do zmiany wielkości liter w bazie danych","Do stylów CSS"]'::jsonb, 0, 'Są to wbudowane w kompilator typy narzędziowe manipulujące znakami w Template Literal Types.', 'easy', 10),
(390, 8, 'TypeScript i Statyczne Typowanie', 'Co robi typ NonNullable<T>?', 'type Wynik = NonNullable<string | number | null | undefined>;', 'output-predict', '["string | number (usuwa null oraz undefined ze zbioru typów)","string | number | null","never","undefined"]'::jsonb, 0, 'NonNullable<T> eliminuje ze wskazanego typu wartości null oraz undefined.', 'easy', 10),
(391, 8, 'TypeScript i Statyczne Typowanie', 'Co robi asercja "as const" (Const Assertion)?', 'const konfiguracja = {
  host: "localhost",
  port: 8080
} as const;', 'single-choice', '["Czyni wszystkie pola obiektu głęboko tylko do odczytu (readonly) i zawęża typy prymitywne do dokładnych wartości literałowych (np. \"localhost\" zamiast string)","Zamienia obiekt w stałą const języka JS w pliku wyjściowym","Blokuje pamięć RAM","Działa jak JSON.stringify"]'::jsonb, 0, '"as const" zapobiega rozszerzaniu typów (Type Widening), zamieniając pola na literały i uniemożliwiając ich modyfikację.', 'medium', 15),
(392, 8, 'TypeScript i Statyczne Typowanie', 'Do czego służy rewolucyjny operator "satisfies" wprowadzony w TypeScript 4.9?', 'const paleta = {
  primary: "#ff0000",
  secondary: [0, 255, 0]
} satisfies Record<string, string | number[]>;
// paleta.primary nadal ma precyzyjny typ string, a nie ogólny string | number[]!', 'single-choice', '["Waliduje, czy obiekt jest zgodny z danym typem, ale ZACHOWUJE najbardziej precyzyjny, wywnioskowany typ wartości bez niechcianego rozszerzania go","Rzutuje obiekt na typ any","Zastępuje słowo kluczowe class","Wymusza asynchroniczność"]'::jsonb, 0, 'Tradycyjne const x: Typ = ... gubi szczegółowe typy pól na rzecz ogólnego typu. Operator satisfies sprawdza poprawność kontraktu, nie niszcząc szczegółowego typu zmiennej.', 'hard', 20),
(393, 8, 'TypeScript i Statyczne Typowanie', 'Czym jest asercja niepustej wartości (Non-null Assertion Operator: !)?', 'const el = document.getElementById("btn")!;
el.focus();', 'single-choice', '["Mówi kompilatorowi TypeScript: \"gwarantuję, że ta wartość nie jest null ani undefined, wyłącz ostrzeżenie w tym miejscu\"","Wykonuje negację logiczną boolean","Oznacza pole prywatne","Rzuca wyjątek, jeśli wartość to null"]'::jsonb, 0, 'Wykrzyknik po wyrażeniu usuwa null i undefined z typu zmiennej w oczach kompilatora, ale NIE generuje żadnego kodu zabezpieczającego w runtime.', 'easy', 10),
(394, 8, 'TypeScript i Statyczne Typowanie', 'Dlaczego podwójne rzutowanie expr as unknown as InnyTyp jest uznawane za niebezpieczny anty-wzorzec (Code Smell)?', null, 'single-choice', '["Omija całkowicie zabezpieczenia kompilatora, pozwalając na wymuszenie konwersji pomiędzy całkowicie niekompatybilnymi typami, co może doprowadzić do awarii w runtime","Spowalnia kompilację o 500%","Wyłącza autouzupełnianie w edytorze","Jest zabronione w tsconfig"]'::jsonb, 0, 'TypeScript nie pozwala na bezpośrednie rzutowanie nielogicznych typów (np. string as number). Obejście tego przez "as unknown as T" niszczy bezpieczeństwo typów.', 'medium', 15),
(395, 8, 'TypeScript i Statyczne Typowanie', 'Czym różni się Enum w TypeScript od unii literałów (Union of String Literals)?', null, 'single-choice', '["Tradycyjny enum generuje prawdziwy obiekt w wyjściowym kodzie JavaScript (runtime code), podczas gdy unia literałów znika całkowicie po kompilacji (zero runtime cost)","Enum działa tylko w Node.js","Unia literałów nie może mieć więcej niż 3 elementy","Nie ma różnicy"]'::jsonb, 0, 'Enum to jeden z nielicznych elementów TS generujących faktyczny kod w JS (obiekt dwukierunkowy). Współczesne trendy faworyzują lżejsze unie stringów lub obiekty z "as const".', 'medium', 15),
(396, 8, 'TypeScript i Statyczne Typowanie', 'Czym są typy markowane (Branded Types / Nominal Typing)?', 'type UserId = string & { readonly __brand: unique symbol };
type OrderId = string & { readonly __brand: unique symbol };', 'single-choice', '["Techniką symulowania nominalnego systemu typów, która uniemożliwia przypadkowe pomylenie dwóch wartości o tym samym typie bazowym (np. UserId i OrderId)","Typami z logo firmy","Typami dla zmiennych środowiskowych","Specjalnymi interfejsami Reacta"]'::jsonb, 0, 'TypeScript stosuje typowanie strukturalne (duck typing). Branded Types dodają unikalny znacznik fantomowy, uniemożliwiając przekazanie OrderId w miejsce oczekiwanego UserId.', 'hard', 20),
(397, 8, 'TypeScript i Statyczne Typowanie', 'Czym różnią się nowe dekoratory Stage 3 (TypeScript 5.0+) od starszych eksperymentalnych dekoratorów (experimentalDecorators)?', null, 'single-choice', '["Nowe dekoratory są zgodne z oficjalnym standardem ECMAScript, nie wymagają włączania flagi eksperymentalnej i mają ściśle zdefiniowane konteksty typowania ClassMethodDecoratorContext","Starsze dekoratory działały tylko w przeglądarce","Nowe dekoratory działają synchronicznie","Nie ma różnic"]'::jsonb, 0, 'Od wersji TS 5.0 dekoratory zostały ustandaryzowane zgodnie ze specyfikacją TC39, wprowadzając obiekt kontekstu jako drugi argument funkcji dekoratora.', 'hard', 20),
(398, 8, 'TypeScript i Statyczne Typowanie', 'Jak zdefiniować funkcję z wieloma przeciążeniami (Function Overloads)?', 'function pobierz(id: number): User;
function pobierz(wszystkie: boolean): User[];
function pobierz(arg: number | boolean): User | User[] {
  // Właściwa implementacja
}', 'single-choice', '["Deklarując jedną lub więcej sygnatur przeciążeń bez ciała funkcji bezpośrednio przed sygnaturą implementacji","Tworząc kilka funkcji o tej samej nazwie z osobnymi ciałami","Używając operatora switch w nagłówku","Nie jest to możliwe w TS"]'::jsonb, 0, 'W TypeScript deklaruje się nagłówki sygnatur (overload signatures) przed funkcją implementującą, która musi obsłużyć wspólny przypadek wszystkich sygnatur.', 'medium', 15),
(399, 8, 'TypeScript i Statyczne Typowanie', 'Co robi flaga "isolatedModules": true w tsconfig.json?', null, 'single-choice', '["Ostrzega przed użyciem konstrukcji TypeScript (np. const enum, declare bez importu), których transpilatory pojedynczych plików (jak Babel, SWC czy esbuild) nie potrafią poprawnie przetworzyć","Izoluje pamięć modułów","Wyłącza komunikację sieciową","Zezwala tylko na jeden plik"]'::jsonb, 0, 'isolatedModules gwarantuje, że każdy plik źródłowy może zostać przetłumaczony na JS niezależnie od innych bez konieczności budowania pełnego grafu typów.', 'hard', 20),
(400, 8, 'TypeScript i Statyczne Typowanie', 'Jak bezpiecznie zawęzić typ błędu złapanego w bloku catch(err) w trybie "useUnknownInCatchVariables"?', 'try {
  wykonaj();
} catch (err: unknown) {
  if (err instanceof Error) {
    console.log(err.message);
  }
}', 'single-choice', '["Sprawdzając warunek if (err instanceof Error), ponieważ w JavaScript rzucić można dowolną wartość (nawet string czy liczbę)","Rzutując natychmiast na (err as any).message","Ignorując błąd","Wyłączając try...catch"]'::jsonb, 0, 'W JS throw może wyrzucić cokolwiek (np. throw 404). Zmienna err w nowoczesnym TS ma typ unknown, dlatego sprawdzenie instanceof Error jest jedyną bezpieczną praktyką.', 'medium', 15),
(401, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym charakteryzuje się wzorzec projektowy Singleton?', null, 'single-choice', '["Gwarantuje istnienie dokładnie jednej instancji danej klasy w całej aplikacji i zapewnia do niej globalny punkt dostępu","Tworzy nową instancję przy każdym wywołaniu funkcji","Służy wyłącznie do łączenia baz danych","Jest wzorcem asynchronicznym w Node.js"]'::jsonb, 0, 'Singleton ogranicza powoływanie instancji klasy do jednego obiektu. W nowoczesnym JS moduł ES eksportujący instancję obiektu (export const db = new DB()) jest naturalnym Singletonem.', 'easy', 10),
(402, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy wzorzec Fabryki (Factory Pattern)?', 'class FabrykaPowiadomien {
  stworz(typ) {
    if (typ === "email") return new PowiadomienieEmail();
    if (typ === "sms") return new PowiadomienieSMS();
  }
}', 'single-choice', '["Do hermetyzacji i centralizacji logiki tworzenia obiektów bez ujawniania klientowi szczegółów instancjonowania konkretnych klas","Do niszczenia nieużywanych obiektów w tle","Do kompilacji kodu JS","Do sprawdzania poprawności typów w TS"]'::jsonb, 0, 'Fabryka deleguje tworzenie konkretnych instancji do dedykowanej metody, ułatwiając rozbudowę systemu o nowe warianty obiektów.', 'easy', 10),
(403, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Budowniczy (Builder Pattern)?', 'const user = new UserBuilder()
  .setImie("Anna")
  .setWiek(28)
  .setAdmin(true)
  .build();', 'single-choice', '["Wzorcem ułatwiającym krokowe konstruowanie złożonych obiektów za pomocą łańcuchowania metod (fluent interface)","Narzędziem do budowania paczek (jak Webpack)","Klasą generującą pliki HTML","Wzorcem tylko dla aplikacji mobilnych"]'::jsonb, 0, 'Builder oddziela tworzenie skomplikowanego obiektu od jego ostatecznej reprezentacji, eliminując anty-wzorzec tzw. teleskopowego konstruktora z dziesiątkami argumentów.', 'medium', 15),
(404, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Prototyp (Prototype Pattern)?', null, 'single-choice', '["Tworzeniem nowych obiektów poprzez klonowanie istniejącego prototypowego obiektu wzorcowego zamiast tworzenia go od zera","Projektowaniem makiet w Figmie","Sprawdzaniem prototypów w konsoli","Używaniem wersji testowej beta oprogramowania"]'::jsonb, 0, 'Wzorzec Prototypu wykorzystuje klonowanie istniejącej instancji (np. metodą Object.create(wzorzec) lub structuredClone) dla optymalizacji kosztu inicjalizacji.', 'medium', 15),
(405, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Dlaczego tradycyjny Singleton bywa uważany za anty-wzorzec w nowoczesnym programowaniu?', null, 'single-choice', '["Wprowadza ukryty globalny stan aplikacji, silnie sprzęga moduły ze sobą i drastycznie utrudnia pisanie niezależnych testów jednostkowych (mockowanie)","Jest za wolny","Zajmuje za dużo miejsca w kodzie","Wymaga instalacji zewnętrznej biblioteki"]'::jsonb, 0, 'Globalny stan w Singletonie utrudnia izolację testów i współbieżność, dlatego współcześnie preferuje się wstrzykiwanie zależności (Dependency Injection).', 'medium', 15),
(406, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jaka jest kluczowa różnica między wzorcem Obserwator (Observer) a Wydawca-Subskrybent (Pub/Sub)?', null, 'single-choice', '["W Observerze obserwowany obiekt (Subject) bezpośrednio zna listę swoich obserwatorów i ich wywołuje, a w Pub/Sub istnieje pośredniczący kanał zdarzeń (Event Broker), dzięki czemu nadawcy i odbiorcy w ogóle o sobie nie wiedzą (pełne odsprzężenie)","To dwa różne określenia na dokładnie to samo","Pub/Sub działa tylko po protokole UDP","Observer jest synchroniczny, a Pub/Sub zawsze w C++"]'::jsonb, 0, 'W Pub/Sub nadawca publikuje zdarzenie do centralnej szyny zdarzeń (Event Bus), a subskrybenci rejestrują się w szynie, co całkowicie uniezależnia od siebie nadawców i odbiorców.', 'medium', 15),
(407, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy wzorzec Fasada (Facade Pattern)?', 'class ApiClient {
  // Skomplikowane nagłówki, tokeny, retry, parsowanie JSON ukryte w prostej metodzie:
  async pobierzUzytkownika(id) { ... }
}', 'single-choice', '["Udostępnia prosty, ujednolicony interfejs wysokiego poziomu ukrywający skomplikowany, złożony podsystem lub zestaw wielu powiązanych klas","Zmienia wygląd strony www","Służy do tworzenia trójwymiarowej grafiki","Działa jako zapora sieciowa firewall"]'::jsonb, 0, 'Fasada upraszcza pracę z rozbudowaną biblioteką lub podsystemem, oferując czyste i intuicyjne metody dla klienta.', 'easy', 10),
(408, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy wzorzec Adapter (Wrapper)?', null, 'single-choice', '["Przekształca interfejs jednej klasy na inny interfejs oczekiwany przez klienta, umożliwiając współpracę klasom o niekompatybilnych sygnaturach","Do ładowania baterii laptopa","Do łączenia z różnymi bazami SQL bez użycia kodu","Do kompresji plików"]'::jsonb, 0, 'Adapter działa jak przejściówka: opakowuje niekompatybilny obiekt i tłumaczy jego wywołania na format wymagany przez bieżący kod.', 'easy', 10),
(409, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Strategia (Strategy Pattern)?', 'class Koszyk {
  setMetodaPlatnosci(strategia) { this.platnosc = strategia; }
  oplac(kwota) { return this.platnosc.zaplac(kwota); }
}', 'single-choice', '["Definiuje rodzinę wymiennych algorytmów, hermetyzuje każdy z nich w osobnej klasie i pozwala na ich dynamiczną podmianę w czasie działania programu","Wzorcem wyznaczania celów kwartalnych w firmie","Pętlą decyzyjną AI","Algorytmem sortowania"]'::jsonb, 0, 'Wzorzec Strategii eliminuje wielkie instrukcje if/switch, pozwalając na łatwe wstrzykiwanie różnych wariantów logiki biznesowej (np. płatność BLIK, Karta, PayPal).', 'medium', 15),
(410, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy wzorzec Dekorator (Decorator Pattern)?', null, 'single-choice', '["Pozwala na dynamiczne dodawanie nowych zachowań i odpowiedzialności do istniejącego obiektu bez modyfikowania jego kodu źródłowego ani dziedziczenia","Do zmiany kolorów w CSS","Do dekorowania logów w terminalu","Do formatowania plików JSON"]'::jsonb, 0, 'Dekorator opakowuje oryginalny obiekt, rozszerzając jego funkcjonalność (np. logowanie wywołań, caching, sprawdzanie uprawnień) z zachowaniem tego samego interfejsu.', 'medium', 15),
(411, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co oznacza litera S w akronimie SOLID (Single Responsibility Principle)?', null, 'single-choice', '["Zasada Jednej Odpowiedzialności: klasa lub moduł powinna mieć tylko jeden powód do zmiany (realizować jedno konkretne zadanie)","Zasada Szybkiego Kodu (Speed)","Zasada Statycznego Typowania","Zasada Bezpieczeństwa (Security)"]'::jsonb, 0, 'Zasada SRP głosi, że każda klasa powinna odpowiadać za jedną ściśle określoną część funkcjonalności oprogramowania.', 'easy', 10),
(412, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co mówi zasada Open/Closed Principle (litera O w SOLID)?', null, 'single-choice', '["Elementy oprogramowania powinny być otwarte na rozbudowę (extension), ale zamknięte na modyfikację (modification)","Kod musi być otwartym oprogramowaniem Open Source","Wszystkie pliki muszą być zamykane po odczycie","Porty sieciowe muszą być otwarte"]'::jsonb, 0, 'Nowe funkcjonalności powinny być dodawane poprzez tworzenie nowych klas i interfejsów, a nie ciągłe edytowanie i ryzykowanie zepsucia istniejącego, działającego kodu.', 'medium', 15),
(413, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co postuluje zasada podstawienia Liskov (Liskov Substitution Principle - litera L w SOLID)?', null, 'single-choice', '["Obiekty klas potomnych muszą być w stanie zastąpić obiekty klas bazowych bez naruszania poprawności działania programu","Wszystkie funkcje muszą być czyste","Każda klasa musi mieć interfejs w TypeScript","Zmienne muszą być niemutowalne"]'::jsonb, 0, 'Klasa dziedzicząca nie może łamać kontraktu klasy nadrzędnej (np. zmieniać warunków początkowych lub rzucać nieoczekiwanych błędów dla metod bazowych).', 'hard', 20),
(414, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co oznacza zasada odwrócenia zależności (Dependency Inversion Principle - litera D w SOLID)?', null, 'single-choice', '["Moduły wysokiego poziomu nie powinny zależeć od modułów niskiego poziomu – oba powinny zależeć od abstrakcji (interfejsów)","Kod należy pisać od dołu pliku do góry","Baza danych steruje frontendem","Zmienne globalne sterują modułami"]'::jsonb, 0, 'Zamiast bezpośredniego powiązania z konkretną klasą bazy danych (np. new MySQLDatabase()), moduł biznesowy oczekuje interfejsu IDatabase wstrzykniętego z zewnątrz.', 'hard', 20),
(415, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co oznaczają reguły DRY, KISS i YAGNI w inżynierii oprogramowania?', null, 'single-choice', '["DRY: Don''t Repeat Yourself (unikaj duplikacji), KISS: Keep It Simple, Stupid (prostota ponad przekombinowanie), YAGNI: You Aren''t Gonna Need It (nie pisz kodu na zapas)","Nazwy protokołów sieciowych","Metodyki zwinne Scrum","Formaty kompresji danych"]'::jsonb, 0, 'To trzy fundamentalne zasady programistycznego pragmatyzmu, chroniące projekty przed nadmierną złożonością, powtórzeniami i overengineeringiem.', 'easy', 10),
(416, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jak wygląda klasyczna Piramida Testów (Testing Pyramid)?', null, 'single-choice', '["Szeroka podstawa: szybkie i tanie testy jednostkowe (Unit), środek: testy integracyjne (Integration), wąski szczyt: kosztowne testy end-to-end (E2E)","Wszystkie testy powinny być wyłącznie E2E","Odwrócona piramida z samymi testami manualnymi","Tylko testy wydajnościowe"]'::jsonb, 0, 'Piramida testów zaleca opieranie bazy jakości na setkach błyskawicznych testów jednostkowych, wspieranych przez testy integracyjne i selektywne testy E2E.', 'easy', 10),
(417, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jakie są trzy kolejne kroki w cyklu TDD (Test-Driven Development)?', null, 'single-choice', '["1. Red (napisz test, który nie przechodzi), 2. Green (napisz minimalny kod zaliczający test), 3. Refactor (popraw jakość i architekturę kodu bez psucia testu)","1. Planuj, 2. Pisz kod, 3. Testuj ręcznie","1. Deploy, 2. Debug, 3. Fix","1. Mock, 2. Spy, 3. Assert"]'::jsonb, 0, 'Cykl "Red - Green - Refactor" gwarantuje, że kod powstaje wyłącznie w odpowiedzi na zdefiniowane wymagania testowe i jest regularnie refaktoryzowany.', 'easy', 10),
(418, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co jest głównym celem testu jednostkowego (Unit Test)?', null, 'single-choice', '["Przetestowanie najmniejszej izolowanej jednostki kodu (np. pojedynczej funkcji lub metody) w całkowitym odcięciu od bazy danych, sieci i zewnętrznych zależności","Sprawdzenie wyglądu strony w Safari","Testowanie czasu odpowiedzi serwera w chmurze","Weryfikacja bazy danych produkcyjnej"]'::jsonb, 0, 'Test jednostkowy skupia się wyłącznie na logice pojedynczej funkcji, zastępując wszelkie zależności atrapiami (mockami).', 'easy', 10),
(419, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym charakteryzuje się test integracyjny (Integration Test)?', null, 'single-choice', '["Weryfikuje poprawność współpracy i komunikacji pomiędzy wieloma współpracującymi komponentami lub modułami (np. serwis łączący się z bazą SQLite)","Testuje tylko pojedynczą linijkę kodu","Sprawdza pisownię w komentarzach","Jest wykonywany przez użytkownika końcowego"]'::jsonb, 0, 'Test integracyjny sprawdza, czy połączone klocki systemu działają poprawnie jako zespół.', 'medium', 15),
(420, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co to jest pokrycie kodu testami (Code Coverage) i dlaczego 100% nie gwarantuje braku błędów?', null, 'single-choice', '["Wskaźnik określający odsetek linii/gałęzi kodu wykonanych podczas testów; 100% oznacza tylko dotknięcie kodu, ale nie sprawdza błędnych założeń biznesowych ani brakujących przypadków brzegowych","Maksymalna prędkość kompilatora","Liczba plików w repozytorium","Pojemność dysku serwera testowego"]'::jsonb, 0, 'Metryka Coverage mierzy ilość wykonanego kodu, a nie jakość asercji czy poprawność logiki biznesowej.', 'medium', 15),
(421, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jaka jest różnica między Mockiem a Szpiegiem (Spy) w frameworkach testowych (np. Vitest / Jest)?', null, 'single-choice', '["Szpieg (spyOn) owija prawdziwą, istniejącą metodę obiektu i monitoruje jej wywołania z zachowaniem oryginalnego działania (lub opcjonalnym nadpisaniem), a mock zazwyczaj tworzy całkowicie sztuczną implementację zastępczą","Mock działa tylko w chmurze","Spy nie ma dostępu do argumentów","To pojęcia tożsame"]'::jsonb, 0, 'vi.spyOn(obiekt, "metoda") pozwala sprawdzić, ile razy i z jakimi argumentami wywołano istniejącą metodę, zachowując lub modyfikując jej ciało.', 'medium', 15),
(422, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jak w Vitest / Jest sprawdzić, czy funkcja mock została wywołana dokładnie 2 razy z argumentem "id123"?', 'expect(mockFn).toHaveBeenCalledTimes(2);
expect(mockFn).???("id123");', 'fill-gap', '["toHaveBeenCalledWith","toBeCalledParams","toReceiveArg","toRunWith"]'::jsonb, 0, 'Asercja toHaveBeenCalledWith(arg) weryfikuje, czy funkcja została wywołana z podanymi parametrami.', 'easy', 10),
(423, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Dlaczego nowoczesny runner Vitest zyskał ogromną popularność w ekosystemie Vite?', null, 'single-choice', '["Współdzieli tę samą konfigurację i transformatory (esbuild/Rollup) z serwerem deweloperskim Vite, oferując błyskawiczny start i natywną obsługę TypeScript/ESM bez żmudnej konfiguracji","Zastępuje bazy danych SQL","Jest napisany w języku PHP","Działa wyłącznie w chmurze AWS"]'::jsonb, 0, 'Vitest eliminuje konieczność osobnej, bolesnej konfiguracji transpilacji TS/ESM w Jest, wykorzystując gotowy pipeline Vite.', 'medium', 15),
(424, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jak zamarkować moduł zewnętrzny (np. axios) w Vitest?', 'vi.mock("axios", () => ({
  default: { get: vi.fn().mockResolvedValue({ data: "sukces" }) }
}));', 'single-choice', '["Używając metody vi.mock(nazwaModulu, fabrykaMocka)","Usuwając paczkę z package.json","Używając window.fakeAxios","Przez plik .env"]'::jsonb, 0, 'vi.mock() przechwytuje instrukcję import "axios" w testowanym kodzie i podstawia zdefiniowany obiekt zastępczy.', 'medium', 15),
(425, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co robi metoda vi.useFakeTimers() podczas testowania kodu z timerami setTimeout/setInterval?', null, 'single-choice', '["Zastępuje zegar systemowy wirtualnym zegarem kontrolowanym programistycznie (np. vi.advanceTimersByTime(5000)), wykonując timery natychmiast bez realnego czekania 5 sekund","Spowalnia działanie testów","Sprawdza strefę czasową serwera","Wyłącza asynchroniczność w Node.js"]'::jsonb, 0, 'Fake Timers pozwalają błyskawicznie przetestować np. godzinny interwał w ułamku milisekundy.', 'medium', 15),
(426, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest atak XSS (Cross-Site Scripting)?', null, 'single-choice', '["Wstrzyknięciem złośliwego kodu JavaScript do zaufanej witryny internetowej, który wykonuje się w przeglądarce niczego nieświadomego użytkownika (np. kradnąc ciasteczka sesyjne)","Zablokowaniem serwera milionem zapytań (DDoS)","Przechwyceniem domeny internetowej","Złamaniem hasła metodą brute force"]'::jsonb, 0, 'Ataki XSS (Reflected, Stored, DOM-based) pozwalają hakerowi przejąć konto użytkownika poprzez wykonanie skryptu z poziomu jego własnej sesji.', 'easy', 10),
(427, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jak zapobiegać atakom XSS na poziomie kodu interfejsu?', null, 'single-choice', '["Sanityzując dane wejściowe przed wstawieniem do DOM (np. biblioteką DOMPurify) oraz stosując bezpieczne właściwości jak textContent zamiast innerHTML","Wyłączając protokół HTTPS","Dodając więcej pamięci RAM","Stosując silniejsze hasła bazy danych"]'::jsonb, 0, 'Uciekanie znaków (escaping), sanityzacja bibliotekami typu DOMPurify i unikanie niebezpiecznych API (innerHTML, eval) neutralizują próby wstrzyknięcia XSS.', 'medium', 15),
(428, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest polityka CORS (Cross-Origin Resource Sharing)?', null, 'single-choice', '["Mechanizmem bezpieczeństwa przeglądarki egzekwowanym przez nagłówki HTTP serwera, który kontroluje, czy skrypt ze źródła A może pobierać zasoby ze źródła B","Algorytmem szyfrowania bazy danych","Formatem wymiany plików graficznych","Systemem logowania Google"]'::jsonb, 0, 'CORS to mechanizm przeglądarki chroniący zasoby serwerowe przed nieuprawnionym odpytywaniem przez zewnętrzne skrypty w innych domenach.', 'medium', 15),
(429, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest atak CSRF (Cross-Site Request Forgery)?', null, 'single-choice', '["Zmuszeniem przeglądarki zalogowanego użytkownika do nieświadomego wysłania żądania HTTP (np. przelewu środków) do docelowego serwisu przy użyciu jego zapisanych ciasteczek sesyjnych","Wstrzyknięciem kodu w konsoli devtools","Kradzieżą certyfikatu SSL","Przejęciem kontrolera domeny"]'::jsonb, 0, 'CSRF wykorzystuje fakt, że przeglądarka automatycznie dołącza ciasteczka do żądań wysyłanych do danej domeny. Zabezpieczeniem są tokeny CSRF oraz atrybut SameSite na ciasteczkach.', 'medium', 15),
(430, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy nagłówek Content Security Policy (CSP)?', null, 'single-choice', '["Określa rygorystyczną białą listę zaufanych źródeł, z których przeglądarka ma prawo ładować i wykonywać skrypty, style, obrazy i połączenia sieciowe, skutecznie blokując XSS","Do kompresji plików gzip","Do przyspieszania DNS","Do konfiguracji plików cookie"]'::jsonb, 0, 'CSP to jedna z najpotężniejszych warstw obrony (Defense in Depth), uniemożliwiająca wykonanie wstrzykniętych skryptów inline lub pobranie złośliwych zasobów z obcych serwerów.', 'hard', 20),
(431, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym charakteryzuje się architektura Flux (będąca fundamentem Reduxa)?', null, 'single-choice', '["Jednokierunkowym przepływem danych (Unidirectional Data Flow): Action -> Dispatcher -> Store -> View, eliminując kaskadowe, nieprzewidywalne mutacje","Wielowątkowością w CSS","Generowaniem stron statycznych","Dwukierunkowym wiązaniem danych z widokiem"]'::jsonb, 0, 'Flux zastąpił problematyczne, splątane dwukierunkowe powiązania MVC deterministycznym, jednokierunkowym przepływem zdarzeń.', 'medium', 15),
(432, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest zasada Single Source of Truth w zarządzaniu stanem aplikacji?', null, 'single-choice', '["Cały globalny stan aplikacji przechowywany jest w jednym, centralnym drzewie obiektów (np. centralnym store), zapobiegając rozsynchronizowaniu danych","Baza danych znajduje się na jednym serwerze","Aplikacja ma tylko jednego programistę","Kod ma jedno repozytorium git"]'::jsonb, 0, 'Jedno źródło prawdy eliminuje sytuacje, w których różne komponenty interfejsu wyświetlają sprzeczne lub przestarzałe wersje tych samych danych.', 'easy', 10),
(433, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym charakteryzuje się Czysta Architektura (Clean Architecture / Onion Architecture)?', null, 'single-choice', '["Regułą zależności: wewnętrzne warstwy logiki biznesowej (Encje i Use Cases) są całkowicie niezależne od zewnętrznych bibliotek, frameworków, UI czy bazy danych","Usunięciem wszystkich komentarzy z kodu","Używaniem wyłącznie czystych funkcji","Architekturą bez baz danych"]'::jsonb, 0, 'W Clean Architecture logika domenowa jest odizolowana w centrum. Zmiana bazy danych czy frameworka UI nie wpływa na czyste reguły biznesowe.', 'hard', 20),
(434, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Repository (Repozytorium) w warstwie dostępu do danych?', null, 'single-choice', '["Warstwą abstrakcji udostępniającą logice biznesowej interfejs operacji na kolekcjach obiektów domenowych (np. findById, save), izolując szczegóły zapytań HTTP czy bazy danych","Repozytorium kodu na platformie GitHub","Folderem z plikami ZIP","Plikiem package.json"]'::jsonb, 0, 'Wzorzec Repozytorium sprawia, że kod biznesowy traktuje magazyn danych jak zwykłą kolekcję w pamięci, nie wiedząc czy pod spodem jest IndexedDB, REST API czy GraphQL.', 'medium', 15),
(435, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co oznacza pojęcie DTO (Data Transfer Object)?', null, 'single-choice', '["Prostym obiektem bez metod ani logiki biznesowej, służącym wyłącznie do bezpiecznego przesyłania danych pomiędzy procesami lub przez sieć (np. z API do aplikacji)","Typem danych w TypeScript dla bazy SQL","Dokumentem technicznym projektu","Narzędziem do testowania"]'::jsonb, 0, 'DTO modeluje surowe dane przychodzące z sieci, które następnie są mapowane na pełnoprawne modele domenowe w aplikacji.', 'medium', 15),
(436, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest dług techniczny (Technical Debt)?', null, 'single-choice', '["Kosztownymi konsekwencjami wyboru szybkich, prowizorycznych rozwiązań kosztem jakości kodu, które spowalniają przyszły rozwój projektu i zwiększają ryzyko błędów","Kosztami abonamentu za serwery AWS","Kredytem wziętym na sprzęt komputerowy","Brakiem licencji komercyjnej"]'::jsonb, 0, 'Dług techniczny zaciąga się, idąc na skróty. Jeśli nie jest regularnie spłacany poprzez refaktoryzację, "odsetki" paraliżują zespół przy dodawaniu nowych funkcji.', 'easy', 10),
(437, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest Code Smell (zapach kodu)?', null, 'single-choice', '["Symptomem w kodzie źródłowym, który nie jest bezpośrednim błędem kompilacji czy składni, ale wskazuje na głębsze problemy architektoniczne lub naruszenie dobrych praktyk","Błędem krytycznym 500","Wirusowym oprogramowaniem","Formatowaniem kodu przez Prettier"]'::jsonb, 0, 'Przykłady zapachów kodu: Long Method (metoda na 500 linii), God Object (klasa robiąca wszystko), Duplicated Code czy Magic Numbers.', 'easy', 10),
(438, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym są Magiczne Liczby (Magic Numbers) i jak je zlikwidować?', 'if (status === 3) { ... }
// Jak to poprawić?', 'single-choice', '["Liczbami wpisanymi bezpośrednio w kod bez wyjaśnienia znaczenia; należy je zastąpić nazwanymi stałymi (np. const STATUS_ZREALIZOWANO = 3)","Liczbami pierwszymi","Losowymi identyfikatorami sesji","Liczbami w typie BigInt"]'::jsonb, 0, 'Zastąpienie liczb lub surowych stringów opisowymi stałymi natychmiast poprawia czytelność kodu i ułatwia późniejsze modyfikacje.', 'easy', 10),
(439, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Co zakłada technika refaktoryzacji "Extract Function" (Wyodrębnienie funkcji)?', null, 'single-choice', '["Wydzielenie spójnego fragmentu kodu z długiej metody do osobnej, mniejszej funkcji o czytelnej i precyzyjnej nazwie wyjaśniającej jej intencję","Usunięcie funkcji z kodu","Skopiowanie funkcji do innego pliku","Zastąpienie funkcji wyrażeniem eval"]'::jsonb, 0, 'Extract Function to fundamentalna technika refaktoryzacji poprawiająca czytelność, modularność i możliwość testowania jednostkowego.', 'easy', 10),
(440, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest zasada Boy Scout Rule (Zasada Skauta) w inżynierii oprogramowania?', null, 'single-choice', '["Zawsze pozostawiaj kod w nieco lepszym stanie, niż go zastałeś (nawet drobna poprawka nazwy zmiennej czy usunięcie martwego kodu przy okazji pracy nad zadaniem)","Nie dotykaj kodu, który działa","Pisz testy tylko na koniec projektu","Wszyscy programiści muszą nosić mundury"]'::jsonb, 0, 'Systematyczne, drobne sprzątanie bazy kodu przy każdej wizycie w pliku zapobiega erozji architektury i kumulowaniu długu technicznego.', 'easy', 10),
(441, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest test End-to-End (E2E)?', null, 'single-choice', '["Testem uruchamiającym całą aplikację w prawdziwej przeglądarce i symulującym rzeczywiste działania użytkownika (kliknięcia, logowanie, zakupy) od początku do końca","Sprawdzaniem typów w TypeScript","Testem pojedynczej funkcji matematycznej","Przeglądem kodu przez lidera zespołu"]'::jsonb, 0, 'Testy E2E (np. w Playwright czy Cypress) testują zintegrowany system wraz z interfejsem, siecią i bazą danych, weryfikując tzw. Critical User Journeys.', 'easy', 10),
(442, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Dlaczego w testach UI zaleca się wyszukiwanie elementów po rolach ARIA (np. getByRole("button", { name: "Zapisz" })) zamiast selektorów CSS (.btn-primary)?', null, 'single-choice', '["Wymusza dostępność (a11y) dla czytników ekranu i jest całkowicie odporne na zmiany klas stylistycznych lub struktury HTML podczas refaktoryzacji wizualnej","Bo selektory CSS nie działają w Playwright","Bo role ARIA działają szybciej o 500%","Jest to wymagane przez specyfikację ECMA"]'::jsonb, 0, 'Testowanie z perspektywy ról semantycznych sprawia, że testy testują zachowanie widziane przez użytkownika (i czytniki ekranu), a nie kruche szczegóły implementacyjne CSS.', 'medium', 15),
(443, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Page Object Model (POM) w testach E2E?', null, 'single-choice', '["Wzorcem projektowym, który hermetyzuje elementy i interakcje danej strony lub widoku w dedykowanej klasie, zapobiegając duplikacji selektorów w wielu plikach testowych","Modelem bazy danych dla strony www","Wzorcem generowania stron statycznych","Plikiem HTML w testach"]'::jsonb, 0, 'Page Object Model ułatwia utrzymanie testów E2E: zmiana selektora na stronie wymaga poprawki w tylko jednym miejscu (w klasie strony).', 'medium', 15),
(444, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jaka jest rola atrybutu aria-live="polite" w aplikacjach dostępnych (a11y)?', null, 'single-choice', '["Informuje czytniki ekranu, że treść tego elementu aktualizuje się dynamicznie i należy odczytać nowe informacje, gdy użytkownik skończy bieżącą akcję (nie przerywając natychmiast)","Tworzy animację na żywo","Oznacza kamerę internetową","Wyłącza powiadomienia w przeglądarce"]'::jsonb, 0, 'Regiony aria-live komunikują użytkownikom asystującym dynamiczne zmiany na stronie (np. powiadomienia toast lub błędy formularza).', 'medium', 15),
(445, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym są testy regresji wizualnej (Visual Snapshot Testing)?', null, 'single-choice', '["Automatycznym porównywaniem zrzutów ekranu (pixel-by-pixel lub perceptual hash) wygenerowanych komponentów z wzorcami bazowymi w celu wykrycia niezamierzonych zmian wyglądu","Testami wzroku użytkowników","Sprawdzaniem palety kolorów","Testowaniem prędkości animacji"]'::jsonb, 0, 'Testy wizualne automatycznie wyłapują przesunięcia pikseli, błędy marginesów lub rozbite layouty wywołane zmianami w stylach CSS.', 'medium', 15),
(446, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest CI/CD (Continuous Integration / Continuous Delivery)?', null, 'single-choice', '["Praktyką automatycznego budowania, testowania i wdrażania zmian w kodzie przy każdym commicie lub pull requeście, gwarantując stałą gotowość aplikacji do wydania","Systemem operacyjnym dla programistów","Certyfikatem bezpieczeństwa SSL","Nazwą frameworka JavaScript"]'::jsonb, 0, 'Potok CI/CD automatycznie uruchamia lintery, testy i procesy budowania w chmurze (np. GitHub Actions), zabezpieczając główną gałąź przed błędami.', 'easy', 10),
(447, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Jaka jest rola narzędzi ESLint i Prettier w projekcie?', null, 'single-choice', '["ESLint analizuje kod pod kątem potencjalnych błędów logicznych i naruszeń reguł jakości, a Prettier odpowiada za bezdyskusyjne, jednolite formatowanie kodu (spacje, wcięcia)","Oba służą do testowania bazy danych","Prettier kompiluje TypeScript do JavaScript","ESLint tworzy kopię zapasową projektu"]'::jsonb, 0, 'ESLint dba o jakość i poprawność logiki, a Prettier o estetykę i spójność wizualną formatowania plików w zespole.', 'easy', 10),
(448, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Do czego służy biblioteka husky i lint-staged?', null, 'single-choice', '["Do automatycznego uruchamiania lintera i formatowania w hookach Gita (pre-commit) wyłącznie na plikach przygotowanych do zatwierdzenia (staged), zapobiegając commitowaniu błędów","Do monitorowania temperatury procesora","Do kompresji repozytorium gita","Do automatycznego generowania changeloga"]'::jsonb, 0, 'Husky z lint-staged blokuje wykonanie git commit, jeśli w przygotowanych plikach wykryto błędy lintera lub niesformatowany kod.', 'medium', 15),
(449, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest wzorzec Circuit Breaker (Bezpiecznik) w komunikacji z zewnętrznymi mikrousługami?', null, 'single-choice', '["Mechanizmem wykrywającym powtarzające się awarie zewnętrznej usługi i natychmiast przerywającym wysyłanie kolejnych żądań (stan Open), aby nie przeciążać systemu i szybko zwracać fallback","Fizycznym korkiem elektrycznym w serwerowni","Zabezpieczeniem przed kradzieżą laptopa","Procesem szyfrowania HTTPS"]'::jsonb, 0, 'Circuit Breaker chroni system przed lawinowym narastaniem opóźnień, gdy zewnętrzny serwis przestaje odpowiadać.', 'hard', 20),
(450, 9, 'Architektura, Wzorce Projektowe i Testowanie', 'Czym jest Feature Toggling (Feature Flags)?', null, 'single-choice', '["Techniką włączania lub wyłączania określonych funkcjonalności w aplikacji w czasie działania bez konieczności ponownego wdrażania kodu (przydatną np. przy testach A/B lub wdrożeniach canary)","Przełączaniem motywu dark mode","Włączaniem dźwięku w aplikacji","Narzędziem do debugowania pamięci"]'::jsonb, 0, 'Flagi funkcjonalności pozwalają oddzielić wdrożenie kodu na produkcję (deployment) od udostępnienia nowej funkcji użytkownikom (release).', 'medium', 15),
(451, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak silnik V8 (Chrome / Node.js) wykonuje kod JavaScript w nowoczesnej architekturze?', null, 'single-choice', '["Interpreter Ignition generuje kod bajtowy (bytecode), a kompilator optymalizujący JIT (TurboFan) kompiluje gorący kod (hot code) bezpośrednio do maszynowego kodu procesora w czasie działania","Jest czystym interpreterem linijka po linijce","Kompiluje cały program do pliku .exe przed startem","Przekazuje kod do interpretacji przez kartę graficzną"]'::jsonb, 0, 'V8 łączy szybki start interpretacji kodu bajtowego (Ignition) ze spekulatywną kompilacją JIT do zoptymalizowanego kodu maszynowego (TurboFan).', 'medium', 15),
(452, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym są Ukryte Klasy (Hidden Classes / Shapes) w silnikach takich jak V8?', null, 'single-choice', '["Wewnętrznymi strukturami silnika mapującymi układ właściwości i ich przesunięcia w pamięci (offsets) dla obiektów o identycznym kształcie, co drastycznie przyspiesza dostęp do pól","Klasami zadeklarowanymi z prefiksem #","Prywatnymi polami w module","Klasami CSS ukrytymi przez display: none"]'::jsonb, 0, 'JavaScript nie ma statycznych klas w pamięci, więc V8 w locie tworzy tzw. Hidden Classes. Obiekty o tych samych kluczach dodanych w tej samej kolejności współdzielą tę samą strukturę.', 'hard', 20),
(453, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Dlaczego inicjalizowanie obiektów z polami dodawanymi w różnej kolejności psuje optymalizację V8?', 'const o1 = {}; o1.a = 1; o1.b = 2;
const o2 = {}; o2.b = 2; o2.a = 1; // Inna kolejność!', 'single-choice', '["Prowadzi do powstania dwóch odrębnych drzew ukrytych klas (Hidden Classes), uniemożliwiając monomorficzne buforowanie dostępu do pól (Inline Caching)","Rzuca błąd TypeError w V8","Podwaja zużycie dysku","Powoduje wyciek pamięci"]'::jsonb, 0, 'Różna kolejność definiowania właściwości tworzy różne przejścia (transitions) w ukrytych klasach, obniżając wydajność Inline Caching.', 'hard', 20),
(454, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest Inline Caching (IC) i jego stan megamorficzny (Megamorphic)?', null, 'single-choice', '["IC zapamiętuje lokalizację właściwości dla obserwowanych kształtów obiektów. Jeśli funkcja otrzymuje obiekty o zbyt wielu różnych kształtach (>4), staje się megamorficzna i spada do wolnego przeszukiwania słownikowego","Zapisywaniem stron www w pamięci podręcznej","Kompilacją stylów CSS w locie","Pamięcią cache procesora L1"]'::jsonb, 0, 'Monomorficzny kod (obiekty o jednym kształcie) działa z maksymalną prędkością kodu maszynowego. Kod megamorficzny jest deoptymalizowany przez V8.', 'hard', 20),
(455, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest Deoptymalizacja (Deopt / Bailout) w kompilatorze JIT?', null, 'single-choice', '["Wycofaniem wygenerowanego zoptymalizowanego kodu maszynowego z powrotem do wolniejszego kodu bajtowego, gdy optymistyczne założenia dotyczące typów zostaną złamane (np. funkcja nagle otrzyma string zamiast liczby)","Awaryjnym wyłączeniem komputera","Błędem składniowym","Usunięciem zmiennych z pamięci"]'::jsonb, 0, 'TurboFan kompiluje kod przy założeniu, że argumenty będą zawsze tego samego typu. Przekazanie innego typu zmusza silnik do kosztownego deopt.', 'hard', 20),
(456, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest wyciek pamięci spowodowany przez odłączone węzły DOM (Detached DOM Nodes)?', null, 'single-choice', '["Sytuacją, w której element został usunięty z drzewa dokumentu HTML, ale w zmiennej JavaScript lub tablicy wciąż istnieje do niego aktywna referencja, uniemożliwiając odśmiecaczowi pamięci zwolnienie całego poddrzewa DOM","Błędem w zasilaniu płyty głównej","Błędem w parserze CSS","Zaburzeniem kolorów na monitorze"]'::jsonb, 0, 'Nawet jedna referencja do pojedynczego usuniętego <div> w tablicy powstrzymuje Garbage Collector przed zwolnieniem wszystkich jego elementów potomnych i powiązanych zasobów.', 'medium', 15),
(457, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak zapobiegać wyciekom pamięci związanym z setInterval() i addEventListener() w aplikacjach typu SPA?', null, 'single-choice', '["Zawsze czyścić timery metodą clearInterval(id) oraz usuwać nasłuchiwacze removeEventListener() (lub korzystać z AbortSignal) w momencie odmontowywania widoku/komponentu","Przeładowywać stronę co 10 minut","Używać wyłącznie pętli while","Wyłączać Garbage Collector w ustawieniach"]'::jsonb, 0, 'Zostawienie aktywnego interwału lub listenera na window trzyma w domknięciu referencje do całych komponentów, powodując stały wzrost zużycia RAM.', 'easy', 10),
(458, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jaka jest różnica między rozmiarem Shallow Size a Retained Size w zrzucie sterty (Heap Snapshot) w Chrome DevTools?', null, 'single-choice', '["Shallow Size to pamięć zajmowana przez sam ten obiekt, a Retained Size to łączna ilość pamięci, która zostanie natychmiast zwolniona, gdy ten obiekt zostanie zniszczony i odśmiecony wraz ze wszystkimi zależnymi strukturami","Shallow to pamięć dyskowa, a Retained to RAM","Shallow to wielkość pliku .js","To pojęcia tożsame"]'::jsonb, 0, 'Retained Size identyfikuje prawdziwych winowajców wycieków: obiekty trzymające duże grafy innych obiektów w pamięci.', 'hard', 20),
(459, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak odpiąć wiele nasłuchiwaczy addEventListener za pomocą jednego sygnału AbortController (nowoczesny standard)?', 'const controller = new AbortController();
window.addEventListener("resize", f1, { signal: controller.signal });
window.addEventListener("scroll", f2, { signal: controller.signal });
// Aby odpiąć oba naraz:', 'single-choice', '["controller.abort()","controller.remove()","controller.disconnect()","controller.close()"]'::jsonb, 0, 'Przekazanie { signal } do addEventListener pozwala na jednoczesne usunięcie setek nasłuchiwaczy jednym wywołaniem controller.abort().', 'medium', 15),
(460, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Dlaczego nieumyślne tworzenie zmiennych w zasięgu globalnym (np. brak const/let) jest jedną z najczęstszych przyczyn wycieków pamięci?', 'function oblicz() {
  wynik = new Array(1000000); // Zapomniano const/let!
}', 'single-choice', '["Zmienna staje się właściwością obiektu window (lub global), przez co jej cykl życia trwa tak długo, jak otwarta jest karta przeglądarki, i nigdy nie zostanie usunięta przez GC","Powoduje zawieszenie karty graficznej","Jest to błąd składniowy odpalany w trybie czuwania","Niszczy bazę danych"]'::jsonb, 0, 'Zmienne globalne są korzeniami odśmiecacza (GC Roots) i nigdy nie zostają zebrane, dopóki strona nie zostanie przeładowana.', 'easy', 10),
(461, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest Web Worker w przeglądarce internetowej?', null, 'single-choice', '["Osobnym wątkiem w tle w systemie operacyjnym, który wykonuje kod JavaScript równolegle bez blokowania głównego wątku interfejsu użytkownika (UI Thread)","Wtyczką do przeglądarki","Procesem na serwerze zdalnym","Wirtualną maszyną Pythona"]'::jsonb, 0, 'Web Worker pozwala na oddelegowanie ciężkich obliczeń matematycznych, przetwarzania obrazów czy szyfrowania do osobnego wątku, zapobiegając zacinaniu UI.', 'easy', 10),
(462, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jakie kluczowe ograniczenie architektoniczne posiada dedykowany Web Worker?', null, 'single-choice', '["Nie ma bezpośredniego dostępu do drzewa DOM (document, window), manipulacji stylami ani selektorów interfejsu","Nie może wykonywać pętli for","Nie może korzystać z typu String","Nie ma dostępu do sieci fetch()"]'::jsonb, 0, 'Ze względu na bezpieczeństwo współbieżności Web Worker nie może bezpośrednio dotykać DOM. Komunikacja z wątkiem głównym odbywa się wyłącznie przez wiadomości postMessage.', 'easy', 10),
(463, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym są obiekty przenoszalne (Transferable Objects, np. ArrayBuffer) podczas wysyłania przez postMessage?', null, 'single-choice', '["Pamięć bufora jest błyskawicznie przekazywana do drugiego wątku w czasie O(1) przez przeniesienie własności wskaźnika (zero-copy), a w wątku źródłowym bufor staje się natychmiast pusty i niedostępny (detached)","Dane są pakowane do formatu ZIP","Są szyfrowane kluczem symetrycznym","Są kopiowane bajt po bajcie"]'::jsonb, 0, 'Transferable Objects eliminują kosztowne klonowanie strukturalne gigabajtów danych, przekazując bezpośredni wskaźnik do pamięci.', 'hard', 20),
(464, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest SharedArrayBuffer i obiekt Atomics w JavaScript?', null, 'single-choice', '["Pozwalają na prawdziwe współdzielenie tego samego obszaru pamięci RAM pomiędzy wieloma wątkami Workerów z operacjami atomowymi (Atomics) zabezpieczającymi przed wyścigami (Race Conditions)","Służą do komunikacji przez Bluetooth","Tworzą kopię zapasową w chmurze","Są tablicami przechowującymi dane w localStorage"]'::jsonb, 0, 'SharedArrayBuffer i Atomics to niskopoziomowe API wielowątkowości w JS, wymagające nagłówków izolacji Cross-Origin (COOP/COEP).', 'hard', 20),
(465, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym różni się SharedWorker od zwykłego Dedicated Workera?', null, 'single-choice', '["SharedWorker może być współdzielony i komunikować się jednocześnie z wieloma różnymi kartami, oknami lub ramkami iframe otwartymi w ramach tej samej domeny","SharedWorker nie zużywa baterii","Dedykowany worker działa po stronie serwera","Nie ma żadnej różnicy"]'::jsonb, 0, 'SharedWorker działa jako pojedyncza instancja obsługująca wiele połączeń przez porty (MessagePort) z różnych kart tej samej witryny.', 'medium', 15),
(466, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest Service Worker w nowoczesnych aplikacjach PWA (Progressive Web Apps)?', null, 'single-choice', '["Programowalnym sieciowym serwerem proxy działającym w tle w przeglądarce, zdolnym do przechwytywania wszystkich żądań HTTP, zarządzania pamięcią Cache API i obsługi pracy w trybie offline","Plikiem konfiguracyjnym serwera Nginx","Wtyczką do generowania ikon aplikacji","Agentem wysyłającym spam"]'::jsonb, 0, 'Service Worker pośredniczy między aplikacją a siecią, decydując czy odpowiedź pobrać z sieci, czy z lokalnego Cache Storage w trybie offline.', 'easy', 10),
(467, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Na czym polega strategia buforowania "Stale While Revalidate"?', null, 'single-choice', '["Natychmiast zwraca użytkownikowi wersję zapisaną w pamięci cache (błyskawiczny czas ładowania), a w tle asynchronicznie odpytuje sieć i aktualizuje pamięć podręczną na przyszłość","Zawsze pobiera z sieci i nigdy nie zapisuje","Czeka 10 sekund przed wysłaniem żądania","Czyści pamięć podręczną po każdym odświeżeniu"]'::jsonb, 0, 'Stale-While-Revalidate oferuje optymalny kompromis między natychmiastowym renderowaniem a świeżością danych.', 'medium', 15),
(468, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jakie są trzy główne fazy cyklu życia Service Workera?', null, 'single-choice', '["1. Rejestracja (Registration), 2. Instalacja (Installation - zdarzenie install), 3. Aktywacja (Activation - zdarzenie activate)","1. Pobieranie, 2. Parsowanie, 3. Wykonanie","1. Start, 2. Pętla, 3. Stop","1. Init, 2. Mount, 3. Unmount"]'::jsonb, 0, 'W fazie install przygotowuje się cache z kluczowymi zasobami (tzw. precaching app shell), a w activate czyści stare, przestarzałe wersje cache.', 'medium', 15),
(469, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jakie wymaganie bezpieczeństwa musi bezwzględnie spełniać witryna, aby móc zarejestrować Service Workera?', null, 'single-choice', '["Musi być serwowana przez bezpieczne połączenie HTTPS (wyjątkiem jest wyłącznie localhost podczas developmentu)","Musi mieć co najmniej 10 podstron","Musi posiadać certyfikat firmy Microsoft","Musi być zarejestrowana w Google Play"]'::jsonb, 0, 'Ze względu na potężne uprawnienia (przechwytywanie całego ruchu sieciowego) Service Worker wymaga szyfrowanego połączenia HTTPS, chroniąc przed atakami Man-in-the-Middle.', 'easy', 10),
(470, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy API powiadomień Push (Push API i Notification API) w połączeniu z Service Workerem?', null, 'single-choice', '["Pozwala serwerowi na wysyłanie powiadomień do urządzenia użytkownika i ich wyświetlenie na ekranie, nawet gdy przeglądarka i strona www są całkowicie zamknięte","Do wysyłania wiadomości SMS z telefonu","Do aktualizacji bazy danych w nocy","Do automatycznego odtwarzania filmów"]'::jsonb, 0, 'Service Worker może zostać wybudzony przez system operacyjny po nadejściu wiadomości Push z serwera, aby zaprezentować notyfikację systemową.', 'medium', 15),
(471, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest WebAssembly (WASM)?', null, 'single-choice', '["Niskopoziomowym, binarnym formatem instrukcji o niemal natywnej wydajności kodu maszynowego, zaprojektowanym jako przenośny cel kompilacji dla języków takich jak C++, Rust czy Go w przeglądarce i poza nią","Nową biblioteką jQuery","Zastępcą dla kodu HTML i CSS","Protokółem sieciowym szybszym od HTTP/3"]'::jsonb, 0, 'WASM nie zastępuje JavaScriptu, lecz współpracuje z nim, dostarczając ekstremalnej wydajności dla silników gier 3D, obróbki wideo, CAD czy zaawansowanej kryptografii.', 'easy', 10),
(472, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak najwydajniej wczytać i skompilować moduł WebAssembly prosto ze strumienia sieciowego?', 'const { instance } = await WebAssembly.???(fetch("modul.wasm"));', 'fill-gap', '["instantiateStreaming","compileAsync","loadModule","fromFetch"]'::jsonb, 0, 'WebAssembly.instantiateStreaming kompiluje kod binarny równolegle w trakcie jego pobierania przez sieć, zanim cały plik dotrze na dysk.', 'medium', 15),
(473, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'W jaki sposób kod JavaScript i moduł WebAssembly wymieniają złożone struktury danych (np. obrazy, ciągi znaków)?', null, 'single-choice', '["Poprzez współdzieloną pamięć liniową WebAssembly.Memory (jako bufor bajtów ArrayBuffer), odczytywany przez widoki TypedArray","Przez pliki JSON na dysku twardym","Za pomocą ciasteczek przeglądarki","Przez zmienne w localStorage"]'::jsonb, 0, 'Pamięć WASM jest płaskim buforem bajtów. JS zapisuje dane do tego bufora, a funkcja WASM przetwarza je wskaźnikami z prędkością kodu natywnego.', 'hard', 20),
(474, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jakie 4 typy wartości liczbowych natywnie obsługuje rdzeń WebAssembly (MVP)?', null, 'single-choice', '["i32, i64 (liczby całkowite 32 i 64-bitowe) oraz f32, f64 (liczby zmiennoprzecinkowe)","string, number, boolean, object","int, float, double, char","same liczby 128-bitowe"]'::jsonb, 0, 'Niski poziom WASM operuje na czystych rejestrach procesora: 32 i 64-bitowych liczbach całkowitych oraz zmiennoprzecinkowych.', 'hard', 20),
(475, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest WASI (WebAssembly System Interface)?', null, 'single-choice', '["Modułowym, bezpiecznym standardem interfejsu systemowego (dostęp do plików, zegara, sieci) dla aplikacji WebAssembly działających poza przeglądarką (np. w Node.js, Wasmtime)","Klawiaturą dla programistów WASM","Formatem graficznym","Silnikiem renderowania czcionek"]'::jsonb, 0, 'WASI umożliwia uruchamianie bezpiecznych, piaskownicowych (sandboxed) binarek WASM bezpośrednio w systemach operacyjnych i chmurze.', 'hard', 20),
(476, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Na czym polega proces eliminacji martwego kodu o nazwie Tree Shaking?', null, 'single-choice', '["Na statycznej analizie importów i eksportów w modułach ES w celu usunięcia z końcowego bundle''a produkcyjnego wszystkich funkcji i zmiennych, które nigdy nie są wywoływane w projekcie","Na formatowaniu wcięć w plikach JS","Na kompresji obrazów PNG","Na usuwaniu starych wersji gita"]'::jsonb, 0, 'Dzięki statycznej strukturze ESM (import/export na najwyższym poziomie) bundler precyzyjnie wie, jakie fragmenty kodu biblioteki są używane, odrzucając całą nieużywaną resztę.', 'easy', 10),
(477, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy pole "sideEffects": false w pliku package.json biblioteki npm?', null, 'single-choice', '["Informuje bundlery (Webpack, Rollup, Vite), że pliki pakietu nie wywołują efektów ubocznych przy samym imporcie, pozwalając na agresywne usunięcie nieużywanych modułów w procesie Tree Shaking","Wyłącza komunikację sieciową w bibliotece","Zapobiega błędom w konsoli","Wyłącza animacje CSS"]'::jsonb, 0, 'Bez flagi sideEffects: false bundler musi asekuracyjnie założyć, że zaimportowanie pliku modyfikuje np. globalny prototyp, i nie może bezpiecznie wyciąć tego pliku.', 'hard', 20),
(478, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Dlaczego serwer deweloperski Vite uruchamia się niemal natychmiastowo nawet w gigantycznych projektach?', null, 'single-choice', '["Serwuje kod źródłowy za pomocą natywnych modułów ES (NPM) bezpośrednio do przeglądarki na żądanie, a zależności pre-bundluje błyskawicznym kompilatorem esbuild napisanym w Go","Nie sprawdza błędów w kodzie","Działa wyłącznie w pamięci podręcznej przeglądarki","Kompiluje kod do plików PHP"]'::jsonb, 0, 'W przeciwieństwie do starych bundlerów, które budowały całą aplikację przed startem, Vite parsuje zależności w esbuild (Go) i ładuje pojedyncze pliki na żądanie przeglądarki.', 'medium', 15),
(479, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym są Source Maps (mapy źródłowe, pliki *.map)?', null, 'single-choice', '["Plikami mapującymi skompresowany, zminifikowany kod produkcyjny z powrotem do oryginalnego, czytelnego kodu źródłowego (np. TypeScript / JSX) podczas debugowania w DevTools","Mapami geograficznymi serwerów w chmurze","Schematami bazy danych","Listą zależności w npm"]'::jsonb, 0, 'Dzięki Source Maps możemy stawiać breakpointy i widzieć błędy z dokładnym wskazaniem linii i nazwy pliku w oryginalnym kodzie TypeScript.', 'easy', 10),
(480, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Na czym polega podział kodu (Code Splitting)?', null, 'single-choice', '["Rozbiciu pojedynczego gigantycznego pliku aplikacji na mniejsze paczki (chunki) ładowane leniwie przez przeglądarkę tylko wtedy, gdy użytkownik faktycznie wchodzi na dany widok","Podziale pliku na 2 równe połówki","Kopiowaniu kodu na dwa serwery","Podziale stylów na kolory"]'::jsonb, 0, 'Code Splitting drastycznie zmniejsza początkowy czas ładowania strony (First Contentful Paint), opierając się na dynamicznym imporcie import().', 'medium', 15),
(481, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Co mierzy kluczowa metryka LCP (Largest Contentful Paint)?', null, 'single-choice', '["Czas renderowania największego widocznego elementu treści (np. dużego obrazu głównego lub bloku tekstu) w widocznym oknie podglądu użytkownika","Łączną wagę wszystkich plików na serwerze","Czas odpowiedzi serwera na ping","Liczbę wyświetleń strony"]'::jsonb, 0, 'LCP mierzy postrzegany czas załadowania głównej zawartości strony. Dobry wynik LCP to poniżej 2.5 sekundy.', 'medium', 15),
(482, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest metryka INP (Interaction to Next Paint), która oficjalnie zastąpiła wskaźnik FID w Core Web Vitals?', null, 'single-choice', '["Mierzy ogólny czas reakcji strony na WSZYSTKIE kliknięcia i interakcje użytkownika w trakcie całej sesji, raportując najgorsze opóźnienie przed wyrenderowaniem kolejnej klatki","Czasem potrzebnym na wpisanie adresu URL","Szybkością łącza internetowego","Liczbą klatek na sekundę w grach"]'::jsonb, 0, 'INP ocenia responsywność interfejsu w całym cyklu życia strony, wymuszając nieblokowanie wątku głównego długimi zadaniami (Long Tasks). Dobry wynik to poniżej 200 ms.', 'hard', 20),
(483, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Co mierzy wskaźnik CLS (Cumulative Layout Shift) i jak go zminimalizować?', null, 'single-choice', '["Mierzy niespodziewane przesunięcia elementów na ekranie podczas ładowania strony (skakanie treści); minimalizuje się go, rezerwując z góry wymiary w CSS (width, height, aspect-ratio) dla obrazów i reklam","Czas kompresji plików CSS","Liczbę zapytań SQL","Poziom kontrastu czcionek"]'::jsonb, 0, 'CLS powoduje frustrację, gdy użytkownik próbuje coś kliknąć, a treść nagle przeskakuje pod palcem. Dobry wynik to poniżej 0.1.', 'medium', 15),
(484, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest Długie Zadanie (Long Task) w profilowaniu wydajności JavaScript?', null, 'single-choice', '["Każdym zadaniem wykonującym się na głównym wątku przez ponad 50 milisekund, co blokuje pętlę zdarzeń i powoduje odczuwalne zamrożenie reakcji na kliknięcia i animacji","Zadaniem trwającym ponad tydzień w kalendarzu Jira","Pobieraniem pliku o wadze 1 GB","Kompilacją TypeScript trwającą 2 minuty"]'::jsonb, 0, 'Każdy blok kodu JS trwający >50ms kradnie czas renderowania klatki i opóźnia obsługę wejścia użytkownika.', 'medium', 15),
(485, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy nowa metoda scheduler.yield() wprowadzona w przeglądarkach w 2024 roku?', null, 'single-choice', '["Pozwala na eleganckie, asynchroniczne przerwanie długiego zadania (Long Task) i oddanie kontroli pętli zdarzeń, aby przeglądarka mogła wyrenderować klatkę i obsłużyć kliknięcia, po czym automatycznie wznawia zadanie","Do zamykania karty","Do zatrzymania pętli nieskończonej","Do restartu serwera node"]'::jsonb, 0, 'scheduler.yield() to nowoczesny standard dzielenia ciężkich operacji w wątku głównym na mniejsze porcje bez używania archaicznego setTimeout(fn, 0).', 'hard', 20),
(486, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Dlaczego animacje w JavaScript należy realizować za pomocą requestAnimationFrame() zamiast setInterval()?', null, 'single-choice', '["rAF synchronizuje wywołanie z częstotliwością odświeżania monitora (np. 60Hz, 120Hz V-Sync) i automatycznie pauzuje obliczenia, gdy karta przeglądarki jest w tle, oszczędzając baterię i GPU","rAF działa szybciej w Node.js","setInterval ma limit do 10 klatek","rAF nie zużywa pamięci RAM"]'::jsonb, 0, 'requestAnimationFrame pozwala uniknąć zjawiska tzw. tearingu i gubienia klatek, idealnie dopasowując się do cyklu odświeżania ekranu.', 'easy', 10),
(487, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy OffscreenCanvas API?', null, 'single-choice', '["Umożliwia renderowanie grafiki na płótnie Canvas w tle wewnątrz Web Workera, uwalniając wątek główny od ciężkich operacji rysowania pikseli i geometrii 2D/3D","Do robienia zrzutów ekranu","Do ukrywania rysunków za pomocą CSS","Do drukowania na drukarce"]'::jsonb, 0, 'Dzięki OffscreenCanvas cała pętla gry lub wizualizacji WebGL może działać w osobnym wątku roboczym bez spadku płynności UI.', 'hard', 20),
(488, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jaka jest różnica między grafiką Canvas (pikselowa/rastrowa) a formatem SVG (wektorowa)?', null, 'single-choice', '["Canvas operuje na siatce pikseli (idealna do gier i setek tysięcy cząsteczek bez obciążania DOM), a SVG to obiekty wektorowe z własnymi węzłami w drzewie DOM (doskonałe do skalowalnych ikon, wykresów i stylizacji CSS)","SVG nie może mieć kolorów","Canvas nie działa na telefonach","Nie ma żadnej różnicy"]'::jsonb, 0, '10 000 węzłów SVG zamrozi przeglądarkę (przeciążenie DOM), podczas gdy Canvas bez problemu narysuje miliony pikseli na sekundę.', 'easy', 10),
(489, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest WebGPU w porównaniu do klasycznego WebGL?', null, 'single-choice', '["Nowoczesnym standardem grafiki i obliczeń ogólnego przeznaczenia (Compute Shaders) w przeglądarce, zaprojektowanym od zera dla współczesnych architektur GPU (Vulkan, Metal, DirectX 12) z drastycznie mniejszym narzutem CPU","Nową wersją CSS","Wtyczką firmy Nvidia","Algorytmem kompresji wideo"]'::jsonb, 0, 'WebGPU zastępuje przestarzały model OpenGL/WebGL, odblokowując m.in. akcelerację lokalnych modeli AI (np. WebLLM) i symulacji fizycznych w przeglądarce.', 'hard', 20),
(490, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy Web Audio API w przeglądarce?', null, 'single-choice', '["Do zaawansowanej syntezy, miksowania i cyfrowego przetwarzania dźwięku w czasie rzeczywistym za pomocą węzłów audio (AudioNodes), filtrów i analizatorów częstotliwości FFT","Tylko do odtworzenia prostego pliku mp3","Do nagrywania rozmów telefonicznych","Do rozpoznawania mowy przez mikrofon"]'::jsonb, 0, 'Web Audio API to modułowy system węzłów audio zdolny do syntezy dźwięku przestrzennego 3D, generowania efektów, pogłosów i analizy widma dźwiękowego w czasie rzeczywistym.', 'medium', 15),
(491, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy atrybut Subresource Integrity (SRI: integrity="sha384-...") w tagu <script>?', null, 'single-choice', '["Weryfikuje sumę kontrolną (kryptograficzny hash) pobieranego z zewnętrznego CDN pliku; jeśli plik na obcym serwerze zostanie zmodyfikowany przez hakera, przeglądarka odmówi jego wykonania","Przyspiesza pobieranie pliku przez CDN","Szyfruje połączenie z serwerem","Zapewnia zgodność z urządzeniami Apple"]'::jsonb, 0, 'SRI chroni aplikację przed atakami typu Supply Chain na zewnętrzne sieci CDN, gwarantując, że kod w pliku nie został zmieniony ani o jeden znak.', 'medium', 15),
(492, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest standard Trusted Types w przeglądarkach?', null, 'single-choice', '["Mechanizmem obronnym, który blokuje przypisywanie zwykłych surowych stringów do niebezpiecznych miejsc w DOM (tzw. Injection Sinks: innerHTML, document.write), wymagając przekazania bezpiecznego obiektu zweryfikowanego przez dedykowaną politykę","Typami danych w TypeScript","Certyfikatem strony www","Wymuszeniem logowania dwuskładnikowego"]'::jsonb, 0, 'Trusted Types eliminuje błędy DOM XSS u źródła, uniemożliwiając przypadkowe przekazanie niezweryfikowanego tekstu do niebezpiecznych właściwości DOM.', 'hard', 20),
(493, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy nagłówek Permissions-Policy (dawniej Feature-Policy)?', null, 'single-choice', '["Umożliwia witrynie jawne włączenie lub zablokowanie dostępu do określonych funkcji sprzętowych i wrażliwych API przeglądarki (kamera, mikrofon, geolokalizacja) dla samej siebie oraz osadzonych ramek iframe","Do zarządzania uprawnieniami w bazie danych","Do ustawiania haseł użytkowników","Do blokowania reklam"]'::jsonb, 0, 'Permissions-Policy pozwala administratorowi strony zabronić osadzonym reklamom lub ramkom iframe używania kamery czy geolokalizacji.', 'medium', 15),
(494, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Dlaczego nagłówek Cross-Origin-Opener-Policy (COOP) oraz Cross-Origin-Embedder-Policy (COEP) jest wymagany do działania SharedArrayBuffer?', null, 'single-choice', '["Zapewnia pełną izolację pamięci procesu przeglądarki (Cross-Origin Isolation), uniemożliwiając ataki typu Spectre/Meltdown polegające na kradzieży danych z pamięci podręcznej przez pomiary czasowe","Wymusza szyfrowanie dysków","Zabezpiecza przed wirusami w plikach PDF","Jest to wymóg prawny RODO"]'::jsonb, 0, 'Po odkryciu luk Spectre przeglądarki tymczasowo wyłączyły SharedArrayBuffer. Przywrócono go dopiero pod rygorem pełnej izolacji pochodzenia przez nagłówki COOP i COEP.', 'hard', 20),
(495, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak zapobiec atakom typu Clickjacking na własną witrynę?', null, 'single-choice', '["Stosując nagłówek Content-Security-Policy: frame-ancestors ''none'' (lub nagłówek X-Frame-Options: DENY), uniemożliwiając osadzenie witryny w przezroczystej ramce iframe na obcej domenie","Blokując prawy przycisk myszy w JS","Wyłączając kursor myszy na stronie","Dodając znak wodny na obrazkach"]'::jsonb, 0, 'Clickjacking polega na osadzeniu ofiary w niewidocznej ramce iframe pod przyciskiem "Wygraj nagrodę". frame-ancestors ''none'' całkowicie blokuje osadzanie strony w ramkach.', 'medium', 15),
(496, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Jak działa kompresja binarnego transferu za pomocą formatów Protocol Buffers (protobuf) lub MessagePack w porównaniu do tradycyjnego JSON?', null, 'single-choice', '["Kodują dane w gęstym, binarnym formacie o znacznie mniejszym rozmiarze ładunku (payload) i wielokrotnie szybszym czasie serializacji/deserializacji przez procesor","Zamieniają dane w plik graficzny JPEG","Wymagają instalacji karty graficznej","To zamienniki dla plików CSS"]'::jsonb, 0, 'JSON to tekst czytelny dla człowieka z dużym narzutem parsowania. Formaty binarne (jak protobuf) drastycznie redukują czas transferu sieciowego i zużycie CPU.', 'medium', 15),
(497, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy propozycja Temporal API (TC39 Stage 3), która docelowo ma zastąpić przestarzały obiekt Date?', null, 'single-choice', '["Dostarcza nowoczesnego, w pełni niezmiennego (immutable), bezpiecznego i uwzględniającego strefy czasowe systemu operacji na datach, godzinach i kalendarzach bez historycznych błędów obiektu Date","Do manipulacji czasem w grach komputerowych","Do podróży w czasie w gicie","Do przyspieszania zegara procesora"]'::jsonb, 0, 'Obiekt Date z 1995 roku jest mutowalny, indeksuje miesiące od zera (0-11) i źle radzi sobie ze strefami czasowymi. Temporal API rozwiązuje wszystkie te problemy.', 'medium', 15),
(498, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Czym jest kompilacja Ahead-Of-Time (AOT) w porównaniu do Just-In-Time (JIT)?', null, 'single-choice', '["AOT tłumaczy kod wysokiego poziomu na kod maszynowy lub zoptymalizowany format w fazie budowania aplikacji przed jej uruchomieniem, zapewniając natychmiastowy czas startu bez narzutu kompilatora w runtime","AOT kompiluje kod po zakończeniu programu","AOT działa tylko w konsoli deweloperskiej","To synonimy"]'::jsonb, 0, 'Kompilacja AOT redukuje czas pierwszego uruchomienia (cold start) i zmniejsza zużycie pamięci w runtime kosztem dłuższego czasu budowania projektu.', 'medium', 15),
(499, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Do czego służy API view transitions (document.startViewTransition)?', null, 'single-choice', '["Umożliwia tworzenie płynnych, animowanych przejść między różnymi widokami lub stanami interfejsu (zarówno w SPA, jak i tradycyjnych MPA) przy minimalnym wysiłku programisty","Do zmiany rozdzielczości ekranu","Do generowania plików PDF z widoku","Do przełączania zakładek w przeglądarce"]'::jsonb, 0, 'View Transitions API automatycznie przechwytuje migawki starego i nowego stanu DOM i tworzy sprzętowo akcelerowane animacje przejścia.', 'medium', 15),
(500, 10, 'Zaawansowany JS, Optymalizacja i Narzędzia', 'Gratulacje dotarcia do pytania 500! Jakie podejście wyróżnia prawdziwego eksperta i architekta JavaScript?', null, 'single-choice', '["Głębokie zrozumienie fundamentów języka, mechanizmów silnika i przeglądarki, pragmatyzm w doborze narzędzi oraz priorytetowe traktowanie wygody użytkownika (UX) i czystości kodu","Ślepe podążanie za każdą nową modą i biblioteką","Przepisywanie całego projektu co 2 miesiące","Pisanie jak najbardziej skomplikowanego kodu"]'::jsonb, 0, 'Mistrzostwo w JavaScript to połączenie solidnej wiedzy technicznej z umiejętnością tworzenia niezawodnych, skalowalnych i przyjaznych dla użytkownika aplikacji.', 'easy', 25)
on conflict (id) do update set
  unit_id=excluded.unit_id, unit_title=excluded.unit_title, question=excluded.question,
  code_snippet=excluded.code_snippet, question_type=excluded.question_type, options=excluded.options,
  correct_index=excluded.correct_index, explanation=excluded.explanation, difficulty=excluded.difficulty, points=excluded.points;

alter table public.duels
  add column if not exists question_ids integer[] not null default '{}',
  add column if not exists current_round integer not null default 0,
  add column if not exists challenger_answers jsonb not null default '{}'::jsonb,
  add column if not exists opponent_answers jsonb not null default '{}'::jsonb,
  add column if not exists started_at timestamptz,
  add column if not exists round_started_at timestamptz;

alter table public.duel_question_bank enable row level security;
revoke all on public.duel_question_bank from anon, authenticated;

create or replace function public.create_duel(p_opponent_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  if p_opponent_id = auth.uid() then raise exception 'Cannot challenge yourself'; end if;
  if not exists (select 1 from public.profiles where id = p_opponent_id) then raise exception 'Opponent not found'; end if;
  insert into public.duels(challenger_id, opponent_id, status)
  values(auth.uid(), p_opponent_id, 'pending') returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.respond_to_duel(p_duel_id uuid, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare v_duel public.duels%rowtype; v_ids integer[];
begin
  select * into v_duel from public.duels where id=p_duel_id for update;
  if not found then raise exception 'Duel not found'; end if;
  if auth.uid() is null or auth.uid() <> v_duel.opponent_id then raise exception 'Only the invited player can respond'; end if;
  if v_duel.status <> 'pending' then raise exception 'Duel is no longer pending'; end if;
  if not p_accept then
    update public.duels set status='declined' where id=p_duel_id;
    return jsonb_build_object('id',p_duel_id,'status','declined');
  end if;
  select array_agg(id) into v_ids from (
    select id from public.duel_question_bank order by random() limit 5
  ) q;
  if coalesce(array_length(v_ids,1),0) <> 5 then raise exception 'Question bank is not ready'; end if;
  update public.duels set status='active', question_ids=v_ids, current_round=0,
    challenger_answers='{}'::jsonb, opponent_answers='{}'::jsonb,
    challenger_score=0, opponent_score=0, started_at=now(), round_started_at=now()
  where id=p_duel_id;
  return public.get_duel_state(p_duel_id);
end;
$$;

create or replace function public.submit_duel_answer(p_duel_id uuid, p_answer_index integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_duel public.duels%rowtype; v_qid integer; v_correct integer; v_points integer;
  v_round_key text; v_is_correct boolean; v_answers jsonb; v_both boolean;
begin
  select * into v_duel from public.duels where id=p_duel_id for update;
  if not found then raise exception 'Duel not found'; end if;
  if auth.uid() is null or auth.uid() not in (v_duel.challenger_id, v_duel.opponent_id) then raise exception 'Not a participant'; end if;
  if v_duel.status <> 'active' then raise exception 'Duel is not active'; end if;
  if v_duel.round_started_at is not null and now() >= v_duel.round_started_at + interval '15 seconds' then
    return public.advance_duel_timeout(p_duel_id);
  end if;
  if v_duel.current_round < 0 or v_duel.current_round >= array_length(v_duel.question_ids,1) then raise exception 'No active round'; end if;
  v_qid := v_duel.question_ids[v_duel.current_round+1];
  select correct_index, points into v_correct, v_points from public.duel_question_bank where id=v_qid;
  if p_answer_index is null or p_answer_index < 0 or p_answer_index >= (select jsonb_array_length(options) from public.duel_question_bank where id=v_qid) then
    raise exception 'Invalid answer';
  end if;
  v_round_key := v_duel.current_round::text;
  if auth.uid() = v_duel.challenger_id then
    v_answers := v_duel.challenger_answers;
  else
    v_answers := v_duel.opponent_answers;
  end if;
  if v_answers ? v_round_key then raise exception 'Already answered this round'; end if;
  v_is_correct := p_answer_index = v_correct;
  if auth.uid() = v_duel.challenger_id then
    update public.duels set challenger_answers=challenger_answers || jsonb_build_object(v_round_key,
      jsonb_build_object('answer_index',p_answer_index,'correct',v_is_correct,'answered_at',now())),
      challenger_score=challenger_score + case when v_is_correct then v_points else 0 end
    where id=p_duel_id returning * into v_duel;
  else
    update public.duels set opponent_answers=opponent_answers || jsonb_build_object(v_round_key,
      jsonb_build_object('answer_index',p_answer_index,'correct',v_is_correct,'answered_at',now())),
      opponent_score=opponent_score + case when v_is_correct then v_points else 0 end
    where id=p_duel_id returning * into v_duel;
  end if;
  v_both := (v_duel.challenger_answers ? v_round_key) and (v_duel.opponent_answers ? v_round_key);
  if v_both then
    if v_duel.current_round + 1 >= array_length(v_duel.question_ids,1) then
      update public.duels set status='completed',
        winner_id=case when challenger_score > opponent_score then challenger_id
                       when opponent_score > challenger_score then opponent_id else null end,
        completed_at=now()
      where id=p_duel_id;
    else
      update public.duels set current_round=current_round+1, round_started_at=now() where id=p_duel_id;
    end if;
  end if;
  return public.get_duel_state(p_duel_id);
end;
$$;

create or replace function public.get_duel_state(p_duel_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare v_duel public.duels%rowtype; v_q jsonb; v_round_key text;
begin
  select * into v_duel from public.duels where id=p_duel_id;
  if not found then raise exception 'Duel not found'; end if;
  if auth.uid() is null or auth.uid() not in (v_duel.challenger_id, v_duel.opponent_id) then raise exception 'Not a participant'; end if;
  v_round_key := v_duel.current_round::text;
  if v_duel.status='active' and v_duel.current_round < array_length(v_duel.question_ids,1) then
    select jsonb_build_object(
      'id',id,'unit_id',unit_id,'unit_title',unit_title,'question',question,
      'code_snippet',code_snippet,'type',question_type,'options',options,
      'explanation',explanation,'difficulty',difficulty,'points',points
    ) into v_q from public.duel_question_bank where id=v_duel.question_ids[v_duel.current_round+1];
  else v_q := null; end if;
  return jsonb_build_object(
    'id',v_duel.id,'status',v_duel.status,'challenger_id',v_duel.challenger_id,
    'opponent_id',v_duel.opponent_id,'challenger_score',v_duel.challenger_score,
    'opponent_score',v_duel.opponent_score,'winner_id',v_duel.winner_id,
    'current_round',v_duel.current_round,'round_count',coalesce(array_length(v_duel.question_ids,1),0),
    'round_started_at',v_duel.round_started_at,'completed_at',v_duel.completed_at,'question',v_q,
    'my_answer',case when auth.uid()=v_duel.challenger_id then v_duel.challenger_answers->v_round_key else v_duel.opponent_answers->v_round_key end,
    'opponent_answered',case when auth.uid()=v_duel.challenger_id then v_duel.opponent_answers ? v_round_key else v_duel.challenger_answers ? v_round_key end
  );
end;
$$;

revoke all on function public.create_duel(uuid) from public, anon;
grant execute on function public.create_duel(uuid) to authenticated;
revoke all on function public.respond_to_duel(uuid, boolean) from public, anon;
grant execute on function public.respond_to_duel(uuid, boolean) to authenticated;
revoke all on function public.submit_duel_answer(uuid, integer) from public, anon;
grant execute on function public.submit_duel_answer(uuid, integer) to authenticated;

create or replace function public.advance_duel_timeout(p_duel_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $
declare v_duel public.duels%rowtype; v_key text;
begin
  select * into v_duel from public.duels where id=p_duel_id for update;
  if not found then raise exception 'Duel not found'; end if;
  if auth.uid() is null or auth.uid() not in (v_duel.challenger_id, v_duel.opponent_id) then raise exception 'Not a participant'; end if;
  if v_duel.status <> 'active' then return public.get_duel_state(p_duel_id); end if;
  if v_duel.round_started_at is null or now() < v_duel.round_started_at + interval '15 seconds' then
    return public.get_duel_state(p_duel_id);
  end if;
  v_key := v_duel.current_round::text;
  if not (v_duel.challenger_answers ? v_key) then
    update public.duels set challenger_answers=challenger_answers || jsonb_build_object(v_key,
      jsonb_build_object('answer_index',-1,'correct',false,'answered_at',now()))
    where id=p_duel_id;
  end if;
  if not (v_duel.opponent_answers ? v_key) then
    update public.duels set opponent_answers=opponent_answers || jsonb_build_object(v_key,
      jsonb_build_object('answer_index',-1,'correct',false,'answered_at',now()))
    where id=p_duel_id;
  end if;
  select * into v_duel from public.duels where id=p_duel_id;
  if v_duel.current_round + 1 >= array_length(v_duel.question_ids,1) then
    update public.duels set status='completed',
      winner_id=case when challenger_score > opponent_score then challenger_id
                     when opponent_score > challenger_score then opponent_id else null end,
      completed_at=now()
    where id=p_duel_id;
  else
    update public.duels set current_round=current_round+1, round_started_at=now() where id=p_duel_id;
  end if;
  return public.get_duel_state(p_duel_id);
end;
$;

revoke all on function public.get_duel_state(uuid) from public, anon;
grant execute on function public.get_duel_state(uuid) to authenticated;
revoke all on function public.advance_duel_timeout(uuid) from public, anon;
grant execute on function public.advance_duel_timeout(uuid) to authenticated;
